/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020318-3","meetingId":"h14-c-budget","date":"2002年3月18日","dateIso":"2002-03-18","committee":"予算特別委員会","time":"午前１０時０７分～午後６時１８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を185件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１４年度品川区一般会計予算","agenda":"平成１４年度品川区一般会計予算","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"といいますのは、品川区の公金を使っている意識とか、それから品川区の職員と同時に教員ですから、そういう人としてのルールのあり方とか、そういう最も基本的なベースが欠けているのではないかと思います。そこでプラン２１も大変努力しておりますけれども、公金使用という観点とか、それから品川区の職員としての意識が非常に欠如しているという感じがするんですがどうでしょうかということが一つ。","respondent":"鷹倉庶務課長","answer":"それで、事務主事会ともいろいろ連絡等しているわけですけれども、かなりベテランの者がブロック制みたいなものをつくりながら、お互いにベテランが弱いところを補強していくと、こういうふうにしていったらどうかというようなことを今考えていますし。","voiceIndex":4,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"ちなみに例えば、区議会事務局とか監査委員事務局は一度も指摘されたことがないんですよ。だから、内部の努力、それから今いろいろおっしゃった、それはもうやってくださって当然なんですよ。ですから、一つの考え方をお聞かせください。今はできません、法律、それはわかっているんだけれども、でも、職員の人事権、特に教員の人事権のあり方についての見解をお聞かせください。お願いいたします。","respondent":"青木指導課長","answer":"今後も品川区の教員として、それぞれの学校の教育のみならず、そうした管理面でも強く意識させるように指導してまいりたいというふうに考えております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"当然、東京都の教育委員会とか連携しながら、それからもう一つ踏み越えて、文部科学省とか連携しながら、受け入れるほうも、例えば一つの案としては、職員の防災待機寮があいているわけですから、ああいうところを有効活用して、全国から優秀な方が来た場合には、どうぞここをお使いくださいよというふうな体制を整備してでもいいから、そういうやる気のある教員。","respondent":"青木指導課長","answer":"私もその面接の中で、一人ひとりの新たな教員の抱負などを聞きますと、やはり品川区で今、この教育改革にぜひ私も取り組みたいという強い情熱を示していますので、そういう教員をぜひ新規だけでなく、またよその地区からの転入者もそうした人たちが目立ち始めましたので。","voiceIndex":8,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"提案","question":"私たちの提案としては、それをもっとさらに踏み込んで、今、例えばある品川区のいろいろな施設を有効利用しながら、あいている施設ですね、例えば、沖縄からこういうふうなことをしたいという先生がいらっしゃって、それが東京都の職員採用試験に合格をなさった方が優先的にそういうようなところに住んでいただくとか、要するに、今言った指導課長の話もそうなんですが。","respondent":"指田教育次長","answer":"今後も、そういったところでもって問題点をお話しする機会を得ながら、機会あるごとに問題点については対応していきたい、お話ししていきたいというふうに思っています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"提案","question":"例えば、人のものをとってはいけないとか、人を殺してはいけないとか、そういう非常に極めて当たり前なところが、例えば、国語と算数というようなものでは教えられない、最も基本的なベースとなるものを提示していくべきではないかというふうな一応の考え方になっているんですけれども、何でも自由という、まあ、何でも自由でいいという、そういう価値観の中では。","respondent":"青木指導課長","answer":"いよいよ４月から完全学校週５日制が実施されます。今、委員がご指摘されましたように、学校週５日制の本来の趣旨というものは、学校、家庭、地域社会が相互に連携しつつ、子どもたちのまさに生きる力をはぐくむというところにあるかと思います。","voiceIndex":12,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"要するに、一番そこで情報が集まって、そこに聞けば、じゃ、どういうふうなメニューがありますよ、こういうようなものが使えますよ、それから区内のこういうふうな連携がとれますよということを、例えば今言ったＰＴＡの皆さんとか、各地域の皆さんが相談しに行ったときには、すぐに答えが返ってくるような仕組みをつくっていったほうが、おそらく今言った、生きる力をはぐくむ。","respondent":"青木指導課長","answer":"現在、それぞれの地域やＰＴＡの活動が一つ、情報としてまとめられるような形で、これから私たちは収集し、そして準備をしていかなければいけないというふうに考えておりますので、その点につきましては至急検討して対応してまいりたいというふうに考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そういうふうなものをどうして、ここで有効活用するためにスキームがつくれないんですかということを聞きましたので、改めて答弁をお願いしたいのと、それから、区議会の話といいましょうかね、議員がそこに行って話をするということではなくて、議員もそれぞれの人脈を持っているわけですから、そういうふうな中の力も総合しながら、この問題に取り組んでいっていただきたいと思いますが。","respondent":"青木指導課長","answer":"そういう意味で、今ご指摘されました区役所の中のそれぞれのセクションとまさに連携をとって、子どもたちの土曜日を使った、まさに生きる力の育成に町内の力を合わせて進めていきたいというふうに考えております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"今の伊藤委員と重なりますが、初めに完全学校週５日制の実施について、二つ目には３０３ページの生徒指導対策費に当たるのかどうか、ちょっとわからないんですが、金銭教育についてお伺いをいたします。もし時間がありましたら、３２３ページの家庭教育支援ネットワーク事業についてお尋ねをいたします。","respondent":"富田教育改革担当課長、青木指導課長","answer":"初めに、すまいるスクールの今後の拡大の予定ですけれども、大変、第二延山のほうが好評ですので、３校新規に１４年度は実施するという方向を出したわけですが、今後の予定ですけれども、各ブロック、地域のバランス。学力低下についてのお尋ねですが、これはせんだっての本会議でもお答えしておりますように、私どもは、基礎・基本を徹底的に教えるということにポイントを置いて指導していきたいというふうに考えております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"嶋委員","kind":"確認","question":"基礎学力の、いわゆる向上ということで、すべての中学校でこの春から第１、第３土曜日の午前中、３時間程度、各校の教室を利用して、１クラス２０人程度で授業の補充として国語、数学、英語などを勉強する。そういう意味では、ほんとに５日制にする意義というか、内容をもう一度はっきり確認したいと思いますので、もう一度お話をいただけますでしょうか。","respondent":"青木指導課長","answer":"しかし、それぞれの親御さんにとっては、やはり学習内容が減らされたというようなご認識で、大変ご心配されているという、そうした背景もあることは私も承知していますが、やはり土日で学力を補充するという考えではなくて、ほかの、まさに平日の日に学校のほうの指導内容。","voiceIndex":22,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問","question":"私もそれに大賛成です。私が、ちょっと地方の子どものアンケートなんですが、中学生では５日制が大変よいというのが７０％、休みの日にしたいことのトップは友達と遊ぶがやはり７０％、のんびり過ごすが６９％、テレビを見る４９％、家族と買い物や旅行３７％、家で学習する３５％と、地方ではこういうアンケートをとっているようですが、品川区においてはどのようにこれを実施されていますでしょうか。","respondent":"青木指導課長","answer":"そうした話を聞きますと、やはり今委員がご指摘されたような、そうした反応は子どもたちの意識として、それぞれの学校は持ってありますし、私たちもそうしたことを、報告を受けておりますので、そうした子どもの実態というのは把握しています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひまた何かの機会にとっていただきたいと思います。それで、ＮＨＫではこの土曜日に関していわゆる特別番組を、これから番組編成をしていくようですが、品川区としてはケーブルテレビにどのような働きをかけて、もしこれをアピールしたい番組がありましたら教えていただきたいと思います。","respondent":"青木指導課長、山田広報広聴課長","answer":"ケーブルテレビのほうの内容ですけれども、今広報広聴課長がまいりましたので、かわりたいと思います。来年度は中学校の放映ということを準備しております。すまいるスクールも大変好評ですので、特別番組なりで教育改革ということで取り上げたいというふうに、今準備をしています。","voiceIndex":26,"id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、子ども向けの番組をまた楽しみにしておりますので、よろしくお願いいたします。最後に、金銭教育についてお伺いをさせていただきたいと思います。やはり現在、品川区の小・中学校で、お金の使い方がどういう形で、どんなときに、こういう、お金の、お小遣いの使い方とか、きっと遠足とか修学旅行かと思いますが、どういうようなときにこういう教育をされているのかお聞きしたいと思います。","respondent":"青木指導課長","answer":"確かに、最近の子どもたちにつきましては、お金の使い方ということは、大分いろいろと問題が出ておりますので、やはりそうした場をとらえて、きめの細かい指導をしていきたいというふうに考えております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"嶋委員","kind":"質問","question":"今は、もうほんとにカード破産とか、キャッチセールスなど、ほんとに若者を中心にしたいわゆる金銭トラブルが後を絶たない現状です。その原因の一つに金銭に関する教育をしっかりされていないというか、受けていないというのが今現在言われております。こういうものをやっぱりしっかりとした時間をとって、学校、教育現場では教育をしていってほしいなと思いますが、いかがでしょうか。","respondent":"青木指導課長","answer":"この大きな社会の変化の中で、金融、金銭にかかわるそうした対応能力というものをそれぞれの学年、発達段階に応じて指導してまいりたいというふうに考えております。","voiceIndex":31,"id":"exchange-013"},{"speaker":"嶋委員","kind":"質問","question":"やっぱり放置していけば、取り返しのつかない大変な問題になっていく内容ですので、品川区で、今までは、そういう専門家、まあ銀行マンとかいろいろな方たちを招いての、先生への、教師へのアプローチみたいなものが今までとか、また児童に対してでもいいんですけれども、そういうのを今までやったことがあるのでしょうか、ちょっとお聞きしたいと思います。","respondent":"青木指導課長","answer":"学校だけではできませんので、家庭でやはりお金の使い方などもよくお父さんやお母さんに指導してもらいなさいというような指導も含めて、学校と家庭の連携を通して、金銭教育を充実させていきたいというふうに考えております。","voiceIndex":33,"id":"exchange-014"},{"speaker":"嶋委員","kind":"質問・要望","question":"家庭も、うちはもちろん親が責任を持ってお金の使い方を教えていかなくてはならないんですけれども、やっぱり今、こういう複雑な経済状況においては、やはり家庭だけでは大変難しいかと思います。学校だけに責任を押しつけるつもりはございませんが、やはりお金でできるもの、できないものを明確にし、上手にお金の使い方を教えていただきたいと思いますが、いかがでしょうか。","respondent":"青木指導課長","answer":"特に、お金の使い方を自分で計画的にできるようにするためには、やはりかなり経験というものも必要だと思いますので、認識、知的な指導だけではなくて、具体的な使い方も含めて、今後も家庭と連携をとりながら、指導してまいりたいというふうに考えております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"嶋委員","kind":"質問","question":"これからもする予定がないのかどうか。今、親御さんも大変忙しくて、子どもの就学時健診には必ずついてくるというのが基本かと思います。絶好のチャンスだと思いますが、いかがでしょうか。","respondent":"上川内生涯学習課長","answer":"１４年度から乳幼児を持つ親の子育て若葉マーク講座ということで、就学前の子育てに関する相談、それを児童センターの幼児クラブ等を中心にして行っていくことに計画をしております。","voiceIndex":39,"id":"exchange-016"},{"speaker":"嶋委員","kind":"質問","question":"児童センターではなくて、学校の就学時健診ということで、今ちょっとお聞きをしたのですが。","respondent":"上川内生涯学習課長","answer":"就学時健診というところでは今後検討してまいりますが、その前の段階のところではそういう予定を組んでおります。","voiceIndex":41,"id":"exchange-017"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひよろしくお願いをしたいと思います。それで、いわゆる思春期の子どもを持つ親への講習会も２科目、８回というふうに今回予算化をされておりますが、これについて、それとあと子育てに関する地域のネットワークづくり交流２回ということなので、済みません、教えていただきたいと思います。","respondent":"上川内生涯学習課長","answer":"家庭教育の支援のネットワークのことをまず最初に言いますが、２３日の品川区の社会教育委員会議の提言、それから旧文部省の教育改革の会議のところでも、家庭の重要性、それから孤立した親たちの支援ということが大事だということで組んでおります。","voiceIndex":43,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、３０５ページのすまいるスクールに関してお尋ねをいたします。すまいるスクール、開設して７カ月がたちました。暑い夏がやってくるので、私はぜひクーラーをつけてほしいなと思うので、その辺どうなっているのかなというのはお尋ねと、あと運営費のところでは、指導員の報酬が載っていますが、職員の体制と報酬の算定というか、その辺を教えていただきたいなと思います。よろしくお願いします。","respondent":"富田教育改革担当課長","answer":"スペースですが、すまいるスクール第二延山につきましては、幼稚園の跡施設ということで約４４０m2ほど、４室ございまして、ありますんですけれども、新規開設予定の学校はいずれも児童数が３００人程度の学校でございまして。","voiceIndex":47,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補助金のところは、独自の事業にということで、改修ということでついたということですけれども、これって今後も、これからも新しくすまいるを開設していく場合にも、都のほうから来る補助金があるのかどうか、その点が１点と、あとちょっとクーラーのところ、すごく喜んだんですが、ちょっとあんまり、最後のがよくわからなかったんですが、ぜひはっきりとお答えいただきたいのと。","respondent":"富田教育改革担当課長","answer":"初めに福祉改革補助金ですが、これは東京都の福祉局の補助事業でございまして、平成１２年度から実施されている事業ですので、この辺、福祉局の補助事業の展開を福祉局と相談しながら、補助事業が打ち切りになればこの補助金というのもなくなりますので。","voiceIndex":49,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"確認","question":"クーラーのことは、ちょっともう一回しつこいんですけれども、第二延山のすまいるスクールには既にあるという確認はいいのでしょうか。それで、今後三つの新しいところは検討していくということなのか、済みません、改めてちょっとそこが確認と、あと職員体制のところなんですけれども、人数はわかりました。どのくらいの報酬がいただけるのか、月に直すとどのくらいか、もしわかったら教えてください。","respondent":"富田教育改革担当課長","answer":"新規で入れた部分もありますということです。非常勤職員の報酬ですが、１３年度も教員免許のある部分については入れておりまして、指導助手と同じ単価、時給１,６００円ということで算定しております。指導補助員については今後決定してまいります。","voiceIndex":51,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"次に活動内容についてお伺いをしますけれども、安全確認、そして児童の把握のところがどうなっているのか、出席の点検がどうなっているのか、お伺いします。そういった面で、５時、６時までいるというのは、育ち盛りの子どもたち、おなかがすくことだろうなと思ったんですが、おやつについてどう考えていらっしゃるのか、お聞かせいただきたいと思います。","respondent":"富田教育改革担当課長","answer":"初めに職員の体制ですが、現在正規職員１名ですけれども、大変非常勤職員等と力を合わせながら実施運営してございまして、学校の校長先生、教頭先生等との連絡等もとり合いながら行っておりますので、専任職員１名で大丈夫だというふうに認識しております。","voiceIndex":53,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"提案","question":"障害児のこと、ちょっと今、とても何か冷たいなと。この点に関しても、もう一回お伺いしたいなと思います。安全確認のところですけれども、連絡帳がどう使われているのかというところをちょっとお伺いします。そういった面で、『すまいるスクール便り』の中身を、子どもを伝える中身にもうちょっと充実をしていただきたいのと、すまいるの保護者会の開催を提案したいんですけれども、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"保護者会のご質問でございましたが、すまいるスクールのほうでは説明会を開いておりまして、来年度すまいるスクール参加予定の方のための説明会も、３月中に開催する予定です。保護者会を開いていく考えはございません。","voiceIndex":55,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった中で、何が大事かといったら、品川区のプラン２１にも地域と家庭と学校の連携ってうたわれていますね。最後に一つだけぜひ聞いていただきたいのは、すまいるができることで、学童保育が吸収されてしまうのではないか、大変心配をされていらっしゃる方がいます。この点をぜひ考慮して、考えていっていただきたいなと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうから、プラン２１関連事業の部分について、基本的な部分の再確認をさせていただきたいと思います。そして、また土日の対応等々については、家庭、地域の力を活用するというお話がありましたけれども、現実の問題として、土曜、日曜の対応は何か具体的なものが出ているんですか。そしてもう一点、この５日制に対する教師の反応は今伝わっているところではどうでしょう。お聞かせください。","respondent":"青木指導課長","answer":"それから３点目ですが、学校の教員の５日制への取り組みに対しての意識ですが、１点目でご説明しましたように、土曜日がなくなる分、どのようにウイークデーで充実した教育活動をしていくのかということにつきましては、既にこの間、２年間にわたりまして移行措置ということで。","voiceIndex":59,"id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"そこで、これまでの形ですと、一つは学習をするグループ、学習派と言っているんですかね。その中で、じゃ、学力を、先ほどのお話のように、先生がしっかりそれについて準備をして、時数を確保しているから大丈夫なんだというお話ですけれども、果たしてこういう生きる力、ゆとりの中に、学力をどう取り込んでいくかというところについて何かお考えがあるようでしたら教えていただきたいと思います。","respondent":"上川内生涯学習課長、青木指導課長","answer":"それから１４年度から土曜日が全部お休みになるということで、校庭開放を全土曜日実施することになっております。例えば、習熟度別学習とか、教科担任制とか、そうした方法で取り組む中で、学力の基本的な定着というのを図ってまいりたいというふうに考えています。生きる力というのは非常に大きな概念です。","voiceIndex":61,"id":"exchange-026"},{"speaker":"原委員","kind":"質問","question":"そこで、中教審が学校週５日制についての中で、塾等について触れている部分があるんですね。月２回の学校週５日制を導入した段階では、休業土曜日について、通塾率、塾に通う率については大変大きな変化はないものの、今回の５日制を導入する際には、塾通いが増加するのではないかという懸念がある。ここの塾、あるいは補習等々については、教育委員会としてはどういうご見解をお持ちですか。","respondent":"青木指導課長","answer":"学校週５日制と塾通いの件ですけれども、学校週５日制が実施されることによって、通塾率が高まるのではないかという、そうした懸念というんですか、そうした問題点についても、私ども、手元にあります資料ですと、大きく、学校週５日制が実施されることによって。","voiceIndex":64,"id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"学力調査の件でちょっとお話をお伺いさせていただきたいんですが、今回の調査内容からしますと、自ら学び、自ら考える力などの生きる力の基礎としての思考力、判断力、表現力、問題解決能力などを加えたものととらえて調査をするという具体的な内容が出ておりますけれども、ではこの学力調査をどう今後の中で生かそうとされているのか、お考えを聞かせてください。","respondent":"青木指導課長","answer":"したがいまして、まず実態を把握し、そしてその結果それを指導法につなげる、そうしたねらいで行いたいというふうに考えております。","voiceIndex":66,"id":"exchange-028"},{"speaker":"原委員","kind":"意見","question":"そうしますと、今の考え方からすると、それでは、ここにも出ていますね、習熟度別学習というところに、学力の内容、今お話されたようなことをどうリンクさせていこうとしているかということなんですが。","respondent":"青木指導課長","answer":"そうした意味で、習熟度別の指導も一つの方法として、どのような成果があったかという分析の材料になるのではないかというふうに考えております。","voiceIndex":68,"id":"exchange-029"},{"speaker":"原委員","kind":"意見","question":"そうしますと、今の習熟度別学習の内容が学力の向上に役立てなければならないわけです。それには、先ほどもうちの政調会長がお話ししましたけれども、いい先生にいい形で品川区に来ていただいて、そしてそれにつなげていただくという努力が必要だと思うんですが、そこのところの習熟度別学習の内容と学力の向上について、もう少しお考えがあったらお聞かせください。","respondent":"青木指導課長","answer":"習熟度別学習というのは、児童・生徒一人ひとりの学力の習熟に応じて指導方法を工夫する、そうした指導法です。そういう意味で、個に応じた指導ということが前提になりますので、なかなか理解が十分にできないお子さんにとっては時間をかけてやります。","voiceIndex":70,"id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"いずれにしましても、ゆとり、生きる力、そういったものの中で、少しでも学力向上につなげるような形をつくっていかなければならないということですので、教師の方々のご努力は大変なものと思いますけれども、しっかりそれを続けてやっていただきたい。足りないところはうちのほうの会派の中で、プラン２１関連、出てくると思いますが、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-031"},{"speaker":"鶴委員","kind":"意見","question":"基礎学力に関連してお尋ねしたいんですが、施政方針でも教育改革の成果を検証するために、独自の調査票を用いて、児童・生徒の基礎学力調査を、小学校・中学校全校で実施するということですね。私、思うんですよ、品川区の教育委員会、私、今回のことで、学力低下は大丈夫かと心配している１人なんですが、結局、教育委員会、品川区の教育委員会としての基礎学力に対する見解というのはどういうことなのか。","respondent":"若月教育長","answer":"じゃ、基本とは何かということになると、これはまたちょっと別のことになりまして、今日は時間の関係でご説明できませんので、また折がありましたらお話をしますが、それでは品川区の子どもたちは今、基礎学力はどうなのかというご質問でありますけれども、中学校の、まあ。","voiceIndex":74,"id":"exchange-032"},{"speaker":"鶴委員","kind":"質問","question":"ある程度の基礎学力は、いろいろな見方によって違うんでしょうけれども、今の答弁のように、しかしながら、ある程度の基準というものがなければ、現場の先生たちを指導しようがないじゃないですか。何に基づいて基礎学力を、先ほど定着させるとかおっしゃったけど、何をもって、まあ、統一的押しつけはいけないけれども、あるレベルというものが必要じゃないですか。そこあたり、ちょっと聞きたいですね。","respondent":"若月教育長","answer":"これはとりもなおさず、学習指導要領の中に定められた学習の内容があります。それに基づいて各学校が指導もしておりますし、教員はそれに基づいたさまざまな測定方法、テストなどを用いて、基礎学力の定着度をはかっている。基本は学習指導要領にあるというふうにご理解ください。","voiceIndex":76,"id":"exchange-033"},{"speaker":"鶴委員","kind":"質問","question":"それじゃ、時間がないから１点聞きますが、今の小・中学校の品川区の児童の国語力というのはどうですか、読み書き含めて。全部１００点満点とれますか。","respondent":"若月教育長","answer":"したがって、子どもたちには、今の段階で精いっぱい力を出しているのか、いないのか、今子どもが持っているこの段階で、その子どもは十分に力を発揮できているのかどうなのか、そういう部分もやはり我々教師は見ていってあげなければならないだろう。","voiceIndex":78,"id":"exchange-034"},{"speaker":"本田委員","kind":"意見","question":"私からは２点。３０９ページの教材教具費、この中でピアノの維持管理についてお尋ねします。それから３３１ページの図書館経費の中で、乳幼児の図書普及、読書普及ですね、これに関してお尋ねします。１学校３台くらいあるような計算になるんですが、この維持管理というのはどのようにされているのか、まずお尋ねしたいと思います。","respondent":"久保田学務課長","answer":"小・中学校におけるピアノの維持管理ですけれども、まずピアノそれ自体の管理は、これは学校でやるわけですけれども、いわゆる調律については、私どもは年間を通じて委託契約しておりまして、年間に数回学校を訪れて。","voiceIndex":81,"id":"exchange-035"},{"speaker":"本田委員","kind":"質問","question":"素人ですから、私どもはよくわかりませんけれども、専門的な能力を持った方ですけれども、１８０台のピアノというのは、一番古いのでどのくらいもっているんでしょうか。学校でちょっと調子が違っているというふうに思っていても、なかなか調律の業者との兼ね合いとかいろいろあるんだろうと思うんですが、その辺はどうなっているんでしょうか。","respondent":"久保田学務課長","answer":"ただ、私ども、何回か調律の専門業者が来て、見ていただいて、修理不能だというようなことであれば、そういう報告を受けて、また新しく老朽取りかえというような考えも出てきますし、そういう形で業者との連携はやっているところです。","voiceIndex":83,"id":"exchange-036"},{"speaker":"本田委員","kind":"質問","question":"古いもので１０年と今聞きまして、あれ、随分新しく回転させているんだなと。それからアップライトについても、３０～４０年はちゃんとやればもつ。そういう点で音が乱れたということを言っておられましたが、古いもので１０年というと、新しいピアノが１８０台も品川区の小・中学校にそろっているんですか。もっと、２０年とか３０年とかたっているんじゃないですか。","respondent":"久保田学務課長","answer":"失礼いたしました。学校のピアノ、今資料がやっと出てまいりました。確かに古いものというので、私どもが今持っているやつで、平成年度に買ったものが大半です。一番古いのということでいきますと、昭和５８年ということですから２０年はまだたっていないというような状況です。","voiceIndex":85,"id":"exchange-037"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから今、１８０台、調律の予算を組んでおられますけれども、これを何とか古いのを新しく回転させなさいというのではなくて、学校の各校長の責任のもとに、音楽の先生方が中心になってピアノの維持管理をしているんだと思うんですが、業者とも十分タイアップしながら、維持管理というのはちゃんとするということが大事ではないかというふうに私は思っているんですよ。２,０００万円ぐらいするんでしょう。","respondent":"久保田学務課長","answer":"大変失礼いたしました。私、ちょっと見間違えまして、４８年が一番古いほうで、申しわけありません。大変失礼申し上げました。","voiceIndex":87,"id":"exchange-038"},{"speaker":"本田委員","kind":"提案","question":"それから図書館経費の、乳幼児の読書普及ですけれども、去年の二定の本会議で私、ブックスタートの導入をご提案しました。職員のそういう活動に対する予算はどこに組まれているんでしょうか。２,０００人の１歳半健診時にお子さんたちに、父兄に、保護者に、そういうことをやるというのは大変なことでして、一定の予算がなければこれはできないと思うんですけれども、どういうふうになっているんでしょうか。","respondent":"青山品川区保健センター所長","answer":"実は、保健所のほうで図書館の者が参って、１歳半健診のときに約１０分間ずつ話をしてくれているんですが、それについては特に予算というものではなく、職員が来てくれているという状況です。","voiceIndex":89,"id":"exchange-039"},{"speaker":"本田委員","kind":"質問","question":"このときは説明がありませんでしたね。たまたま所長が留守だったものですから担当の方にお聞きしたら、このところ品川区保健センターはそのような事業はやっていないというご回答を私、いただいたんですね。これは一体どういうことになっているんでしょうか。保健所と連携してやっているというんですが、荏原のほうとはやっているけれども、保健センターとはやっていないということなんですか。","respondent":"青山品川区保健センター所長","answer":"ただ、保健センターにつきましては、待ち合い場所に、絵本をたくさん置いておきまして、そこで保護者の方や関係する者が読み聞かせができるような態勢をとるという形で変わらせていただいております。","voiceIndex":91,"id":"exchange-040"},{"speaker":"本田委員","kind":"提案","question":"私は、４カ月の健診のときに絵本の大切さを教えてやるというブックスタートが、こういうやり方をどうでしょうかということを昨年提案したんですが、１歩譲って、１歳半健診のときにそれに通ずるような内容のものをやっていますという答弁だったものですから、それならまだいいなというふうに思っていたんですね。ところが品川区保健センターはやっていないと。","respondent":"志村品川図書館長","answer":"児童の、乳幼児の図書の普及ですけれども、申しわけありません。１歳６カ月健診については今答弁したとおり、荏原の保健所というんですか、旧の、今、品川区保健所になっていますけれども、そちらで今やってあります。","voiceIndex":93,"id":"exchange-041"},{"speaker":"本間委員","kind":"質問","question":"私のほうからは特にページは、あちこち飛びますので、完全学校週５日制に絡む諸問題についてということでお願いします。ある新聞では、子どもたちに週末をどう過ごさせるか、完全学校週５日制の実施を４月に控え、週末の活用について頭を痛める学校現場の悩みが、全日本中学校長会の調査で浮かび上がったということで、そのデータが出ております。この件につきましてのご見解をお尋ねします。","respondent":"上川内生涯学習課長","answer":"地域の子どもは地域のみんなで育てるということで、週５日制になって、私どものほうもＰＴＡの皆さんに校庭開放を全校、全土曜日を開放するようにこれからお願いしていったり、それから先ほども言いましたように、地域交流促進事業ということで。","voiceIndex":97,"id":"exchange-042"},{"speaker":"本間委員","kind":"質問","question":"「どうなる学力」という、ある新聞の記事の連載なんですけれども、その中には品川区の記事も含まれておりますが、ある地方自治体では、完全学校週５日制ということにつきまして、私立との差に加えて地方自治体でも学力に差が生じるのではないかという懸念する声が上がっています。それから、出ることではなくて、転入をする部分はどうなっているのかということ。教えてください。","respondent":"久保田学務課長、青木指導課長","answer":"それから平成１３年度が１６.６％、平成１４年度にまいりますと、これはまだ見込みですけれども１８.１％になるかと思います。教員のほうの異動の件ですが、これもせんだっての本会議でもご答弁させていただきましたように、確かに今、品川区は教育改革を進めております。","voiceIndex":99,"id":"exchange-043"},{"speaker":"本間委員","kind":"質問","question":"それで私は、前回の一般質問等でもお話をしたことがあるんですけれども、いわゆる学校が競争をしていく、それぞれの校長先生も大変苦労されて、努力をされている姿を最近よく見かけます。そこで、学校を地域が、あるいは親が、子どもが選ぶ場合の競争条件をいかにして、公平に足並みをそろえていくべきではないかということを前にも述べたことがあります。小学校、中学校、お願いします。","respondent":"鷹倉庶務課長","answer":"残っているのは、現在のところ３０校程度未実施ですけれども、今申し上げました意味ではＲＣ構造上、まあまあ大丈夫かなという見通しを持った形で残していると。したがいまして、今後この辺のところを参考に、校舎改築をしていくということになると思います。","voiceIndex":102,"id":"exchange-044"},{"speaker":"本間委員","kind":"質問","question":"まだ３０校ほど未実施だということですね。本年から学校の屋上緑化が始まりますね。その部分で、おそらく優先順位がついてくると思うんです。そうすると、耐震構造をクリアしていないところについては、屋上緑化の話はなかなか前向きな受けとめ方をされないわけでして、その辺も実はお聞きしたわけです。したがいまして、これからの見通しについてお尋ねします。","respondent":"鷹倉庶務課長","answer":"屋上緑化につきましては、新築のところは当然新しい都の条例のもとにやっていかなければいけない。これは当然のことです。従来のところを屋上緑化していく場合について、今ご指摘の耐震補強をしている部分、この辺のところを見きわめながら、屋上緑化をしていくです。","voiceIndex":104,"id":"exchange-045"},{"speaker":"本間委員","kind":"質問・要望","question":"それぞれ学校は、ほんとに一生懸命地域の皆さんとともに知恵を合わせ、力を出しながら、お互いに力を出しながら、今までとは違った学校づくり、地域に開かれた学校づくり、あるいは特色ある学校づくりに一生懸命取り組みを進めている状況の中で、外から見る方は、競争条件の一つとして、前提となる施設がばらばらではやはりいい施設のほうに目が向くんじゃないかという心配が実はいつもされるものですから。","respondent":"鷹倉庶務課長","answer":"運動場、校庭が狭いということの裏返しの質問かと思います。具体的には学校でできないのは浜川中、１校です。ここは３,７００m2ということで、ちょっと若干狭いのと、海浜公園が使いやすいこともございまして、ここ１校使用しています。","voiceIndex":106,"id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"１校でしたか。ない物ねだりはこれ以上無理だと思いますけれども、やはりそのようなことも競争条件の一つとして非常に未整備な部分だなと、しかし限られたスペースしかないもので同じようにはできないけれども、そうしたら、その次は便宜を図っていただきたいということになりますが、これからもひとつよろしくお願いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私からは、まず１項の教育総務費の中から安全衛生管理費関係だと思うんですが、それと２項で学校教育費の教職員健康管理費、それと３項で区立小学校ＰＴＡ連合会、それとジュニア・リーダー、その辺についてお聞きしたいと思います。最初にジュニア・リーダー教室についてお聞きしたいと思います。参加者は区内全域、平均化していらっしゃるのかどうか、その辺についてお答えをお願いしたいと思います。","respondent":"上川内生涯学習課長","answer":"ジュニア・リーダー教室、参加者状況ですが、小学生コースでは３会場、旗の台会場、五反田会場、南大井会場に分けてあります。７０名。中学生コースが１会場で８名。それから中学・高校生コースが１会場で２７名。区内全域の小・中学生を集めて実施しております。","voiceIndex":111,"id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"意見","question":"わかりました。大体それはわかるんですけれども、教室が終わった後に児童・生徒、どのように区の中でいろいろな協力体制をとっていらっしゃるのか、有効に生かしていらっしゃるのかを、ちょっとお答えいただけますか。","respondent":"上川内生涯学習課長","answer":"ジュニア・リーダー教室を終わった後といいますと、毎年募集しておりますが、高校３年生を卒業した方たちを主に対象としまして、卒業生たちはほとんどの方がジュニア・リーダーのカウンセラー、リーダーとしてのお兄さん、お姉さんという立場で。","voiceIndex":113,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"カウンセラーとして参加していただいているというのはわかりました。ただ、そうすると青少年対策地区委員会、この中でこういうジュニア・リーダーで育った方たちをどのように生かしていっていらっしゃるのか。実は私も子どものころ、小学生のときにジュニア・リーダーを受けました。その辺で、事業部の間でどうつながりを持って考えていらっしゃるのか、その辺をお答えいただきたいと思います。","respondent":"上川内生涯学習課長","answer":"それで、全区的にジュニア・リーダーの教室を開いて、卒業生たちを送り出しているわけですが、高校を卒業するまで残っている方が大体これで見ますと１～２名程度で、今小学校４年生からというふうになっていますけれども、その間に受験とかいろいろなものがございまして。","voiceIndex":115,"id":"exchange-050"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですからこの中でも、この運営委託は確か青少年委員会でやっていらっしゃる、青少年委員の方が受けているから、ちょっとその辺が矛盾するところがあるんですけれども、その方たちにまた再度復活を求めていけば、青少年委員の方は当然青少年対策地区委員会の方なんですから、そこにもう一回結びつけることができるんじゃないかと思うので、今後の活用をお願いしたいということで要望にします。","respondent":"長田地域活動課長","answer":"そういう意味からすれば、当然青少年委員会で実施をした事業、こういったノウハウを地域の地区委員会の中に持ち帰って、十分調整をして生かしていただくということは原則かと思います。ただ、いろいろな事情がありまして、参加の少ない地域があるのも事実です。","voiceIndex":117,"id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その日に、私もちょっとある会長さんからお声をかけていただいてお邪魔させていただいたんですが、教育長と教育次長、それから指導課長、３人、もっといらっしゃったのかもしれないんですが、私、お会いしたのは３人だったので、これ、指導課の管轄部分かと思っていたんですが、予算面で見ると生涯学習関係になるんですか。この中で研修会と学校の関係というのはどういうふうになってくるんでしょうか。","respondent":"上川内生涯学習課長","answer":"それで各学校、小学校、中学校ともに幹部研修、専門部研修、ブロック研修、それで１年の成果として研究発表大会というふうにしておりまして、ＰＴＡですから、当然親御さんとそれから先生方と、学校側と一緒になって行うという事業です。","voiceIndex":119,"id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"質問","question":"親と先生が一緒になって行う事業ということで、そこからお聞きしたいんですが、この日、七つのブロックに分かれてかなりきちんとした研究発表をなさっていらっしゃいました。教頭先生、実は私はあんまり教頭先生を、全校わかりませんので、どのぐらいの方がお見えいただいたのか、それから逆に一般の先生方がどの程度こういうときに見えているのかなというのが、数字的なものはある程度わかりますでしょうか。","respondent":"上川内生涯学習課長","answer":"小学校のところはきゅりあんで行いました。全体で５７７名。校長先生と教頭先生と、ちょっと区分けはしていないんですが５７名。それから一般の先生のほうは２名ということで、あとは親御さんということです。","voiceIndex":121,"id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"意見","question":"先生の２名というのが非常に疑問に思ってならないです。これだけ皆さん、親のほうが一生懸命やっているのに、学校が地域や保護者の方との開かれた学校ということでやっているのに、何で学校の先生って協力度がないのかなという気がちょっとします。","respondent":"青木指導課長","answer":"今、委員ご指摘の研究大会なんですけれども、今までは保護者の会という認識が学校には強かったのではないかなというふうに思っております。","voiceIndex":123,"id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先生ということで、先ほどのちょっと今までの午前中の質疑の中で思い出したんですが、私、この前の決特のときに健康診断の件でちょっとお聞きして、さっき予算書を見ていて、あれっと思って思い出したんですが、前回結核検診を受けていない方が４０人ぐらいいらしゃるというお答えがあったと思うんですが、そういうのはやっぱりその後、進展しているんでしょうか。","respondent":"鷹倉庶務課長","answer":"そして逐次追跡調査していますけれども、現在のところほぼ１００％になっていると、こういう状況です。","voiceIndex":125,"id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういう病気関係というのはやっぱり子どもに感染すると心配だと思いますので、ぜひ続けていただきたいと思います。学校の関係でもう一点続けてお聞きしますが、去年６月の大阪での池田小学校事件。その中であのときに、学校安全対策委員会が各学校で設置されたと思うんですが、これの運営状況というのは今もずっと続いているんでしょうか。","respondent":"青木指導課長","answer":"そういう意味で、私どもはそれぞれの学校の取り組みを把握しながら、今後も指導していきたいと思いますし、とりわけ年度があけましたら、また校長連絡会などで学校安全対策委員会の具体的な計画と報告という形で、校長先生方にまた指導していきたいというふうに考えております。","voiceIndex":127,"id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問","question":"思い出したくないし、煽ってはいけない部分ですけれども、万が一を考えたとき、やっぱり忘れてはいけない状況だと思います。それからそういういざというとき、先生方、どういう対応をしたらいいのか、そういう訓練みたいなものも、決してこれは子どもを入れてしまうとちょっと問題があると思うので、先生方の中でそういう訓練というのは実施していらっしゃるんでしょうか。","respondent":"鷹倉庶務課長","answer":"それを各学校に示しまして、それを十分留意しながら、各学校でどういう場合押すのか、基本的には学校が判断して押せばいいということになってありますので、そういう形で指導し、いろいろ学校で対応しています。","voiceIndex":129,"id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問","question":"システムだけでなく、何かあったとき、じゃ、先生方はどういうふうに動いたらいいんだというような、そういう訓練というのは特別にはなさっていらっしゃらないんですか。","respondent":"鷹倉庶務課長","answer":"各学校で、それぞれ押し方だとかという形で……、じゃなくて、学校１１０番につきましては、具体的な対応はしていないと思いますけれども。","voiceIndex":131,"id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっと内容が違ったんですけれども、もし、そういう事件が発生したときに、先生方が生徒をどのように誘導していって、どうしたらいいということを検討していらっしゃって、そういう訓練は実際に何か考えていらっしゃるのかということ、そっちのほうなんですけれども。","respondent":"青木指導課長","answer":"既に校内では避難訓練というような形で訓練をしています。私たちの主催しております生活指導主任会の中でも、こうした避難訓練などの情報交換をしています。","voiceIndex":133,"id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。その辺を考えていった場合に、今さら教室をつくるということは全くお考えにならないと思うんですけれども、現実論としてどういうふうに対応していくのかなというのが、疑問があるんですが。","respondent":"富田教育改革担当課長","answer":"そういった学校につきましては、これまで展開しているような形ではなく、例えば平日の午後にはどこまでできるのか、また学校がお休みになる土曜日にはそういった部分でどのように展開していけるのかといったことを、その点も含めて今後検討してまいりたいと考えております。","voiceIndex":135,"id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"すまいるスクールもこれから全校実施ということを考えていったときに、その教室にある程度直していった分と、今度、学校改築との兼ね合いを考えた場合に、学校改築がもう見えているところもやっていくのか、それから逆に先にやっていくのか、そこら辺の問題、それから先ほど学校の屋上緑化も出ましたけれども、屋上緑化をやっていくケースと、学校改築との兼ね合いとか。","respondent":"鷹倉庶務課長","answer":"学校の屋上緑化だとか、今のすまいるの部分も含めて、いろいろな要素を含めながら、総合的に判断して代表質問等でお答えしていますけれども、老朽化だとか、地域のバランスだとか、それを踏まえながら、今の点も踏まえながら、各年度、学校を決めていきたいと。","voiceIndex":137,"id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"意見","question":"すまいるスクールの中で考えていく講座の中に、ちょっと気になっていたのは、５日制になっていったときに、ゆとりある生活の中で個性を生かしながら、自分のよさを発揮し、豊かな生活をはぐくんでいくというところがありますけれども、講座数をあんまり増やしてしまうと、個性を生かしたというところがどうなってくるのかなというのと、それから地域の中で野球だとかサッカーをやっていらっしゃる。","respondent":"富田教育改革担当課長","answer":"すまいるスクールでの、いわゆるさまざまな教室の展開についてだと思いますけれども、やはり親御さんなどの希望の多い英会話とかパソコンなどはベースにしたいと考えていますが。","voiceIndex":139,"id":"exchange-062"},{"speaker":"山路委員","kind":"質問","question":"私のほうからは３点お伺いいたします。１点目は、３０９ページ、コンピューター整備、インターネット活用教育推進事業に関連をいたしまして情報教育について、３点目は、３２３ページ、パソコン教室についてお伺いいたします。私も全くそのとおりだと思うのであります。どのようなコンピューター授業等の技能の向上を目指していくのか、その点についてお伺いをいたします。","respondent":"青木指導課長","answer":"は情報活用の実践力を育てる、２点目は情報の科学的な理解に努める、３点目は情報社会に参画する態度、先ほど委員がご指摘されました情報モラルの必要性等についても指導していきたいというふうに考えております。","voiceIndex":142,"id":"exchange-063"},{"speaker":"山路委員","kind":"質問","question":"現状の教育内容をお聞きした感じがいたしますけれども、もっと掘り下げて情報教育について主体的な判断、表現、創造、発信、伝達能力を身につける、あるいは児童・生徒の課題や問題解決のための目的に応じてパソコン等を動かし、インターネットを、先ほどご答弁にありました、適切に活用することができるようにする育成方法、あるいは創造力、判断力を生かすための心構えを育てるとか。","respondent":"青木指導課長","answer":"先ほど３点のポイントで指導をしているということでご説明させていただきましたけれども、その中で１点目の実践力の中には、当然児童・生徒の主体的な、そうした収集能力や判断能力、表現や処理、そうしたものができるようにということで。","voiceIndex":144,"id":"exchange-064"},{"speaker":"山路委員","kind":"質問","question":"コンピューター授業における本質のレベルアップというものを課長の答弁で感じましたけれども、例えば浜松市では小学生、中学生のコンピューターの技能の認定を一つの方策として実施するです。いきなり、全校一斉とはいかないかもしれませんが、できるところから、そういうものに対しての検討をして、大きな技能資質の向上に役立つものの一つであるかと思いますが、どのようにお考えでしょうか。","respondent":"青木指導課長","answer":"私どもは情報手段の活用というところで、コンピューターを使いたいというふうに考えております。","voiceIndex":146,"id":"exchange-065"},{"speaker":"山路委員","kind":"質問・要望","question":"１級から９級まで段階がありますので、レベルアップのために、ぜひ研究はしていただきたいと思います。もう一点、特に平成１４年度からの情報倫理教育ということが言われておりますが、有効機関として情報機器を使うということと、人というのが大事だということでこういう言葉が今新しく出ているわけですが、情報倫理教育についてはどのような考えで臨まれ、どういう指導をされていくのかをお伺いいたします。","respondent":"青木指導課長","answer":"情報倫理ですが、先ほども情報化社会に参画するためには、基本的な態度というものを育成する必要があるというご説明をさせていただきました。","voiceIndex":148,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問","question":"人と人のネットワークが大切だ、インターネットが人とのふれあいの中にあって生活を豊かにする道具であり、体感をさせていく、それで人の大事さの中に手段があるですけれども、この辺は現場で日常、どういうふうに指導されているかお伺いいたします。","respondent":"青木指導課長","answer":"そういう意味で、コンピューターの活用に当たってはあくまでも、先ほども申しましたように、道具としての認識を持って、やはり人と人とのかかわりというところにコミュニケーションの重要性がありますので。","voiceIndex":150,"id":"exchange-067"},{"speaker":"山路委員","kind":"質問","question":"どうぞ日常の教えの視点をはずさないようによろしくお願いいたします。続きまして、Ｅメールの活用について現在どのような活用をされていくかお伺いいたします。","respondent":"青木指導課長","answer":"まだ、実際にはＥメールを活用しての学習活動というのは、今後の課題にはなってくるかと思いますが、実際に国際交流ということで、アメリカとＥメールのやりとりをするというような報告もあります。これからの課題かなというふうに考えてあります。","voiceIndex":152,"id":"exchange-068"},{"speaker":"山路委員","kind":"質問","question":"今、若干少ないということでございましたけれども、学校内でホームページも開いて、各学校で開いていらっしゃいますし、例えば、国語の時間で作文をつくったり、あるいは和歌を詠んだり、俳句をつくったり、児童・生徒でやっているですが、そういうものの作品については、廊下あたりに掲示したり、また表彰したりされているということですが、Ｅメールを使って、そういう作品を校長先生に送って。","respondent":"青木指導課長","answer":"メールを使ってのやりとりについては今後の課題かなというふうに考えてあります。","voiceIndex":154,"id":"exchange-069"},{"speaker":"山路委員","kind":"提案","question":"Ｅメール大賞とかを新しく考えてはどうでしょうかという、これはご提案ですけれども、それも方策の一助になるんじゃないかと思いますので、どうぞ研究をしていただきたいと思います。ＩＴ講習会は１万１,０００人を当初目標に、１３年度、国の補助を受けて開催されましたけれども、目標達成率は何％までいったのか、また本年は、一部出ましたけれども、どういう事業に変えられるのか、お伺いいたします。","respondent":"上川内生涯学習課長","answer":"今後につきましては、レベルアップというところで、今までのインターネットとメール、それの復習、それからご要望がありましたワード、エクセルの分を新たに組み入れるということでパソコン教室２０回、１回２０人定員で実施したいと思っているところです。","voiceIndex":156,"id":"exchange-070"},{"speaker":"山路委員","kind":"質問","question":"当初の目標にちょっと足らないみたいですけれども、もともとＩＴ講習会の意義はデジタルデバイド対策ということで、数多くの人に基礎的な技能を身につけていただくですけれども、でき得れば、本年も１授業、１講習会ぐらいは必要じゃないかと私は思うんですけれども、全く予定が立っていないみたいですけれども、この辺についてはどのように検討されたんでしょうか。","respondent":"上川内生涯学習課長","answer":"１３年度全体で約３０講座程度を申請していく予定にしています。","voiceIndex":158,"id":"exchange-071"},{"speaker":"山路委員","kind":"質問","question":"もう一点ですけれども、外国人の方の参加については１３年度はどうだったんでしょうか。時間がありませんので、もう一つ、外国人の方が参加していなかったら、新たに外国人の方の講習会というのも１４年度は考えてもいいんじゃないかと思いますが、どうお考えでしょうか。","respondent":"上川内生涯学習課長","answer":"外国人の方につきましては、今までの中で外国人というところで集計はしてございませんでしたので、外国籍の方も入っていたと思いますので、今後はその辺、どのような需要があるのか研究させていただきたいと思います。","voiceIndex":160,"id":"exchange-072"},{"speaker":"田中委員","kind":"質問・要望","question":"私も同趣旨で、パソコン教室に関しましては、本来民間で行える授業は極力民間でと、一方、区、行政が行うことは福祉の向上に向けてということで、その辺のすみ分けを明確にしなくちゃいけないとは思うんですが、一方、パソコン需要が増えるということは逆に言うと民間需要を増やすということにもなるので。","respondent":"上川内生涯学習課長","answer":"ただ、当生涯学習課扱いでも６,０００人という方を卒業させているわけでございまして、それも高齢の方が、最高齢８８歳という方もいらっしゃいますし、そういう方たちのために、意欲が続いている間にレベルアップをしたいということもありまして、メープルだけでは賄い切れない。","voiceIndex":163,"id":"exchange-073"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう中で、逆に言うならば、コンピューターを使えないと行政サービスを受けられないという事態に、今後ますます、そういう懸念というんでしょうか、ことが予想されるんですけれども、そういう方々の、いわゆる情報弱者の方々にも適切なといいますか、使える方と同等の行政サービスを提供する上でも、情報弱者という方々を極力少なくしていく。","respondent":"上川内生涯学習課長","answer":"国の補助の対象ということでは１４年のところまでしかわかりませんが、シルバー大学のうるおい塾ですとか、そういうところでもこれからやっていくようになると思いますので、そういうところで検討させていただきたいと思います。","voiceIndex":165,"id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"これからますます電子化が進んで、いわゆる電子区役所になっての方向に進むとなると、公平性の概要としては、当該事業の便益や負担が公平に配分されているかどうかという観点でチェックするということと、さらにはサービスの受益者とそれ以外の者とに不均衡が生じないかどうかの基準でも評価するというふうな基準になっておりまして、行政評価上も将来の電子区役所になった際でも。","respondent":"田中情報システム課長","answer":"今後の電子区役所に向けての情報格差対策としましては、いろいろな形で今、所得、企業の規模等、業種等、いろいろアンバランスがありますので、それに対応したような公開端末の配備ですとかを含めまして、十分検討していきたいというふうに考えております。","voiceIndex":167,"id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"今現在まだ完全な電子区役所になっていないこの時代ですので、まずは新年度にも書かれておりました障害者の方に対するパソコン教室もぜひ進めていただきたいですし、また引き続きシルバー大学等々の高齢者の方々に向けてもそうですが、高齢者あるいは障害者ではなく、いわゆる情報弱者という方も今後ますます増えてくることが予想されますので。","respondent":"青木指導課長","answer":"基礎・基本をどこまで絞れるのか、そして小学校、中学校を通して学んだことがさらに高校につながっていくという、いわゆる小・中で学習しなかったものをさらに高等学校につなげていくような中で学んでいくという、３割減ったというよりは、３割スピードを落として。","voiceIndex":169,"id":"exchange-076"},{"speaker":"田中委員","kind":"意見","question":"厳選されたということでありますが、それまでの教育もある種厳選されて小・中の教育内容がある種基礎・基本ではないかなという、まだ少し認識を持ちながらあれなんですが、今回、基礎・基本の学力定着度を図るための学力調査が行われるということなんですが、この目的は、ほんとは基礎・基本の定着度を図るという、またそれを先ほどはその結果を次の指導に生かしていかれるんだというお話だったんですが。","respondent":"青木指導課長","answer":"ですから、ただ知識、技能というところだけで調査をするということではなくて、二つの力を両面測定できるような、そうした問題を作成し、実施していきたいというふうに考えております。","voiceIndex":171,"id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば、品川区立小学校を出た方が、私立の中学校に行きたい、あるいは、公立中学校から私立の高校に進学したいといった際の、要は入試の問題というんでしょうか、入学試験の対象も基礎・基本になっていないと、学校で学んだこと以上に勉強しないと私立の中学校あるいは私立の高校に行かれないと仮になったならば、先ほど、統計上は塾に行く数は特段変わりないということだったんですが。","respondent":"青木指導課長","answer":"公立学校として基礎・基本の定着ということに力を入れてまいりますが、基礎・基本の力が定着することによって、次の段階として発展的な力につなげるものであるというふうに考えております。","voiceIndex":173,"id":"exchange-078"},{"speaker":"桜井委員","kind":"質問・要望","question":"２点、ご質問します。小・中学校の校長と教育委員会が１対１でやる。私は、改めてちょっとご説明いただきたいんですけれども、一つは学校の特色づくりのための予算の総額、プラン２１関連事業、それから二つ目には学校の、今出たプラスアルファ、配当の予算配分の総額と基準、それからその中で、要望されたけれども、ついた予算、それからつかなかった内容の理由。以上です。","respondent":"久保田学務課長","answer":"中学校も３,１１０万円ほどということになるかというふうに思っております。それから、今回の学校で要望された予算のプラスアルファの分は、プラン２１関連事業がプラスアルファの部分というふうに見ていただいてもいいかなというふうに思っております。","voiceIndex":176,"id":"exchange-079"},{"speaker":"桜井委員","kind":"質問・要望","question":"要するに、一生懸命、教育予算をお願いしたいというふうにヒアリングで学校長が説明しているわけですね。よし、わかった、これだけつけますというふうに多分お話があったんだと思うんですけれども、そういうプラスアルファの予算というのは総額幾らかということを質問したのと、それから、今言ったように、要望されたけれども、ついた予算とつかなかった予算の内容を教えてくださいというふうに言ったんです。","respondent":"久保田学務課長","answer":"基本的に今までの配当予算等の違いということで、これは学務課で持っている教材・教具費が一番大きいので、その点で若干ご説明しますけれども、ほとんど平成１３年と１４年は変わりなく、配当予算はここで予算を計上しています。","voiceIndex":178,"id":"exchange-080"},{"speaker":"桜井委員","kind":"質問・要望","question":"何回も同じ質問をさせないでいただきたいんですけれども、じゃあ、教育長のほうに聞いたほうがよろしいんでしょうか。軽量でいくと。一生懸命校長が説明し、教育長の理解を得たものは、それはつけますと。しかしそうでない場合には、それはつけられない。それと学校の、そういうものが要望あったけれども、これはつけてこれはつけなかったと、同じことを何回も、ちょっと委員長、質問しているんですけれども。","respondent":"市岡企画財政課長","answer":"それから備品購入費でも同じ考え方で１７５万円。ただしこれは、特定の学校のどこへつけたということではなくて、あくまで教育費として、こういう枠で予算を計上したと、こういうことです。","voiceIndex":180,"id":"exchange-081"},{"speaker":"桜井委員","kind":"質問・要望","question":"学校、今、私は教育長に聞きたいんですね。教育長自身が公表します、各学校への予算配分は必ず公開しますというふうに言っているわけです。今していなければいつするのか、あるいはこの場で公表いただければ公表していただきたいというふうに思います。","respondent":"指田教育次長","answer":"これから、今、一時的なものというものは各学校に通達いたしました。例えば、習熟度別であるならば、あなたの学校は何時間分ですよというふうな形を差し上げてありますけれども、全体的な２次査定分がまだ残っていますので、それはこれからというふうな状況になります。","voiceIndex":182,"id":"exchange-082"},{"speaker":"桜井委員","kind":"質問・要望","question":"一つあります。そこをもう一度確認をしたいのと、その前段の質問です。私の試算だけではちょっと申しわけありませんから、そちらのほうで教えていただきたいんですけれども、あまりさかのぼっては恐縮ですけど、３年間のところでお話しいただきたいんですけれども、区民一人当たりの教育予算、それから児童１人当たりの教育予算、それから生徒１人当たりの教育予算、これ３年間、教えてください。","respondent":"鷹倉庶務課長","answer":"児童１人当たり、小学校ですね、これが１０年度が４８万円、１１年度が５２万円、１２年度が５４万円。そして中学校が１０年度が５０万５,０００円、１１年度が５１万３,０００円、そして１２年度が……、ちょっと１２年度が数字がおかしいのでまた後ほど申し上げます。","voiceIndex":184,"id":"exchange-083"},{"speaker":"桜井委員","kind":"確認","question":"児童１人当たりですね。それで、区民１人当たりの教育費を教えていただけますでしょうか。それで、今プラン２１によって１億数千万円、これは今までのイメージとしては教育予算よりも増えた、プラスアルファになったというふうに、総額を、私は今受けとめたんですけれども、その理解でいいのかどうか、もう一度確認と、先ほど公表のことをご答弁いただかなかったんですけれども、教えてください。","respondent":"指田教育次長、鷹倉庶務課長","answer":"公表については、どういう公表の仕方をするかは別にしましても、公表は必ずしてまいります。私は持ってございません。そして２３区中の順位という形のお話がございました。これはどの数字をとるかというのはなかなか難しいんですけれども、２３区そろっている数字で１２年度ベースで持っている数字があります。","voiceIndex":186,"id":"exchange-084"},{"speaker":"桜井委員","kind":"質問","question":"私がなぜしつこく教育予算の質問をしているかというと、やはり校長とのかかわり方が、一般の父兄の皆さん、父母の皆さんが見ていまして、一体、公教育というのか、どういうふうに一人ひとりの子どもたちにかける費用、公立ですからどの学校を選んだにしても、やはり教育費のかけ方は、やっぱりそれは当然ながら等しくする、それはもう基本だと思うんですね。生きる力、目標は入きる力なんだと。","respondent":"若月教育長","answer":"経営の論理が優先しているのではないか、こういうご指摘でありますが、そんなことはないんです。教育の論理を正しく機能させるためには、もっと経営的なセンスを取り入れなければだめだ、こう言っているだけのことであります。","voiceIndex":189,"id":"exchange-085"},{"speaker":"桜井委員","kind":"質問・要望","question":"その経営的センスを私は質問したんですけれども、１分しかないので私のほうからちょっと指摘をしておきたいと思いますけれども、経営論的発想に基づく指導システムづくりや学校体制づくりが大切であると。今の経営のベースというのはやっぱり、成果主義ということがよく企業でも言われていますよね、成果主義。そこにコストの問題と効率主義がね……、人間を見る上では大変だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-086"},{"speaker":"本多委員","kind":"質問・要望","question":"私からは２点質問します。１点目は、学校管理費の教材・教具費について、２点目は、教育改革プラン２１を進めていく上での教職員について、２点お伺いします。それと２点目が体操着の購入ですね。三つ目が私費で購入しているものの会計について、４点目が小中学生対象の傷害保険がどのようになっているのか内容を教えていただきたいと思います。","respondent":"久保田学務課長","answer":"いずれも学校が発注して、公費あるいは私費で支払っているですけれども、私費につきましては、各学校ごとに月額を決めて徴収して必要な教材を購入し、年度末には決算書的なものを作成して、これには監査を当然つけるんですけれども。","voiceIndex":193,"id":"exchange-087"},{"speaker":"本多委員","kind":"質問・要望","question":"学校内で管理をする会計帳簿ですね、まあ、先ほど私費については年度末決算、そして監査をしているということなんですが、学校内で管理する帳簿について改めてお聞きしたいのと、また、教師用の教科書と指導書ですね、小学校３,６４０万円、中学校１,６３８万円、この辺の部数ですとか単価に関しては、定価に対する購入率というんでしょうか、その辺についてお聞かせいただきたいと思います。","respondent":"久保田学務課長","answer":"指導書の割合ですけれども、これは各学校によってそれこそ千差万別がありますので、統計的な数字は今のところ持ち合わせておりません。","voiceIndex":195,"id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"学校単位でまとまった数で購入をしていくものというものはどのくらいあるのか、概要をちょっとお聞かせいただきたいと思うんですが。","respondent":"久保田学務課長","answer":"学校単位でまとまって購入するものは、いっぱいあると考えています。その中でも一番典型的なものが、例えば卒業の記念アルバムなんかも挙げられるかと思います。","voiceIndex":197,"id":"exchange-089"},{"speaker":"本多委員","kind":"質問・要望","question":"納入をされました教材・教具で、使用されないものというものがもしあれば、お聞かせいただきたいと思います。こういったものは、児童・生徒それぞれ、教材として個々に持つ、例えば算数とかではドリルとかいろいろな教材があると思うんですが、そういった個々の教材ですとか、あと共通して学校に置いてあるもので使わないようなものなどがあれば教えていただきたいと思います。","respondent":"久保田学務課長","answer":"共通して使わないものですけれども、当然会費を取って、要するに予定していたけれども買わなかったと、こういうものについては返還しておりますので、必ず教材を買ったらそれは何らかの形で使用しているということになるのではないかなというふうに思っております。","voiceIndex":199,"id":"exchange-090"},{"speaker":"本多委員","kind":"質問・要望","question":"次に行かせていただきたいと思いますが、教育改革プラン２１を進めていく上で、教職員の現行の制度、先ほどからも答弁が出ておりまして、意欲のある人、そうでない人がいて、教育委員会としては、品川区の教員という自覚を持って取り組んでほしいという指導課長の指導のとおり、そのとおりだなと思うんですけれども、今の地方分権の進む中、人事制度につきましては構造的な変革が求められており。","respondent":"青木指導課長","answer":"私どもが、こういうような人材が必要であるというようなことを都とのヒアリングを通して、都のほうの調整によってこちらのほうに勤務するような形になるわけでして、そういう意味で、私どもが目指している教育改革に必要な人をすぐに採用する。","voiceIndex":201,"id":"exchange-091"},{"speaker":"本多委員","kind":"質問・要望","question":"アメリカの公立学校では、教員が自主的に手を上げて、そういった自主的に手を上げた方を採用していくということで、教育委員会が異動とかはほとんどないそうで、また、チャータースクールに関しましても人事異動がほとんどなく、人材の掘り起こしとか採用を自由にして、人事権があるというような、非常にやりやすいというような部分があると思うんですが、その点についての感想などがあったら。","respondent":"青木指導課長","answer":"理事会によって学校運営を進めていくという今の事例を紹介していただきましたけれども、確かにそういう意味で、教育委員会の制度を超えた制度ではないかなというふうに考えております。","voiceIndex":203,"id":"exchange-092"},{"speaker":"北野委員","kind":"質問・要望","question":"最初に、すまいるスクールについて伺いますけれども、こちらは今年の９月から、城南第二小学校、原小学校、宮前小学校の３校が新たに開設されるわけですけれども、場所としてはどこが使われるのでしょうか。お伺いしたいと思います。それと、こちらは身障者学級が常設ですよね。そうしたときに、今後そういう身障者のお子さんたちを放課後どうするかということについても再度お伺いしたいと思います。","respondent":"富田教育改革担当課長","answer":"すまいるスクール新規開設３校の、開設の場所はどこかというお尋ねですが、具体的には各学校と今後詰めていく予定ですけれども、それぞれ比較的独立して、まとまった３教室以上とれるところというところで考えております。","voiceIndex":206,"id":"exchange-093"},{"speaker":"北野委員","kind":"質問","question":"そこを予定されているのか、まあ、今後の話し合いなんですけれども、その点をちょっとお伺いしたいのと、それから教室を使うにしても、こちらは今、西大井の南地区の再開発ですよね。それで、住宅が３００戸増えるということで、将来的には小学校の新入生、または転校生が見込めるわけですけれども、そういうことも考えて教室というのは検討されるのでしょうか、お伺いします。","respondent":"富田教育改革担当課長","answer":"地域開放している部屋と、またすまいるスクールで使用する教室と、どのように使い分けをしていくのか。例えば同じ施設を時間で分けていくとかさまざま考えられると思いますが、この点については、学校を中心に今後検討してまいりたいというふうに考えております。","voiceIndex":208,"id":"exchange-094"},{"speaker":"北野委員","kind":"質問","question":"二度手間ということにもなりかねないので、今のお返事ではそうですけれども、ちょっとそこが納得いかないなというのがあります。先日の教育委員会の中では、学識経験者の人が５校ぐらいを大体受け持ちまして、そして基準が標準化するようなというお話し合いもあったようですけれども、そういう基準というのはどういうふうに設問については設定していくんでしょうか、お伺いします。","respondent":"富田教育改革担当課長、青木指導課長","answer":"初めに原小学校の児童数の増についてですけれども、現在使用予定の西校舎ですが、場合によっては４教室すべてということではない可能性もございまして、さまざま考えておりますけれども、差し当たって当面。これも、ＡからＢに当てはまる当てはまらないという形での評価の尺度が出てきておりますので、そういう意味で、学校側の説明も含めて、その基準が示されていくというふうに受けとめていただければと思います。","voiceIndex":210,"id":"exchange-095"},{"speaker":"北野委員","kind":"質問・要望","question":"学校評価のことなんですけれども、こちらの項目では、「１ 学校の総体」と、それから５項目ありまして、それで設問の中には、「学校の姿」、「児童・生徒の姿」、「教職員の姿」というのが相当細かくあるんですけれども、いろいろな観点ということがそのことに値するのか、ちょっと理解ができなかったので、もう１回教えていただきたいと思います。","respondent":"青木指導課長","answer":"そこにそれぞれ具体的な内容での文言が評価表には入っておりますので、そこの項目についてそれぞれ評価していただくような、そうした評価表の仕組みになってあります。","voiceIndex":213,"id":"exchange-096"},{"speaker":"北野委員","kind":"提案","question":"それと評価の中に、子ども自身が理解度というんですか、要するに勉強に対して理解できた理解できなかった、こういうところがわかりにくかったというような、やはり子ども自身からの調査も行うべきではないか。民間事業者に委託ということなんですけれども、調査内容は品川区独自のものをつくるということなんですけれども、どういうようなことで調査表をつくっていくのかというのを伺いたいと思います。","respondent":"青木指導課長","answer":"学力調査ですけれども、学力調査につきましては、学力調査の問題作成委員会という、そうした委員会を設置いたしまして、そこで問題作成に当たって検討していきますが、先ほど委員ご指摘の、民間の機関との連携で進めていきますが、この問題作成というのは大変時間もかかりますし。","voiceIndex":215,"id":"exchange-097"},{"speaker":"北野委員","kind":"質問","question":"子ども自身の評価というんですか、それについてはいかがでしょうか。そういう学校独自に子どもの姿というんですか、自分が生きる力として進めていくことについて、やはり評価していくということが大事だと思うんですけれども。全部が品川区の基本の姿で評価してしまうというのはおかしいのではないかなということなんですけれども。","respondent":"青木指導課長","answer":"これは、それぞれの学校で当然、外部評価者を集めて説明もいたしますし、それからこうした基準でこの調査を進めてほしいという依頼をしていくわけですから、統一した形で、全く同じような観点で、子どもたちを同じ物差しではかるというようなことではございません。","voiceIndex":217,"id":"exchange-098"},{"speaker":"北野委員","kind":"質問・要望","question":"やはり子どもの姿というのが、自然体であって、いろいろさまざまな点で評価されるべきだと思いますので。予算書には小学校の５年と中学２年というのが事項別明細に載っていますけれども、そういうところでやはり、そういうのが学校の判断にならないように、要するにいい学校、悪い学校という判断にならないような形で進めていっていただきたいと思います。この減っている理由を教えていただきたいと思います。","respondent":"久保田学務課長","answer":"今回は、図書費の充実という観点から、ほかの費目には流用しないということを限定して、今までやってきた部分について精査した形で、今回はこういう形で予算を計上したと。ほかの費目、あるいはほかの事業には、この予算は絶対流用させないという思いでこれをやってきたです。","voiceIndex":219,"id":"exchange-099"},{"speaker":"北野委員","kind":"質問・要望","question":"図書費を流用していたということは、ほかの予算が少なかったから流用されたという意味にもとられてしまうんですけれども、まあ、今年はそれをちゃんとその事業に回したということであって……。ですから学校図書の充実も図りながら進めていっていただきたいと。ですから来年度は、ちゃんとした計画を立てて、要望があれば出していただけるということなんでしょうか。","respondent":"久保田学務課長","answer":"それに応じて新たにそういうところにも予算をつぎ込んでいく、強化していくという考え方は現在持っております。","voiceIndex":221,"id":"exchange-100"},{"speaker":"北野委員","kind":"質問・要望","question":"今、各学校でも、朝の図書の時間を設けたりとか、読書の時間を設けたりとかいろいろ進めている。その中で、ぜひ図書についても充実させていただきたい。子どもが読みたい本がやはりあると思いますので、そういうのも選びながら進めていっていただきたいと思います。防災センターなど人が来るところなどがいいと思いますがいかがでしょうか。","respondent":"鷹倉庶務課長","answer":"ここで意識調査をした中で、いろいろご意見をいただいてもおります。これを踏まえながら検討委員会で、こういう形で集約したという形で、ご意見を運営に反映しているという考え方を持ってあります。","voiceIndex":223,"id":"exchange-101"},{"speaker":"北野委員","kind":"提案","question":"これは私も、学校改築に当たっては、絵とか文章なりで、ぜひ子どもの意見を取り上げてほしいということで提案させていただいたことが実現したということなんですね。それで、やはりいろいろな方が学校に向けて、新しい学校ということで子どもたちがこういうことを描いているんだよということで、ぜひ機会をとらえてではなく、前向きに進めていっていただきたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":225,"id":"exchange-102"},{"speaker":"金高委員","kind":"質問・要望","question":"私は、３０５ページの国際理解教育についてお伺いをします。既に国際理解教育は、品川区のプラン２１によりまして、平成１１年度から推進してまいったわけでありますけれども、ちょうど３年目になります。これらの先生方、どういう資格といいますか、まあ、教員資格といいますか、そういうのを持った方なのかどうか、そういうのをお伺いさせていただきたい。","respondent":"青木指導課長","answer":"中学校のほうですが、これはやはり、二つの派遣の方法をとっております。一つは人材派遣の会社のほうから派遣するものですが、もう一つは、そのポートランドとオークランドの学校の先生を直接招致して本区の学校に派遣をすると、こういうような形で現在進めております。","voiceIndex":228,"id":"exchange-103"},{"speaker":"金高委員","kind":"意見","question":"それぞれ小学校、中学校、内容が違うわけですけれども、３年目に入りまして、この３月、いよいよちょうど３年目が終わるわけです。これらを実際に実施されてきて、それぞれの学校での成果といいますか、その辺をお聞かせ願えればと思いますが。","respondent":"青木指導課長","answer":"小学校ですが、小学校は２年目が終わります。プラン２１のスタートから、小学校の国際理解教育、全校で小学校は取り組んでおりますので、その２年目が終わるということになります。","voiceIndex":230,"id":"exchange-104"},{"speaker":"金高委員","kind":"質問","question":"中学校のほうはどのような形になりますでしょうか。","respondent":"青木指導課長","answer":"やはり生の英語を聞いたり、それから実際に会話を通してコミュニケーションを深めるという意味では、大変ＡＬＴという存在は大きいものというふうに考えております。","voiceIndex":232,"id":"exchange-105"},{"speaker":"金高委員","kind":"意見","question":"非常に成果が上がっているということでありますけれども、見方をちょっと変えまして、ポートランドあるいはオークランドからそれぞれ先生が来ております。ちなみに１人当たりの単価というのはどのぐらいの単価になっているか、参考までにお聞かせ願いたいと思いますが。","respondent":"青木指導課長","answer":"１時間当たり７,３００円ということで行っております。","voiceIndex":234,"id":"exchange-106"},{"speaker":"金高委員","kind":"質問","question":"１時間当たり７,３００円、非常に高い数字でありまして、ちょっとびっくりいたしました。その次に、帰国子女の問題点で、ちょっとお伺いします。","respondent":"青木指導課長","answer":"今年度につきましては、２２人がきゅりあんの教室に通っております。ほぼ集中講座ですので、３カ月ほど通うと日本語になれるということで、また学校のほうで普通の生活に入れるようなケースが多くなっております。","voiceIndex":236,"id":"exchange-107"},{"speaker":"金高委員","kind":"質問","question":"先日、このきゅりあんのほうにお伺いさせていただきまして、授業内容をちょっと見せていただきました。聞きましたら３カ月程度ということでありました。なぜかといいますと、小学校の低学年ですと、学校でもって子どもたちと遊びながらの会話とか何かでもってできるわけでありますけれども、特に高学年、あるいは中学生になって日本に戻ってまいりまして、３カ月でもって、確かに日本語を話すことはできる。","respondent":"青木指導課長","answer":"この教室に集中的に通いますけれども、学校も通ってありますので、言葉は最初は理解できなくても、この集中講座に通いながら学校と並行して生活を進めていくということをしておりますので、学校のほうの教師もそうしたことを十分配慮して指導に当たっております。","voiceIndex":238,"id":"exchange-108"},{"speaker":"金高委員","kind":"質問","question":"先日この教室のほうに伺いましたところ、ちょうど３人の先生方がおりまして、ほんとに文部省のつくりました教材を利用しまして、きめ細かにそれぞれの言葉でもって教えております。もしやっているのであれば、品川区とどういう違いがあるかどうか、その辺を、もしありましたらお聞かせ願いたいと思います。","respondent":"青木指導課長","answer":"このような取り組みがあるということは聞いておりますけれども、具体的にどういうような状況であるかという、まあ、正確な情報としては把握してございません。","voiceIndex":240,"id":"exchange-109"},{"speaker":"金高委員","kind":"質問・要望","question":"こういういろいろな言葉を知っている先生方のところでフォローするために、多分ＮＰＯですか、その関係でもってやっていると聞いておりますけれども、そういった、通う子どもたちに対して何らかの、行政のほうでもって手を差し伸べる枠があるかどうか、将来的な展望でありますけれども、その辺のご意見をいただければと思います。","respondent":"青木指導課長","answer":"そういう弾力的な対応をしていますので、今後も一人ひとりのそうしたお子さんに対して対応できるような教室であるように運営をしていきたいというふうに考えております。","voiceIndex":242,"id":"exchange-110"},{"speaker":"金高委員","kind":"意見","question":"これからの日本は少子化になります。海外からそういうふうに戻ってきた子どもたちは、いずれ日本でもってずっと生活していくわけでありますので、日本の貴重なる財産、人材であると思います。そういう子どもたちを一人でも多く直すといいますか、やはり社会の中でもって１日でも早く入っていけるようなそういう体制は、絶えずとっていただきまして、教育行政に取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":244,"id":"exchange-111"},{"speaker":"辻委員","kind":"確認","question":"いよいよ学校５日制がスタートするわけですが、品川区でもそれに向けてさまざまな事業が予定されています。それでちょっと確認しておきたいんですが、今、まるっきり話が違うんですけれども、学校に、品川区に教育実習という形で、学校の教員、教職課程をとっている方が、品川区の小・中学校に教育実習として来る実績というのはどのぐらいあるんですか、年間。","respondent":"青木指導課長","answer":"毎年教育実習生は品川区で受け入れております。その人数は年によって違いますけれども、ほぼ２０人程度の実習生は受け入れているところです。","voiceIndex":246,"id":"exchange-112"},{"speaker":"辻委員","kind":"質問・要望","question":"それから長期の夏季休暇ですね、要するに夏休みなんかのときにどうするかということについても、今後考えていかなきゃ……。それがまた品川区の教育に対して情熱を持っている、先ほどあったように、品川区が悲鳴を上げるぐらい殺到していい教師が集まってくる、こういうことにもなるんじゃないかと思うんですけれども、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"委員ご指摘の学生ですとか、教員を目指す方々のすまいるスクールとのかかわりですけれども、ちょうど夏休み期間中は、非常勤職員も午前中の部分が手薄な部分もありますので、ぜひとも夏休みについては、大学の。","voiceIndex":248,"id":"exchange-113"},{"speaker":"辻委員","kind":"質問","question":"ぜひ検討をお願いしたいと思います。次に習熟度別の学習のことについてお伺いします。要するにおくれている、つまずいているとか、そいういうことに対して何とかゆとりを持って教えていかなきゃいけないというのはわかるんです。これでちょっと関連なんですが、それで、おくれている子どもについては指導助手なんかをつけていろいろやるっていうんですけど、進んでいる子どもについてはどういう形で……。","respondent":"青木指導課長","answer":"そのグルーピングにつきましては、指導助手が入ったり、また時には管理職が入ったりすることもありますし、学年全体で行うような習熟度の形もありますので、さまざまな形態で習熟度別の学習を進めているところです。","voiceIndex":250,"id":"exchange-114"},{"speaker":"辻委員","kind":"意見","question":"その場合は、この習熟度でいうとおくれているというか、つまずいたり、いろいろ理解が、抱えている子どもというのは、ある部分では復習に近い形ですよね。ところが進んでいる子というのは、もう復習ではなくて今度は予習に近い、平たく言っちゃえば次へ進んでいっちゃうわけです。その辺はもう、とことんやらせていく方向なのかどうか。その辺で、どういう考えがあるのか。","respondent":"青木指導課長","answer":"それぞれの子どもの学習意欲ということを、やはり十分に配慮していかなければいけないというふうに考えています。","voiceIndex":252,"id":"exchange-115"},{"speaker":"辻委員","kind":"質問・要望","question":"我々は、小・中一環教育の中で、品川区として抱えたさまざまな問題が、このいろいろな中で解決もあるんじゃないか、こういうことをしてもらえばという課題と、ここで例えばね、「学級は原則として同学年の児童・生徒で編制する」という、これは学級編制についての話ですけれども、ここで言うのとはちょっと意味合いが違うかと思うんですけれども。","respondent":"富田教育改革担当課長","answer":"小学校設置基準および中学校設置基準の制定に関して、文部科学省のほうでパブリックコメントを求めているわけですけれども、品川区教育委員会といたしましても、小・中一環校の問題等々あり、積極的に事務局内で考えをまとめて期限までに提出していきたい考えです。","voiceIndex":254,"id":"exchange-116"},{"speaker":"辻委員","kind":"提案","question":"それからもう一つが、まず読書運動についてちょっとお伺いしたいと思います。やり方はいろいろあるかと思うんですけれども、私は朝１０分ぐらいの、まずそこから入っていこうというような提案もしていたわけですけれども、どんな形で進まれているのでしょうか。","respondent":"青木指導課長","answer":"読書活動を取り入れた教育活動ですけれども、現在、読書活動を教育課程に位置づけて実施している学校が、小学校では３０校、中学校では７校あります。","voiceIndex":256,"id":"exchange-117"},{"speaker":"辻委員","kind":"質問","question":"この読書というか、要するに広い意味では国語というものが一番大事になってくるというのは、論を待たないと思うんですね。そこでどう習慣として、そのものが、活字離れと言われる中でなっていくかということは非常に大事だと思うんです。教育委員会というのは、このことについてやれとかって首に縄をつけてはいけないでしょうが、どういうことなんでしょうか。やれないのとやる学校の差というのは。","respondent":"青木指導課長","answer":"先ほど小学校３０校、中学校７校というふうにご説明いたしましたけれども、これはあくまでも固定的に、もう時間割の中に組んでいるという学校でございまして、何らかの形ではどこの学校でも実施しています。","voiceIndex":258,"id":"exchange-118"},{"speaker":"辻委員","kind":"質問・要望","question":"朗読というか、読み聞かせもやっていました。ですから、この授業というか、国語というんじゃなくて、学校の一つの大きな行事として読書というのは位置づけていただきたい。どうでしょうかね、ほんとにやっている学校とやっていないところをね、それこそ差をつけてでもいいから、奨励してあげてぐらいに私は意味があると思うんです。これを私は思いますので、ぜひこれは要望しておきます。","respondent":"山岡総務部副参事","answer":"体育館のフリー教室につきましては、スポーツ協会と教育委員会と共催の形で事業を実施しているですけれども、区民の方でしたら、何曜日の、例えば午前中でしたらどういう種目があるという形でなっております。","voiceIndex":260,"id":"exchange-119"},{"speaker":"辻委員","kind":"質問","question":"そのときに、私のところにある区民の方から電話をいただきまして、フリースクールというのは個人参加なんですか、それとも団体参加なんですか。この辺をちょっとお伺いしたいと思います。","respondent":"山岡総務部副参事","answer":"個々の方が、自由にフリーに参加できるです。団体の競技もありますけれども、個人で参加してその団体の皆さんと一緒にやると、そういう形を今、とっております。","voiceIndex":262,"id":"exchange-120"},{"speaker":"辻委員","kind":"質問","question":"時間がないので端的にお伺いします。個人で参加していくというか、区内の在住、在勤と書いているんですよ。ところが高校生ぐらいになってくると、港区とか他区の学校同士の仲間が来て参加したいと言ったときに、入口で、あんた品川区じゃないからといって断るんですか、どうですか。","respondent":"山岡総務部副参事","answer":"原則として先ほど申しました条件ですので、そういうふうにお尋ねをされましたときは、区外の方はご遠慮していただきますと、そういうふうにお答えしております。","voiceIndex":264,"id":"exchange-121"},{"speaker":"辻委員","kind":"質問・要望","question":"区外、他区はだめというか、これは有料でやっているわけですよ。ところが個人で４、５人がバスケットやろうといって来たときに、あんた区外だからだめよとかと言う……、私はちょっとこれは……、料金体系をどうするかというのは、これは調べると、スポーツ協会が全部徴収とかをやっているようですが、ひとつこれはぜひ検討していただきたい。いかがでしょう。","respondent":"山岡総務部副参事、指田教育次長","answer":"今の問題につきましては、スポーツ協会サイドだけで決めるわけにもまいりませんので、教育委員会と協議しまして前向きに検討してまいりたいと思います。大変申しわけありません。区民の方がいれば、そういう差別をしないで必ず入れるような形でもって対処してまいります。","voiceIndex":266,"id":"exchange-122"},{"speaker":"築舘委員","kind":"質問・要望","question":"それからすまいるスクールに関しましては、この４月から完全週５日制ですか、ということで、土曜日が結局先生方が教えていたんだけど、それがお休みになると。そうしますと、そこにおいて、今度三つの学校、第二延山とほかに、また三つの学校が増えるわけですから４校になるわけですけれども、４校だけで比較というか、すまいるスクールを位置づけるというのは多少問題があるんじゃないか。","respondent":"青木指導課長、富田教育改革担当課長","answer":"それぞれ教科について、特別活動について、その中では学校教育はどうだったのか、それぞれのところで教員同士の１年間の反省を出して、職員会議を通して、それをみんなで検討をしてきた。平成１４年度につきましては３校ですが、１５年度以降は年次計画を立てて拡大をしてまいりたいと考えておりまして、この際には、先日校長会のほうでも、１５年度からは手を挙げた学校等々。","voiceIndex":270,"id":"exchange-123"},{"speaker":"築舘委員","kind":"質問・要望","question":"学校評価のほうですけれども、それぞれ先生方が評価をするといっても、どうしてもやっぱり甘くなるという部分はあると思うんですね。それは要望で結構です。それで、専任指導員１名というふうに先ほど言われていましたけれども、この専任指導員１名というのは、今の学校の先生じゃだめなのかどうか。ですから、そういうことが考えられることなのかということを、ちょっとお聞かせください。","respondent":"青木指導課長","answer":"すまいるスクールの職員と学校の教員では、やはり勤務の上で重なりがどうしても出てきますので、ちょっと今のご提案は無理な形になります。","voiceIndex":273,"id":"exchange-124"},{"speaker":"築舘委員","kind":"質問・要望","question":"それで、いやあ、しっかりと本会議、委員会のために勉強しています、それから地域の皆さんのために毎日回って、それからその要望を聞いていますと、こういうことをしっかりと言っているわけですよ。それで、４年たったらその審判を得るわけですよ。だからそれは評価ですね。はっきり言って評価につながるわけ。ただやっぱり、そういう意欲のある先生が出た場合、どうなるんですか。どうでしょうか。","respondent":"青木指導課長、若月教育長","answer":"それで、今、このすまいるスクールでも、学校とこのすまいるスクールの連携というんですか、学校の情報とすまいるスクールの情報をお互いに交換し合ってすまいるスクールを進めているという現実もありますので、今後。したがいまして、委員がご指摘のように、すまいるスクールとは別に、先ほど来、出ていますように、学習がおくれているようなお子さん、あるいはもっと勉強したいというようなお子さん、そういう子どもたちを学校に集めて。","voiceIndex":275,"id":"exchange-125"},{"speaker":"築舘委員","kind":"質問","question":"だから、悪い先生が２人いると、やっぱりこれは悪くなっちゃうんですね。ですから、そういうところは、それぞれやっぱり学校が、校長先生が権限を持って、しっかりとやる気のある先生を常に引き立てるというか伸ばしてあげる。ですから、そこの点をひとつ、しっかりと考えていただいて、教育長からもお答えいただきましたけれども、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":278,"id":"exchange-126"},{"speaker":"沢田委員","kind":"質問","question":"小中一貫校に関して、大きく２点、質問したいと思います。先日の代表質問で、私は具体例を挙げて、統廃合になるんではないかという不安が地域に広がっているということを質問した際に、教育長のほうから、そういったのはあくまでも想像だ、全部想像になるわけですと言って、基本的スタンスとして統廃合は考えていないというふうに答弁されたわけですけどね。","respondent":"富田教育改革担当課長","answer":"小中一貫校の結果として周辺校が統廃合につながるのではないかというご質問ですけれども、代表質問でもお答えしておりますとおり、プラン２１または小中一貫校につきましても、統廃合を前提としたものではないです。","voiceIndex":280,"id":"exchange-127"},{"speaker":"沢田委員","kind":"質問","question":"それはわかりますよ。そう思っていないというのはわかるんだけど、そう思ってやった結果がどうなるかというのは、また別問題だというように思うんですよ。統廃合を目指してそのことをやっているんでないということはわかったんです。小学校６年まではいいけれども、６年卒業したときには、この一貫校に入れるんですか、必ず。","respondent":"富田教育改革担当課長","answer":"小中一貫校の対象児童等々、そういった具体的なことにつきましては、今後設置いたします小中一貫校準備委員会の中で検討してまいる課題の一つです。","voiceIndex":282,"id":"exchange-128"},{"speaker":"沢田委員","kind":"意見","question":"小中一貫校は、教育長も答えているけども、小学校と中学校の垣根をなくして、９年間一貫した教育をやることによって、小学校から中学校に上がるときのストレスだとか、シームレスに子どもたちを教育したいという、こういうことで一貫校ができているわけですね。一貫校に入れないかもしれない。だから、そこのところどうなのかということを聞いているんで、ちょっとお答え願いたいと思います。","respondent":"富田教育改革担当課長","answer":"私どもも各──例えば第二日野小ですとか、第三日野小学校ですとか、ＰＴＡの役員の方を回ってご説明しております趣旨と申しますのは、そういった具体的な対象児童がどうなるのか、そういった課題は大変大きな課題であるというふうに認識をしております。","voiceIndex":284,"id":"exchange-129"},{"speaker":"沢田委員","kind":"質問","question":"小中一貫校の策定経費を予算化するときに、そこのところをきちっとしておかなければだめなんじゃないですか。三日野も行かなくなっちゃうという不安があるんですよ。だから、統廃合するという意志があるかどうかというのは、私はおそらくないと思いますよ。だけど結果的にそういうことになるということに対して、こうだから安心してくださいということを私は言うべきだと思うんですが、教育長、いかがですか。","respondent":"富田教育改革担当課長","answer":"先ほどから申し上げておりますとおり、私ども、そういった課題がさまざまあるのは承知しております。したがいまして、小中一貫校の準備委員会、早急にその辺の課題、さまざまある課題を洗い出しながら、一つ一つ解決をしていきたい、決定をしていきたいです。","voiceIndex":286,"id":"exchange-130"},{"speaker":"沢田委員","kind":"質問","question":"で、新しい物事をやるときに、やはり関係者に不安を与えるようなことがあっては、私はならないと思う。例えば、小学校は１学年３クラスで、中学に行けば４クラスだから、希望者は大体吸収できるから、どうぞ地元の小学校に入ってください、安心してくださいと、そういうふうに言えばそんな問題はないと思います。ここは、ぜひ教育長なり次長のほうで、どう考えているのかお答え願いたいと思います。","respondent":"指田教育次長","answer":"そうではなくって、委員会でもって持っていくわけですから、そこでもって話をちゃんとまとめて、整理をなるべく早く出していきたいということでもってお答えをしているところであります。","voiceIndex":288,"id":"exchange-131"},{"speaker":"沢田委員","kind":"質問","question":"これをもう１度、皆さんの声を聞いて、やるのかやらないのかも含めて、皆さん、声を出してくださいというスタンスならいいですよ。これはもっと具体化に向けて、委員会、部会をつくってどんどん進めるということですから。で、これはなかなか答えていただけないので、ちょっと別の角度から質問したいと思うんですが、学校の、中学校の教育で、公民で、地方自治をどのように教えるでしょうか。","respondent":"青木指導課長","answer":"突然の質問で、今、とまどっておりますけれども。中学校の公民でも、小学校の社会でも、やはりよき社会の一員として、どのように物を考えるのかというようなことを常に指導しています。","voiceIndex":290,"id":"exchange-132"},{"speaker":"沢田委員","kind":"質問・要望","question":"１学年、小学校３年生、４年生、そして体育館まで取り組んで、調査経費までつけちゃって、さあ、これを具体化するために、皆さん、聞いてくださいというんでは、この中学校で教えている地方自治とは何なのか、住民の意思で決定していくんだということに教育委員会が反してないでしょうかね。ちょっとその辺の見解を聞かせていただきたいと思います。","respondent":"富田教育改革担当課長","answer":"したがいまして、私どもも、またこちらの議会が終わり次第、それぞれの中で話された状況等々もちまして、また要請があれば各ＰＴＡの役員たち、ご説明に上がりたいと考えていますし、準備委員会での動き等々につきましても、それぞれの関係の学校のほうにも。","voiceIndex":292,"id":"exchange-133"},{"speaker":"沢田委員","kind":"質問・要望","question":"そうしますと、まだ決まっていないんだから、この計画はゼロから見直すこともあり得るということですか。そこのところを答弁していただきたい。進め方については皆さんの意見を聞くというのか、小中一貫校を、日野中を移設してやるという計画そのものを見直す余地があるのか、どちらなんでしょうか。","respondent":"富田教育改革担当課長","answer":"小中一貫校につきましては、第二日野小学校の地に、第二日野小学校の改築とあわせ、日野中学校移転・改築、この方向は決まっております。こちらで決めていただくことと考えております。","voiceIndex":294,"id":"exchange-134"},{"speaker":"沢田委員","kind":"質問","question":"そうするとね、第四日野小学校や一日野や第三日野小学校を残したい、不安だ、小中一貫校は困るという声があっても、既に結論決まっちゃってるんじゃないですか。まあ、これをいつまでやってもしようがないので、少し違う観点からも聞きたいと思うんですが、これまで関係地域といいますか、あるいはＰＴＡだとか、どんな説明をしてきたのか、どんな意見が出ているのか、お答え願いたいと思います。","respondent":"富田教育改革担当課長","answer":"これまで、２月８日のプレス発表以降、日野中学校のＰＴＡの役員、また大崎第一町会自治会連合会の役員、第二日野小学校ＰＴＡの役員、また中学校ＰＴＡ連合会の役員、小学校ＰＴＡ連合会の役員、第三日野小学校ＰＴＡの役員等々にご説明を申し上げてきております。","voiceIndex":296,"id":"exchange-135"},{"speaker":"沢田委員","kind":"意見","question":"今、言った中に第四日野が入っていないんですけれども、なぜ第四日野が──ちょっと聞き逃したらごめんなさいね、入っていないのか、ちょっと説明願えますか。","respondent":"富田教育改革担当課長","answer":"こちらでは、要請があれば説明に伺いますということを、学校長を通してお話をしておりまして、要請があったところに伺ったという経緯です。","voiceIndex":298,"id":"exchange-136"},{"speaker":"沢田委員","kind":"質問","question":"こういう不安が出ているのに、要請がないと行かないんですか。私は、こういう新たな施策を展開するときに、まず決める前に、こういうことを考えているけれどもどうなんだ、このことを先行して、住民の声に、不安にこたえ、物事を決めるというのが地方自治体のあるべき姿じゃないんでしょうか。話を聞いてきました。それで、こういうときがあるときに、第四日野小なんか、もう真っただ中じゃないですか。","respondent":"指田教育次長","answer":"一貫校のことにつきましては、この間、プレス発表が終わった時点で、各校長先生を通じて、私どもの考え方はお話をしてきております。そういう中において、今、お話しがありました第一日野、あるいは第四日野、そこにもやはり校長先生に伺いました。もちろん第三日野も同じです。","voiceIndex":300,"id":"exchange-137"},{"speaker":"沢田委員","kind":"質問","question":"大変誠実さに欠けるというふうに思いますね。一方で、小学校から中学校に上がるのをスムーズにストレスなくと言いながら、そのほかの子どもに対しては中学校をどこに選ぶかと、不安をこんなに拡大するのが公教育でしょうか。私は、入った子だけじゃなくて、入れない子、悩んでいる子も同じように不安を取り除くのが教育だ、そのことを指摘して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":302,"id":"exchange-138"},{"speaker":"船波委員","kind":"質問","question":"第一は、小中一貫校についてですが、これはプレス発表の資料では、小中一貫校関連として２,０００万円計上されていて、予算書を見ると、小中一貫校基本計画策定経費というところで２,０００万円予算が計上されているので、小中一貫校関係では、この基本計画策定にすべてが費やされてしまうのかなと思うんですけれども、その内容はどういうものになっているんでしょうか。","respondent":"鷹倉庶務課長","answer":"したがいまして、ソフト面のものを、基本計画のハード面に反映していくという意味で、十分この部分で対応できるのではないかというように考えております。","voiceIndex":304,"id":"exchange-139"},{"speaker":"船波委員","kind":"質問","question":"あまりにも少ない人数でする教育でいいのかとか、あるいは少ない子どもたちのために一つの学校を維持するための費用が、まあ、すごくかかると思いますけれども、それほどの費用をかけていていいのか、もしかしたらほかにもっとまとめて、効率的な費用の使い方もあるのではないかとか、小中一貫校ができるできないとか、学区域の自由化、自由な選択に関係しないところで。","respondent":"鷹倉庶務課長","answer":"そしてまた準備委員会に上げていくと。こういうものを地域の中に、先ほど教育改革担当課長が申しましたとおり、地域の中に説明してまいります。この部分については特に経費がかかるわけではなくて、我々が出向いていっていろいろ説明する。","voiceIndex":306,"id":"exchange-140"},{"speaker":"船波委員","kind":"質問","question":"統廃合に関しては、地域から声が上がってきたら、そのときに考えるということですけれども、でもやはり教育委員会として、品川区の子どもたちの教育にとってどういった学校の配置がいいのかということを教育委員会として考えるべきではないかと思いますけれども、どうなんでしょうか。","respondent":"久保田学務課長","answer":"そういう点ではこの間、プラン２１でそれぞれの学校の取り組み、特色ある学校づくりの取り組みについて、教育委員会は全面的に支援してまいりましたので、例えば小規模の学校につきましても、そういうスタンスでもってやってきておりますので。","voiceIndex":308,"id":"exchange-141"},{"speaker":"船波委員","kind":"質問","question":"次は小学校の国際理解教育についてですが、プラン２１の資料を見ますと、国際理解教育なんですけれども、括弧として英語教育の推進になってしまっていて、予算の明細を見ても、５～６年生の各学級に１０時間、英語の先生を配置するということになっていますけれども、このプラン２１の国際理解教育の内容にリストされている、英語教育以外の事柄を行うにも。","respondent":"青木指導課長","answer":"本区におけます小学校の国際理解教育ですが、今、英語がどれだけ重要な外国語になっているかという認識のもとに、私どもはこの国際理解教育を考えております。それで、中学校でも、本区では英語が外国語ということで、全校で英語に取り組んです。","voiceIndex":310,"id":"exchange-142"},{"speaker":"船波委員","kind":"質問・要望","question":"全区一斉にすると、やはり点数がよいところ悪いところというのが出てきてしまうかもしれませんけれども、そういったことで子どもたちがやる気をなくしたりとかしないようにするための対策は、どういうふうに保証していくんでしょうか。","respondent":"青木指導課長","answer":"異文化理解につきましては、ボランティア活動も導入していますし、それからまちの人から学ぶという授業もやっております。全区的に行う学力調査につきましては、やはり今プラン２１を進めているこの品川区という自治体として学力を把握したいという考え方です。","voiceIndex":312,"id":"exchange-143"},{"speaker":"石田委員","kind":"質問","question":"もう１個、もう１点やりたいのは、国旗国歌をやりたいと思いますが、国旗国歌からまずお伺いをしたいと思います。国旗国歌、小学校１年生から指導しているという話でありますが、まずどのような指導を１年生からしていくかというところをお聞かせ願いたいと思います。","respondent":"青木指導課長","answer":"それぞれの学年においては、社会科の時間だとか、それから音楽の時間だとか、そうした時間を通して、国旗とは何か、国歌とは何かというようなことを、それぞれの発達段階にふさわしい形で指導しております。","voiceIndex":315,"id":"exchange-144"},{"speaker":"石田委員","kind":"質問","question":"時間もあれなんで、端的に言います。」。どういうふうにあと言われたか。これは、どういう指導があったかはわかりませんが、これは小学校２年生ですから、小学校２年生にこういう、今、論議になっているようなことが、こういうことがあっていいのかなと、ちょっと私は思うんですが、そういうことがどういうふうに、教育委員会としてどういうふうにとらえているかというところだけ、ちょっとお聞かせください。","respondent":"青木指導課長","answer":"国旗や国歌に対しての指導については、一面的な指導ではないかなというふうに認識しています。","voiceIndex":317,"id":"exchange-145"},{"speaker":"石田委員","kind":"確認","question":"それ意味がよくわからないんだけれども、そういう一面的な指導がそういうふうにあるということを、教育委員会として、そういう情報を校長先生を通じてでも何でもいいけれども、私もそれを言われて、何人か確認したらやっぱりそんなことがあったから、やっぱりそういうことがあるんだけれども、教育委員会としてそういうことを把握しているのかどうかというところを……。","respondent":"青木指導課長","answer":"そのような指導があったということは、今、初めて聞きました。","voiceIndex":319,"id":"exchange-146"},{"speaker":"石田委員","kind":"質問","question":"ですからね、そういうことが把握ができていない、把握できてないんならできてないで、今後そういうことを、例えば１年生、今、発達段階でこうだっていうことがあると思いますが、１年生の段階では儀式でも、まあ、それが２年生なのか３年生なのか、私はわかりませんが、そういうところをどのように、逆に教員に対して指導していこうということをお考えなのか、お考えがあったらちょっとお聞かせください。","respondent":"青木指導課長","answer":"今、改めてこの国旗国歌問題について、もう論議する時代ではないというふうに私は認識しております。","voiceIndex":321,"id":"exchange-147"},{"speaker":"石田委員","kind":"質問・要望","question":"それは、必ず校長先生を通じてでも、校長会でも、強硬にそこら辺のところはやっていただきたいと思います。そういう話が出てくること自体、私はおかしいと考えていますんで、そういうところをひとつよろしくお願いを申し上げます。そういう情報が、校長先生同士の間とか、そういうのが流れないというのかな。ちょっとそこら辺を教えていただきたい。","respondent":"青木指導課長","answer":"こういう研修会の折りに、それぞれの推進校の取り組みや、こうしたまちの人々に学ぶ授業の情報交換等はやってありますので、今、委員ご指摘のように、こういうボランティアの方の取り組み、こういうまちの人から学ぶ授業がすばらしかったというような内容については。","voiceIndex":323,"id":"exchange-148"},{"speaker":"石田委員","kind":"質問","question":"あわせてお聞きしたいのは、私がわかっている範疇で言いますと、それの広まりというのは非常に弱いのかなと考えていますし、また、企業がいろいろ品川区に対してボランティアというかそういう形で、いろいろな、まちの人から学ぶという形のいろいろなおもしろいことをしてくださる、そういうところについては、企業のことも広めていくというか、そういうところもどういうふうにお考えなのか。","respondent":"青木指導課長","answer":"今後もこうした、企業と学校がどういうような形で実際にできるのかというようなことを検討してまいりたいと思いますし、また、そうした声があればぜひ、こちらのほうでも受けとめていきたいというふうに考えております。","voiceIndex":325,"id":"exchange-149"},{"speaker":"石田委員","kind":"質問","question":"今の点を、もし話があってから進めるというんではなくて、現実にもう起こってて、その評価というのは多分出てるわけですよ。そういうところがせっかく、品川区にそういう企業がいるんであれば、教育委員会のほうから出ていって、そういうのを品川区中、済みません４０校あるんだけどやってくださいとか、そういう動きをかけられるのは教育委員会だと思うんですが、そこら辺のご見解をお願いします。","respondent":"青木指導課長","answer":"実際に今お話のありました、企業が学校にこういうような場を提供する、こういう機会を提供するというようなことも含めて、私どものところにもいろいろとお声がかかってきてありますので、積極的に取り入れて、全区的な形で取り組んでいきたいというふうに考えております。","voiceIndex":327,"id":"exchange-150"},{"speaker":"石田委員","kind":"質問・要望","question":"このことについては、ぜひぜひ対応していただきたいと思います。だから、先ほども８日間か９日間かわかりませんが、今度夏休みは多く出てこなくちゃならないというような日にちができてくるわけですけれども、まずこの就業体系を、例えば父母とかそういう方たちに全面的に例えば明らかにしていくとか、そういうところのお考えはあるのかないのか、そこら辺をちょっと教えていただきたい。","respondent":"青木指導課長","answer":"こういうようなことで大きく教員の勤務のあり方が見直されるということにつきましては、それぞれの学校でも今、どのような形で今後、夏休み等も含めて、教員に考え方を徹底させるのかというところで取り組んでいるところですので、今後も保護者に対しても。","voiceIndex":329,"id":"exchange-151"},{"speaker":"石田委員","kind":"質問","question":"そういうことを、今の勤務体系はこういう状況の中でやってるということを、父母とかに地域にも知らせて、それで一緒になって一体でやりましょうというのが、本来の地域も父母も学校も含めて一体となることなんだけれども、何か教員だけ、こういうことでこれから指導して、一人ひとり頑張っていきますという答弁ばっかりなんで、そこら辺のことをどうお考えなのか、最後にそれだけをお聞きしたい。","respondent":"指田教育次長","answer":"そういう姿勢のもとに、今お話が出ましたことについても、機会をとらえながら父母の間、あるいはＰＴＡを通してといいましょうか、そういう中でもってお話しをして申し上げていきたいというふうに思っています。","voiceIndex":331,"id":"exchange-152"},{"speaker":"上山委員","kind":"質問","question":"先ほど石田委員のほうから、日の丸・君が代でどういうふうに教えているんだというような趣旨の、ちょっとあったかと思うんですけれども、改めて伺いたいんですけれども、今の学習指導要領でどういうふうなことを、例えば、あんまり細かくはいいんですけれども、小学校はこういうふうに教える、あるいは中学校でこういうふうに教えている、ありましたら、ちょっとご答弁いただければありがたいんですが。","respondent":"青木指導課長","answer":"いろいろな場面がありますけれども、例えば学校行事などでは、入学式や卒業式などにおいては、その意義を踏まえ、国旗を掲揚するとともに国歌を斉唱するように指導するものとするというような形で学習指導要領に位置づいております。","voiceIndex":334,"id":"exchange-153"},{"speaker":"上山委員","kind":"質問","question":"中身について、先ほど石田委員でもちょっとありましたけれども、どこかの学校で、君が代の「君」は天皇と教えたとか、よくわかりませんけれども、違ったら申しわけないんですが、日の丸がそういうふうに侵略戦争のときに使われたというふうに、まあ、そういうふうなこともあったというんですけれど、そういうふうなことまで何か教えるとなっていらっしゃるんでしょうか。","respondent":"青木指導課長","answer":"具体的にはそういうような形で学習指導要領には示されておりません。","voiceIndex":336,"id":"exchange-154"},{"speaker":"上山委員","kind":"質問","question":"それで、例えば日の丸の問題でいえば、もちろん日の丸はそうだとは言いませんよ、何も侵略戦争の、単純なそういうふうに、もともと使われたということではありませんけれども、そういうふうな占領されたところでたたえられたということがあるかもしれませんけれども、改めて、何ていうんでしょうかね、どういうふうに、例えば今、ある子どもが言っていたっていうんですけれども。","respondent":"青木指導課長","answer":"小学校４年生の社会科の時間に、我が国や外国には国旗があることを理解させるというような指導があります。ほかにもいろいろな場面でありますけれども、要するに国旗として日の丸を教える、国歌として君が代を教えるです。","voiceIndex":338,"id":"exchange-155"},{"speaker":"土井委員","kind":"質問","question":"るる出ておりますが、私もプラン２１関連ということで絞りまして、お伺いをしていきたいというふうに思います。ほんとうにある意味でありがとうございました。そして、その対象等々によっては、これの中身のつくりはこれでいいのかなということ等があるものですから、まずそれを１回最初に聞かせてください。","respondent":"青木指導課長","answer":"それで、対象は、そこの参観者は学校関係者が多いわけですけれども、私ども、プラン２１のこの冊子につきましては、教育関係者のみならず、学校関係者のみならず、多くの方に、今、品川区が進めているプラン２１の現況を知っていただきたいという、そうしたねらいをもって作成し。","voiceIndex":341,"id":"exchange-156"},{"speaker":"土井委員","kind":"質問・要望","question":"そういうふうに確認させてください。そうすると、本来的には、学校教育関係者だけなら、これでもまあしようがないな、指導要領の言葉がずらっと並んでくるわけですから、それはそれでいいとすればいいんでしょう。例えば、この教育のところで、先ほど基礎基本は読み書き算数ですか、算ですね、だというんだけれども、それは言ってみれば、最終的に生きる力をつけるための道具としての中身ですよね。","respondent":"青木指導課長","answer":"冒頭ですが、このプラン２１の説明に当たって、ちょっと問題がある、具体性に欠ける、ちょっとわかりづらいというような点がございました。２ページ、３ページでは基本的な考え方を示させていただきました。","voiceIndex":343,"id":"exchange-157"},{"speaker":"土井委員","kind":"質問","question":"お答えをいただいていないんで。要するに、それらを含めた時限のもの以外の時限は何時間あるんですか。そしてその中で、今言ったここで、英語では少なくとも年間５時間だとかとられるわけでしょう。そうすると、全体ほかはどうなるんですか、どう配分されるんでしょうねということを伺ったんです。","respondent":"青木指導課長","answer":"時間ですが、来年度より総合的な学習というのが、年間１０５時間予定されます。それで、今、委員がご指摘された小学校の国際理解教育や、中学校における福祉教育とかふれあい教育というようなものも、その１０５時間を活用して進めていきたいというふうに考えております。","voiceIndex":345,"id":"exchange-158"},{"speaker":"土井委員","kind":"質問","question":"わかりました。７０時間。そこら辺をひとつ、お伺いをしたいというふうに思います。平均値が上がる。それは、逆の意味で、先ほど一番最初に言った、習熟度学習のところに具体的にどうなさるんですか、グループ別ですよとおっしゃった。グループ別ですよというのは、部屋を別にするんですか、どうなんでしょうか、ということ等も起こるわけですね。グループ別というのはいろいろ考え方があるわけですから。","respondent":"青木指導課長","answer":"二つ目ですが、学力調査です。そういう、それぞれの学校間の競争というような認識で実施するようなことではございません。やはり一人ひとりの子どもたちの学力の定着度というものを測定できるような、そうした調査にしたいというふうに考えてあります。","voiceIndex":347,"id":"exchange-159"},{"speaker":"土井委員","kind":"質問・要望","question":"これがちょっとわからないと先ほど申し上げましたが、もう一つわからないのは、そのまた後ろに行くと、これはまあ、研究課題ですからいいんですけれども、「系の学習」、その辺を、後から調査権を使わせていただいて聞かせていただきますけれども、まあ、要するに新しい言葉がぽろん、ぽろん、ぽろんと突然出てくるというのでは、どうにも理解ができないという形になるんですね。一言だけ。","respondent":"若月教育長","answer":"後段のほうなんですけれども、先ほどもどなたかのご質問にお答えいたしました。流した汗には報おう。報えるだけ報おう、それだけのことであります。決してそこにおいて、何かの感情や、あるいは別の要素が入るということはありません。","voiceIndex":349,"id":"exchange-160"},{"speaker":"南委員","kind":"質問","question":"私は３０人学級について質問をしたいと思います。品川区の教育委員会はこの間、ＴＴ、チームティーチング、そして今年度からですか、少人数加配をし、少人数での授業、工夫をしているというふうに聞いておりますけれども、その現況と、その効果はどういうふうにあるのかということをちょっとお尋ねします。","respondent":"青木指導課長","answer":"小学校では１９校、２１名の加配をいただいております。中学校では１８校、３３名の加配という状況です。それぞれの学校では、チームティーチング、少人数加配、この教員たちの活用をしまして、先ほども話題になりました習熟度別学習等も含め、成果を上げているところです。","voiceIndex":352,"id":"exchange-161"},{"speaker":"南委員","kind":"確認","question":"成果がある、少ない人数で教育することは教育成果があるという、そういうことでいいんですか。もう１回、ちょっと確認をしたいと思うんですけれども。ですから、こういう動きについて、品川区の教育委員会はどういうふうに評価をしていらっしゃるのか、ちょっとその点についても伺いたいと思います。","respondent":"青木指導課長","answer":"したがいまして、ほかにいろいろ学校では教育活動に取り組んですが、このチームティーチングや少人数加配というのは、その学習の状況、学習の内容、それにふさわしい形で、方法として取り入れているというところで、評価をしています。","voiceIndex":354,"id":"exchange-162"},{"speaker":"南委員","kind":"質問・要望","question":"教育の、学習の面での効果のみという、そういうことなんでしょうかね。ですから、１５の県で、何らかの形で実践をしているというふうに思うんですが、そういう意味で私は、３０人学級をぜひとも実現していただきたいというふうに思っているんですが、このことをずっと一貫して、私どもは議会のごとに強調もし、実現を要求してきましたけれども、なかなかそこには踏み出していない。","respondent":"久保田学務課長","answer":"これは、山形のほうでやられているものと若干似通っているところもあります。そういう形で東京都のほうは現在進めておりますが、基本的な４０人学級という考え方に変更する考えはないというふうに聞いております。","voiceIndex":356,"id":"exchange-163"},{"speaker":"南委員","kind":"質問","question":"こういう点で３０人学級だって、何でやろうとしないんですか。３,３００の自治体のうちの１,６５８ですからね、過半数ですね。半分ですよ。そういうところで品川区がこれだけの教育改革をやろうってところに、どうして３０人学級だけ手をつけないんでしょうか。そこのところをどういうふうに解決しようとしているのか、そこについてもきちんとした姿勢も私は伺っておきたいというふうに思います。","respondent":"久保田学務課長、青木指導課長","answer":"そういう点では問題があるような学級の状況については、やはり授業の中で起こってくるわけですので、そういう授業の中を先ほど話したＴＴとか、あるいは習熟度別学習ということで、綿密な形で。そういう意味で、人数の問題というよりは、私はこの学校の指導上の問題が今回皆さんにご心配をかけているようなところにつながっていったのではないかなというふうに考えておりますので、教育委員会としましても、生活指導。","voiceIndex":358,"id":"exchange-164"},{"speaker":"南委員","kind":"質問・要望","question":"学習と生活を分けてというふうな、そういう立場に立っているという話なんですが、私は１日のうちの、まあ何時間でしょうか、朝の８時半から夕方３時、４時ぐらいまで学校生活しますね。そうだと思うんですね。そういう授業のあり方っていうものについては、教育委員会としてはどういうふうな見解を持っていらっしゃるか、ちょっと伺いたいと思います。ですからその点についての見解をお願いします。","respondent":"青木指導課長","answer":"したがいまして、生活面と学習面では、やはり規模というものを考える必要があるんではないかなというふうに受けとめております。","voiceIndex":361,"id":"exchange-165"},{"speaker":"南委員","kind":"質問・要望","question":"私は要望にとどめますが、財政の問題で言えば、極めて東京都の問題ですから、東京都にしっかりと少人数学級ができるように、財政の確保をしろということを事あるごとに言っていただきたいと思います。先生が一人ひとりの生徒と対話ができない。だから何を考えているのかわからない。ですから、ぜひその方向で品川区も頑張って教育改革していただきたいということを言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":363,"id":"exchange-166"},{"speaker":"三上委員","kind":"質問","question":"３００ページ、教育指導費、それから３２５ページ、学習振興運営経費、施設予約システム開発委託についてお伺いいたします。時間によってはもう１点伺うかもしれませんという予告だけしておきます。そのあたりの稼働的な部分というのは今どうなっているのか、そこらだけちょっと先にお伺いしたいと思います。","respondent":"久保田学務課長","answer":"コンポスト、生ごみが大体１個当たり８トンぐらい出ますけれども、それの大体６分の１ぐらいコンポスト化されているというような状況です。","voiceIndex":365,"id":"exchange-167"},{"speaker":"三上委員","kind":"質問","question":"今、答弁の中から、環境教育にということでこのコンポスト化した肥料になってくるんでしょうか。","respondent":"青木指導課長","answer":"今、委員のご質問にもありましたように、どこの学校でも環境教育というものは、社会科なり、家庭科なり、理科なりというような中で実施しています。","voiceIndex":367,"id":"exchange-168"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、これは生ごみ処理器が設置されている学校、特に小学校１６校、中学校が９校ということであるわけですね。そうすると、そういった設置されていない学校についてどういった取り組みをするか、これが問題になってくると思うんですけれども、そこらあたりどういうお考えでしょうか。","respondent":"久保田学務課長","answer":"生ごみ処理器を設置していない学校についての対応ですけれども、現在これは清掃リサイクル課で進めております生ごみ処理事業の中に、すべて運んでいただいてコンポスト化しています。","voiceIndex":369,"id":"exchange-169"},{"speaker":"三上委員","kind":"提案","question":"こういうことだって言えるわけです。私は平成５年の第４回定例会で、家庭用の生ごみ処理器を導入したらどうかと提案しましたね。価格も３万円ぐらいから、今、現実ありますよね。容量的にも。だから残っているその行われていない小学校、１６校以外で、だから２４校になるんでしょうか。そこで持ち回りでそれをこういうふうにした形で子どもたちの目の前でやってあげたって、それはいいんじゃないでしょうか。","respondent":"久保田学務課長","answer":"そういう形でやっている学校もあります。それからもう一つは清掃リサイクル課で、今度別の場所でコンポスト化しているんですけれども、それをフィードバックしてもらうということも、これは可能だと思いますので、その辺についても今後検討していきいというふうに考えています。","voiceIndex":371,"id":"exchange-170"},{"speaker":"三上委員","kind":"質問・要望","question":"そこらあたり、いろいろな知恵を出して、そして取り組んでいっていただきたいと、これはお願いしておきたいと思います。図書館のほうは質問しませんけれども、テニスコートとか、野球場、体育館、文化センターや区民集会場などの会議室、ホールなどの４０施設を対象とするということになっているんで、もうちょっと４０施設の具体的な説明をお願いできませんでしょうか。","respondent":"上川内生涯学習課長","answer":"スポーツ系につきましては、公園、テニスコート、野球場６施設、それから体育間の２施設、それから会議室や集会場、ホール系などの施設につきましては、平塚橋会館、区民集会場１４カ所、荏原区民センター、中小企業センター、メープル、Ｏ美術館、区民ギャラリー。","voiceIndex":373,"id":"exchange-171"},{"speaker":"三上委員","kind":"提案","question":"私は平成４年の一般質問で、第３回定例会で、この問題について具体的にもうちょっと突っ込んで提案している部分があるんです。４０施設というだけで終わってしまっている。お金のやりとりだってその場でほんとうはできるのに、やらないで、銀行なりいろいろなところに行って振り込みをやるという仕組みをまだ今でもとっているんじゃないかと思うですけれども、そこらあたりはどうなんでしょうか。","respondent":"上川内生涯学習課長","answer":"学校につきましては、スポレク推進委員会というのが今、学校ごとに調整をいたしております。その調整の機能を生かして、同じテーブルの中で調整したほうがいいということで、ここの対象の施設からは除外しております。","voiceIndex":375,"id":"exchange-172"},{"speaker":"三上委員","kind":"質問","question":"そのスポレク推進委員会でいろいろやっていることによって、これもあれですよね、１カ月前にはこの調整会議やりますよね。それで、一般の人が借りようとすると、その調整会議が終わって、登録団体になってなきゃ借りられませんでしょう。どうなってるんでしょうか、そこは。","respondent":"上川内生涯学習課長","answer":"登録団体でなくても、一般の方でも借りられます。","voiceIndex":377,"id":"exchange-173"},{"speaker":"三上委員","kind":"質問","question":"じゃあ借りられるということになって、それはいいことだと思いますけれども、そのときのお金の納金というのは、学校を借りた場合は、どういう今、仕組みになっているんでしょうか。それは調整会議なら調整会議のときに申し込んだらそこでできるけれども、それ以降、その学校に申し込みに行った場合には、どういう仕組みになっているんでしょう。","respondent":"上川内生涯学習課長","answer":"申し込みの調整会議に間に合わなかったような場合は、学校のほうから申請したときに納付書をもらって、それで銀行のほうに払い込むことになっています。","voiceIndex":379,"id":"exchange-174"},{"speaker":"三上委員","kind":"意見","question":"納付書をもらって、それで過去に私はこういう納付書の問題で言ったことは、納付書の銀行に支払いましたという、領収書を持ってこいということになっていたんですよね。それは改善されていますか。","respondent":"上川内生涯学習課長","answer":"同じです。","voiceIndex":381,"id":"exchange-175"},{"speaker":"三上委員","kind":"確認","question":"全く変わっていないということですね。むしろそういったことをなぜ変えられないのかということを。その領収書を持ってきて、その当日持ってきてそれで確認したもので、それで貸してくれるという仕組みだったんですね。ですから結局はその間、領収書を処理ができないと。要するに借りた側の人は。ということで１カ月以上その処理ができないということは、まだ続いているんですか。","respondent":"鷹倉庶務課長","answer":"したがいまして消し込みを素早くとらえて、こちらから窓口では納付書を見なくても、あるいはこちらから払っていない人の追及をできるような流れを研究して実現していきたいなと、このように考えてあります。","voiceIndex":383,"id":"exchange-176"},{"speaker":"三上委員","kind":"確認","question":"こういうことにならざるを得ないわけですから、その料金の支払い体系までも、きちっとした考え方の中に入れてやってもらいたいと。振り込んだら振り込んだで、それで済んだという形で、確認は品川区がやらなきゃおかしいじゃありませんか。入ったお金について、事務的に連絡するという仕組みになればいいわけですから、それをなぜやれないのか。ちょっとお考えを聞きたい。","respondent":"鷹倉庶務課長","answer":"今、申し上げましたとおり、これから消し込みを即座に私ども電算を使いながらとらえるようなことができれば、かなり時間的な制約が解消されますので、利用者にご不便をかけないような形の方向性が打ち出せると、このように考えてありますので、ご了解いただきたいと思います。","voiceIndex":385,"id":"exchange-177"},{"speaker":"松澤委員","kind":"質問","question":"最後ですので短く２点か３点お聞きします。昨年の第４回の定例会の一般質問の中で、品川区における教育の諸問題についてということで幾つか質問いたしました。その後のお話を伺いたいと思います。実はこのプラン２１の新しい中にも何ページですかね、７ページに書いてありますけれども、１１月の中学生の新１年生希望申請集計表。今現在、実際にその学校、入学数は何人ぐらいいるのでしょうか。お願いします。","respondent":"久保田学務課長","answer":"当該の学校につきましては、入学予定者数９名です。","voiceIndex":388,"id":"exchange-178"},{"speaker":"松澤委員","kind":"質問・要望","question":"結果で言うのは大変に申しわけないとは思うんですけれども、この９名という数字ですね、答弁の中でも述べていただきましたけれども、校長、教員が一生懸命回っているんだ、教育委員会も一生懸命やっているんだという中で実際９名。これについてのコメントをいただきたいと思います。","respondent":"青木指導課長","answer":"この９名の新入生が４月に参ります。その新入生に対しまして、学校としても精いっぱいの対応をしていきたいと思いますが、教育委員会といたしましても、こういうような状況を正確に分析しまして、今後の指導に生かしていきたいというふうに考えております。","voiceIndex":390,"id":"exchange-179"},{"speaker":"松澤委員","kind":"質問","question":"実際に昨年が５０名を超える子どもたちが入ってきて、今年度は９名、予定が。９人の子どもたちがいろいろある中で、この学校を選んでくれたんですからね。保護者の方もいろいろ相談しながら、この学校に行こうよと決めてくれたんだと思いますので、その９人のためにも、この学校はしっかりしなくちゃいけないと思いますので、その決意を一言聞きたいと思います。","respondent":"青木指導課長","answer":"９人のお子さんと保護者の方がこの学校を選んでくださったということを、私たちはほんとに重く受けとめて今後の指導に当たっていきたいと考えております。来年度の教育活動も、学校とともに教育委員会も全面的に支援してまいりたいというふうに考えております。","voiceIndex":392,"id":"exchange-180"},{"speaker":"松澤委員","kind":"質問・要望","question":"これについてコメントをということで伺いましたところ、「現在進められております教育改革は教師の意識改革を伴うことから、意気に感じて意欲を持ち取り組もうとする教員、逆にそれを負担に感ずる教員など、プラン２１を意識し始めた結果が異動にあらわれていると受けとめております」という答弁をいただいております。もし人数がはっきりわかりましたら、わかる人数をお教えいただきたいと思います。","respondent":"青木指導課長","answer":"今年度の異動の人数ですけれども、小学校の転出が１１２名、転入が９２名。中学校の転出が６２名、転入が５２名と、これは学級数の問題とか、加配の問題とかありますので、その予備調査と直接関係があるということではございません。","voiceIndex":394,"id":"exchange-181"},{"speaker":"松澤委員","kind":"質問","question":"たくさんの希望とそして転入者ということで、一応学級減、あるいは退職者、あるいは新規採用という中で、異動の、例えば聞きたいのは、転出希望した方には、皆さん転出希望どおり出せたということでしょうか。","respondent":"青木指導課長","answer":"転入者も含めて、転入者も第一希望で品川区に来られる方もいらっしゃるし、第６希望で来られる方もいらっしゃいますし、そういう意味で希望どおりもちろんいきませんけれども、バランスとしては、今の段階ではバランスよくいっているというふうに考えております。","voiceIndex":396,"id":"exchange-182"},{"speaker":"松澤委員","kind":"質問・要望","question":"２３区のなかでは、品川区のほかに荒川、豊島、今年の４月からは足立、杉並、江東、墨田という２３区中７区、もう３分の１になろうとしている。ですから、どんどんＰＲして、日本全国からほんとにいい教員を採っていただいて、嫌だという教員はどんどん出しちゃう。ほんとに、どんどん全国的に展開をしていただきたいんですが、ひとつコメントをいただきたいと思います。","respondent":"青木指導課長","answer":"そういう意味で中堅、そして新規採用ともに、今後とも教育委員会として、そうした教員を迎え入れて教育改革を推進していきたいというふうに考えております。","voiceIndex":398,"id":"exchange-183"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。頑張っていただきたいと思います。もう１問、実は、学校の校庭照明のことでお伺いしたいと思います。つい先日も学校の教育懇談会に出席しましたところ、父兄の方から自分の子どもはこの学校に入れるんですという話がありました。しかしながらこの学校には照明がないですよという話があったんですね。その点をお聞きしたいと思います。","respondent":"上川内生涯学習課長","answer":"夜間校庭開放ということで、私どものほうで１７地区、スポレクエリア内に１カ所ということを目標にして、総合実施計画の事業として、推し進めております。今、１３年度末で１４校ということになっております。","voiceIndex":400,"id":"exchange-184"},{"speaker":"松澤委員","kind":"質問・要望","question":"時間がないので、要望にしますけども、実は校庭開放、スポーツ開放、夜間開放するための照明となりますと、それはテニスをしたり、ソフトボールをしたりということで、相当明るいルクスが要ると思うんですよ。実は回りから苦情が来る。私は前に防災面でもそういう話をしましたけれども、そういうようなことで照明をなるべく広げていただきたい。その件についてご答弁いただきまして終わりたいと思います。","respondent":"鷹倉庶務課長","answer":"それで、問題は明るくすることによって、近所回りから、困るという部分もないことはないわけで、その辺のところも意見を聞きながら、できるところについては、先ほど申し上げた考え方をベースにしながら進めていってみたいなというふうに考えてあります。","voiceIndex":404,"id":"exchange-185"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=796#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":134279,"voices":406}},{"id":"h14-20020322-3","meetingId":"h14-c-budget","date":"2002年3月22日","dateIso":"2002-03-22","committee":"予算特別委員会","time":"午前１０時０４分～午後６時０６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を111件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"提案","question":"おはようあります。私、初めての総括質疑であり、また身近な区議会を目指してケーブルテレビの放映ということで、テレビカメラが入って多少緊張しておりますが、質問をなるべく簡潔に、また基本的なところを確認させていただきながら、続けさせていただきたいと思います。最初に平成１４年度の予算編成について、お伺いをさせていただきたいと思います。すごく品川区らしいすばらしい状況だなと考えています。","respondent":"中尾根企画部長","answer":"そういうことから、本来の評価とか理解ということについては、この先、具体的に実施したときに、ほんとうの真価が問われるときが来るんではないかと、このように受けとめてあります。","voiceIndex":2,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"提案","question":"それを受けたほうの立場として、その施策の提案に対してどのようにとったのか。それともう１点、事業部制そのものについては、まだ評価をするのは早いと思いますが、この予算編成を通じて、事業部制にしたことの効果、それと、またこれからの事業部制の課題について、どのようにお考えでしょうか、その２点について、お答えをお願いしたいと思います。","respondent":"中尾根企画部長、高橋区長","answer":"新しい事業部制のもとで、うまく回転させる。そのときに、同時に設けました事業部経営会議をうまくやるにはどうしたいいかということを考えた結果として、プレゼンテーションという新しいことを試みました。事業部制の問題ですが、確かに、２３区の中でも品川区が初めて実施をした一つの制度です。","voiceIndex":4,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２点目に、介護保険関係の質問に移らせていただきます。５年目の改定によって、例えば事業内容に絡んできた場合に、６年目の事業実施をしたときには、保険料は既に決まっているわけであり、事業の遂行に対して保険料が足りなくなってくるということが起きてくるのかどうか、そこの２点について、お答えをお願いしたいと思います。","respondent":"新美保健高齢事業部長","answer":"５年目の制度の見直しで、保険料に大きく係わるような見直しがもし実施されるとすれば、当然、実施時期等についての調整等が図られるものと考えております。","voiceIndex":7,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"続きまして、第２期の保険料算定について、お伺いさせていただきたいと思います。第２期のサービス供給量について、どのようにお考えになっているのかをお聞きしたいと思います。それともう１点ポイントになってくるのが、介護報酬の問題が絡んでくると思うんですが、これの見通しとスケジュールについては、どのようになっていくのでしょうか。この辺に対してのお考えを、お聞きしたいと思います。","respondent":"新美保健高齢事業部長","answer":"第１期のときと違いまして、制度導入後、ほぼ２年余の実績が今回は明らかになっておりますので、実績を踏まえつつ、新たな基盤整備の状況、また、その他関連の、例えば医療制度の動向等を勘案いたしまして、平成１５年からの供給量を見込んでまいりたいと考えています。","voiceIndex":9,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問","question":"高齢者人口が増加してきて、また、在宅介護をなさっている方自体がご高齢になっているという状況も踏まえた場合、現在の施設サービスよりも、これから中期的、長期的に、品川区として施設サービスをどのようにとらえていくのでしょうか、その点について、お答えをお願いしたいと思います。これは、以前にもお聞きしているんですが、再度、お答えをお願いしたいと思います。","respondent":"新美保健高齢事業部長","answer":"それ以降の施設の整備につきましては、介護保険事業計画の改定の中でも検討していくわけですが、ケアホームのような形の施設がいいのか、痴呆性グループホームのベッドをつくったほうがいいのか、あるいは、それ以外の類型があるのか、多様な施設のあり方について十分検討し。","voiceIndex":11,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"介護保険の準備基金について、お伺いさせていただきたいと思います。その中において、介護保険制度を、これから長い目で安定的に運用していくためには、この基金のすべてを使ってしまうと、今後の保険料にかなりの跳ね返りも出てくるのではないかと思うんですが、この辺について、大切に扱っていただきたいという思いの中から、お答えをお願いしたいと思います。","respondent":"新美保健高齢事業部長","answer":"私ども品川区といたしましても、やはり制度の安定的、継続的、あるいは健全な運営という視点から、来期についてどこまで見るか、どの程度準備基金としてどの程度取り崩すか、あるいは残すかということを含めまして、今後の作業の中で十分検討をし。","voiceIndex":13,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"介護報酬については秋からのスタートという部分はあると思うんですが、もう、すぐに始まっていくので、いろいろ検討している中に、議会の中の声も生かしていただきたいと思いますが、ぜひ、よろしくお願いしたいと思います。介護保険に関して、もう１点、お聞きします。医療態勢という意味と、２点、お答えをお願いしたいと思うんですが、よろしくお願いいたします。","respondent":"新美保健高齢事業部長","answer":"そういった病院との間でかかりつけ医調整委員会といった組織を持っておりますので、そういった場を活用しながら、地域の住民が医療面での不安がないような対応を、地域の医療機関、あるいは病院と十分対応がとれるようなことを検討するようにしていきたいと考えています。","voiceIndex":15,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"当然、介護保険にかかわる部分がかなり多いと思いますので、その辺も踏まえた上で、ご検討をよろしくお願いしたいと思います。次の項目として、大井町駅東口の関連について、お聞きしたいと思います。その中で、大井町駅東口のＣ地区をどのように考えていくか、その点について、お聞きしたいと思います。それを前提にして、お答えをお願いしたいと思うんですが、よろしくお願いいたします。","respondent":"岩野まちづくり事業部次長","answer":"休止に至った理由につきましては、例えば、バブルが崩壊いたしまして、非常に経済状況が悪くなったということで、実際に再開発を実施しても、ほんとうに床が売れるのかどうかといった事業採算が見えないような形で、現況のように、戦後のああいったような形で残っているです。","voiceIndex":17,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺も考えていくと、どうなのかという点が１点あるんです。その点を踏まえて、また品川区として、あの辺にどんな夢を持った場所がつくれるのかというお答えも、ちょっとお聞きしたいと思います。例えば、あの辺を考えた場合、商店街との兼ね合いを考えた場合、他の事業部とどのようなつながりを持っていらっしゃるのか、その２点について、お答えをお願いします。","respondent":"岩野まちづくり事業部次長","answer":"今は、補助１６３号線が一本橋の商店街を通りますので、そういったようなことについても、まだ事業計画の認可は下りてございませんが、その前から、今で言います産業振興課と連携をとりながら進めているところです。","voiceIndex":19,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、一部、首を振っていらっしゃった方も何人かいらっしゃったみたいなんですが、あまり長い目でもいけないのかもしれませんが、これから長い目で開発整備も考えながら、よろしくお願いしたいと思います。それから、商店街だけでなく、地域一体となったデータベースづくり、システム体制について、どのようにお考えになっていらっしゃるのか、その２点をお願いいたします。","respondent":"小栗区民生活事業部長","answer":"今後、取り組みの中で、区といたしましては、商店街をはじめ大型店を含めました地元商業関係者の、地域の魅力づくりに向ける意識に関心を高めていただくような努力をしてまいりたいと考えているところです。","voiceIndex":21,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは、前に私がお聞きしたときは、東京都内は使えないとお聞きしていたんですが、現在、近隣の区では実施されているということもお聞きしております。品川区として、市街地活性化事業自体を考えていくことはできるのでしょうか。それまでの間に、商店街の点とか線でなく、広域的な広がりを結びつけるための検討をどういうふうに考えていらっしゃるのか、その点について、お答えをお願いいたします。","respondent":"小栗区民生活事業部長","answer":"具体的な仕組みといたしましては、大井銀座商店街が取り組む情報システムを開発し、既存のイベント事業と組合せながら、大井町の再構築に実践的な取り組みを展開していく方法を検討していきたいと考えているところです。","voiceIndex":23,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"４点目として、ペイオフと制度融資関係について、質問します。今年度末の品川区の基金残高が約５４０億円になると思います。それと、緊急時にどういう対応をなさるのか、その点について、あわせてお答えをお願いしたいと思います。私は出すべきではないと思います。というのは、外郭団体でしたら区自体ではないんですから、第３者にその情報が出てしまう。その２点について、お答えをお願いしたいと思います。","respondent":"相川収入役","answer":"そのほか、何か緊急な事態が出れば、その都度それには対応していくと考えているものです。","voiceIndex":25,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、基本的に出るのは、運用方針を外郭団体に伝えるということでよろしいのでしょうか。運用方針だけが出るということで、よろしいわけですね。","respondent":"相川収入役","answer":"これは、運用方針だけを説明しています。","voiceIndex":27,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川区の制度融資関係について、お聞きしますが、金融機関への預託金は、現在、１３億円ありますが、平成１４年度は、預託金制度を継続なさっていらっしゃいますが、継続したことに対して、利子補給制度などを検討した上での継続なのか。それともう１点は、現状の金融機関における状況から、預託金制度そのものについては、どのような検討をなさっているのか、お答えをお願いしたいと思います。","respondent":"小栗区民生活事業部長","answer":"具体的な検討といたしましては、預託金の廃止、それから、利子補給制度の切り替えといったようなことを検討してまいりました。","voiceIndex":29,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、この辺のところは十分に検討しながら、改正の方向に向かっていただきたいという思いがあります。それと同時に、１３億円の基金を、その時点で取り崩しをすることになると思うんですが、その後には一般財源に持っていくのではなくて、産業の振興ですとか、商店街の振興に使っていっていただきたいと思います。その辺、ちょっとお答えをお願いしたいと思います。","respondent":"小栗区民生活事業部長","answer":"しかし、検討する際には、ご提案のように、金融機関との新たな協調関係を築くというような具体的な方向も視野に入れながら検討させていただきたいと考えています。","voiceIndex":31,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういう意味では、何か新しいものを考えていただきたいのと同時に、これ自体がペイオフ対策の一つ、大変な金額を抱えている区としても管理は大変だと思いますが、この辺のところも十分な対応をお願いしたいの同時に、先ほどの繰り返しになりますが、１３億円の基金を取り崩した際には、区内の産業振興の面に使っていただくことをお願いいたしまして、私の質問を終わらせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"私は、鈴木委員に引き続き、総括質疑を行いたいと思います。私どもの主張と違っております。答弁の時間、猶予を与えないという、これはどこかのチャンネルと同じようなスタイルをとっておりましたけれども、大変不適当であると認識しておりますので、人権問題に関連する人権教育について、改めてどうお考えか質しておきたいと思います。","respondent":"指田教育次長","answer":"こうした観点から、先般の款別審査での上山委員の発言につきましては、私どもといたしましては到底受け入れがたい発言であると認識しています。","voiceIndex":35,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"都区制度改革に関連してお伺いいたします。平成１２年に都区制度が改革されまして、なかんずく、清掃事業が地域、自治体に移ってきまして、はや２年経っております。いよいよご退任ですけれども、この間の都から区に移ってきたこの事業のあり方、どこをどう苦労されて、今後、４年後の見直しにどういう準備をすべきであるかということに関して、ご見解を伺いたいと思います。","respondent":"野本環境清掃事業部長","answer":"前回の款別の審査の中でちょっとお答えさせていただきましたように、清掃事業をどう運営するかの基本は、輸送事業という格好で対応するのか、あるいは、ほんとうに清掃事業の持つ人員、機材というものが区の隅々まで、ある意味では、１週間に２度。","voiceIndex":37,"id":"exchange-018"},{"speaker":"塚本委員","kind":"質問","question":"１年前にそのことが決まっても構わないわけですから、今がちょうどその仕組みをつくる時期であると思います。ブロック制の問題が出てまいりました。そういう品川区が、２３区がどう仕組みを変えていくかについて提言をできる立場にあると、私は理解しておりますけれども、この件に関してご見解があれば、伺っておきます。","respondent":"野本環境清掃事業部長","answer":"資源循環型基本推進法、あるいは各種リサイクル法等もどんどん整備されてきております。そういう中で考えてみますと、端的に言えば、平成１８年に竣工する大井清掃工場の能力をどう使うのか。","voiceIndex":39,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"私どもは、優秀な官僚がその力を生かして、なかんずく第３セクターに仕事の場を求めて、お互いにいいところを出し合うという体制は、決して悪いことではないと思いますけれども、端的にあらわれたこの事態は、何らかのサインであると理解しております。このことに関して、人を送り出すほうの責任者として、お考えがあれば、ご見解を承りたいと思います。","respondent":"高橋区長","answer":"こういうものを踏まえまして、外郭団体の問題に対しまして、皆さんからいただきましたご提言等を参考にいたしまして、早急に、特に人事に刷新を図ってまいりたいと考えています。","voiceIndex":41,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"品川区では、そのようなお金の流れにもなっておりませんし、第３セクターがそこまで増殖しているとは、私ども、考えておりません。お役人の人事制度として、ある種、よく働いた人、能力のある人が６０歳以降も力を出せる仕組みがあるということは、モチベーションとして大事なことであるという認識も持っております。この件に関して、ご見解があれば、伺いたいと思います。","respondent":"本間総務部長","answer":"ただいま、職員の報酬等の開示というお話がございました。ご案内のとおり、現在、地方公務員法は、人事委員会で決めました給与につきまして、予算特別委員会等々でもそれぞれの等級の号給等を公表しておりますし、区民の皆様にも、年に１回、職員の給与等を公表しています。","voiceIndex":43,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"年俸制にしろと言っているのではないんです。年俸として明示をせよと。モデルをつくって、何号、何等なんて言ったってわからない人が多いわけですから、私もよくわかりません。そのことを言っているわけですから、もう一度、お答え願いたいと思います。","respondent":"本間総務部長","answer":"その点につきまして、年に１回、広報「しながわ」で、我々職員の平均的なモデルを取りまして、それぞれの給与だけではなくて、いただいている手当等、超勤も含めまして、すべて区民の皆様に、現在、公表しています。","voiceIndex":45,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"それがみんなにわかっているかどうかということが問題です。それに関連して、お伺いいたします。埼京線、りんかい線が、今年の１２月に大井町駅をつなぎまして、いよいよ開通ということに相なりました。おいしい井戸水を飲むときは、その井戸を掘った人ことを思い起こせという話がありますけれども、改めまして、ここに至った経過について、どのように認識をされているか伺いたいと思います。","respondent":"中谷まちづくり事業部長","answer":"りんかい線が、本年１２月にいよいよ全線オープンという形になります。","voiceIndex":47,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"そのような力の結集が、１２月初旬の開通ということになるわけです。区は、これにどう臨もうとしているのかということが１点。この通過点、点だけをとらえて、それでおまつりごとが済んだからよしとするのかどうか。そういう人たちの力を合わせて、この結節点で再構築をしていくという考えが必要なのではないかと、私は思っておりますけれども、この２点について、お伺いをいたします。","respondent":"中谷まちづくり事業部長","answer":"今後とも、いろいろな場面で、区としての働きかけをしてまいりたいと考えているところです。","voiceIndex":49,"id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"せっかく大変な機会です、また、１２月までにはまだ時間があります。それぞれの地域が、大井を中心として埋もれ火のように人が残っておると、私は理解しております。そういうものをどうぞ掘り起こして、新しいコンセプトで、人のネットワークをつくっていただきたいと念願しておりますけれども、いかがでございましょうか。","respondent":"高橋区長","answer":"今回の問題につきましても、早速、４月に入りまして、実行委員会等をつくっていただきまして、具体的にどのような事業ができるか検討し、区も一緒になって検討してまいりたいと考えています。","voiceIndex":51,"id":"exchange-025"},{"speaker":"塚本委員","kind":"意見","question":"ぜひ、お力添えを願いたいと思います。大井町が品川区の中心核であるということは、論を待たないわけです。ひるがえって、このまちの道路のアクセスはどうなっているのかということを心配する声が、あちこちで聞こえてまいっております。道路のアクセスに関してどのように考えていられるか、ご見解を承りたいと思います。","respondent":"中谷まちづくり事業部長","answer":"この問題につきましては、区として、かねがね大井町駅周辺の交通アクセスを改良するために検討しておりまして、その一つが補助１６３号線、区役所前の交差点から２０５号線までの拡幅の都市計画道路整備事業を一日も早く行うことによりまして。","voiceIndex":53,"id":"exchange-026"},{"speaker":"塚本委員","kind":"意見","question":"今、示された対応策というのは、当然、とるべきものであると思いますけれども、やはり抜本的にいち早く幹線をつくるということが大事であろうと思います。まちばの人たちは同じ税金を払って、区税か、都税か、国税か、この道はどうだという認識は大してございませんよ。何で家の前がこうなっていて、こんな渋滞が起きているのか、税金はどう使われているのかという疑問ばかりですよ。","respondent":"中谷まちづくり事業部長","answer":"区では、こういうふうにまず自分でできることを進める中で、法的な問題、あるいは財源的な問題、東京都の協力なしにはできない問題、こういう問題については東京都と連携し、より一層必要なものについては要請していく中で、区民の皆さんの道路整備。","voiceIndex":55,"id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"私は、品川区のお役人、官僚は大変優秀だと考えていますし、方々で、そう吹聴しております。しかしながら、お役人の第一の特徴というのは、与えられた条件でもって最適の解答を求める、そういうことは得意であるけれども、本来のあるべき姿を見据えて、ここをこう変えればどうなるんだ、よくなるんだ、そのことに向かって努力をしようという意識が欠けている点があると思います。","respondent":"高橋区長","answer":"したがいまして、この問題につきましては、将来、東京都に、２６号線対策として強く要望をしてまいります。と同時に、大井警察に徹底した違法駐車の取り締まりをしていただき、少しでも交通渋滞の緩和を図るような努力をしていただく、これが必要かと考えています。","voiceIndex":57,"id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"根本の議論をネグレクトしてものが進むという事態について、伺いたいと思います。このことが果たして、子どもにとっていいことなんでしょうか。あるいは、子育ては親育て、一緒に親が成長するんだということは、近年、明らかになってきておるわけですから、そういう観点に立ってみれば、根本の議論をしないで、各施策の最適の解答を求めていく今の状況について、私は、大変な危惧を持っている。","respondent":"小沼福祉事業部長","answer":"ですから、必ずしもすべてにおいて国の、あるいは都のというところで迎合しているとは、私どもとしては考えてございません。","voiceIndex":59,"id":"exchange-029"},{"speaker":"塚本委員","kind":"意見","question":"私も、その認識から出発してほしいと考えています。なかんずく、０歳から３歳までは、どれほど親の愛情を受けても、受け足りないということはないという時代であろうかと考えています。もちろん、父親もそのときどきにおいて責任を果たすべきです。忸怩たるものがありますけれども。どうぞ、根本的な論議を始めようではありませんか。ご静聴、ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-030"},{"speaker":"中島委員","kind":"質問","question":"私は、公明党を代表いたしまして、総括質疑を行います。しかし、今の社会状況の中では難しい面もあります。そこで、仮称家庭あんしんセンターの事業内容についてお伺いしたいと思います。はじめに、地域で子育てを支え合うファミリーサポートセンター、またトワイライトステイを利用する場合の申込み方法や、事業などの利用者の負担はどのぐらいを想定されているのでしょうか、お伺いいたします。","respondent":"小沼福祉事業部長","answer":"ファミリーサポートセンター関係での利用者の負担を中心としての問題ですが、現在、私どもとしましては、ご利用の会員の方につきましては、時間で８００円程度の料金ということで、援助会員と賛助会員間でのやり取りということを基本に考えてあります。","voiceIndex":66,"id":"exchange-031"},{"speaker":"中島委員","kind":"質問","question":"今、手続のことはおっしゃっていただきましたでしょうか。","respondent":"小沼福祉事業部長","answer":"利用する会員の方と、それを支える方、このお二方がおりまして、基本的には、その間でのいわゆる契約ですので、当然のことですけど、申込み用紙であるとか、どういう時間帯で、どういう人を好むとか、その間での情報サービスの提供であるとか、あるいは。","voiceIndex":68,"id":"exchange-032"},{"speaker":"中島委員","kind":"質問・要望","question":"これは、電話でも申込みができるのでしょうか。続いて、次の質問に移りますので、後でお答えいただきたいと思います。せっかくできたいい事業ですので、手続はできるだけ簡素化をしていただきたいという要望もあって、今、質問させていただきました。その際の利用負担というのは、毎日だと非常に高くなると思いますので、どのように支援をしていくのか、この点についてお答えいただきたいと思います。","respondent":"小沼福祉事業部長","answer":"負担の問題ですけれども、先ほど、申し上げましたけれども、私どもとしましては、今の段階では、時間８００円程度というようなことで考えてあります。","voiceIndex":70,"id":"exchange-033"},{"speaker":"中島委員","kind":"質問・要望","question":"続きまして、出産後の子育て支援としてのヘルパーの派遣について、お伺いいたします。そこで、このファミリーサポートセンターの事務局をこの４月から立ち上げると伺っておりますが、産後のヤングママや、新生児の育児支援の観点から、ぜひ、実現していただきたいと願っております。この点について、どのような運びとなっているでしょうか。","respondent":"小沼福祉事業部長","answer":"いわゆる産褥ヘルパーの問題ですけれども、これにつきましては、ファミリーサポートセンターでの子育ての支援事業の一つとして、今、いろいろな点で事務的な問題、それから保健所等との連携の問題を含めて、プロジェクトチームをつくってありますので、その中で、逐次。","voiceIndex":72,"id":"exchange-034"},{"speaker":"中島委員","kind":"質問・要望","question":"ぜひ、前向きに展開をしていただきたいと要望をしておきます。次に、このセンターには、児童虐待防止連絡協議会を設置されるとありました。児童虐待に関するネットワークの構築で、早期発見、迅速な対応に努めるとありますが、この協議会の構成メンバー、開催回数、検討する具体的な内容などをお知らせください。","respondent":"小沼福祉事業部長","answer":"検討の内容といいますか、こちらで考えてあります点は、一つには、当然のことですが、いわゆる虐待についての関係機関との相互の意見交換、あるいは情報交換など、いわゆる情報の共有に関することが１点あります。","voiceIndex":74,"id":"exchange-035"},{"speaker":"中島委員","kind":"質問","question":"ただいま、児童相談所とも連携をとるというお話がありましたが、例えば、子どもの保護のために親から離し保護することも考えられると思うんです。そうしたときに、児童相談所がうまく機能してくれないという苦情が寄せられております。この点に対しては、どのようにお考えでしょうか。","respondent":"小沼福祉事業部長","answer":"今までのような、ちょっと時間がかかったとか、あるいは、ちょっと見当違いであるというようなことがないような形でのやり取りをして進めていきたいと考えています。","voiceIndex":76,"id":"exchange-036"},{"speaker":"中島委員","kind":"質問・要望","question":"ほんとうに子どもの安全のために、ぜひ、強力に進めていただきたいと要望しておきたいと思います。昨年、我が党では、児童遊園を含む区内２１６カ所の公園の総点検を行いました。その際、区民の方から、「害虫駆除はどうなっているんですか」という声がたくさんありました。昨年、我が党の嶋議員からも、この点に関しまして一般質問をいたしました。早期発見の方法、ＰＲの方法についてお聞かせください。","respondent":"中谷まちづくり事業部長","answer":"ＰＲについてですが、現在、ホームページ、あるいは、「しながわガイド」等でＰＲを行っておりますが、今後、こういうものにつきましても、さらに充実に努めてまいりたいと考えているところです。","voiceIndex":78,"id":"exchange-037"},{"speaker":"中島委員","kind":"質問","question":"ネズミの問題なんです。款別審査の中でも出ておりましたが、私も、建て替えの工事が行われる前に、駆除を義務づけてほしいという声をいただいております。建築課では、先日、解体業者に、事前の駆除をするように指導されていると伺いました。その後に、駆除をしたという報告を受けるなど、チェックはされているのでしょうか。","respondent":"山室住宅指導担当部長","answer":"ネズミ駆除の問題ですが、窓口での解体の指導はしておりますが、確認というのは特段しておりません。","voiceIndex":80,"id":"exchange-038"},{"speaker":"中島委員","kind":"質問","question":"この点は、ぜひ強化してほしいと思います。ちょっとした連絡ですので、ぜひ、お願いしたいと思います。工事がなくても、ネズミの被害というのは増えていると思います。大阪府では、総合ネズミ駆除運動を、期間を決めて大阪府全体で行っております。品川区のホームページにもネズミ対策が載せられておりますが、ほかにどのような対策を考えて、実施されているのでしょうか。よろしくお願いします。","respondent":"新美保健高齢事業部長","answer":"ネズミ対策についてのご質問ですが、現在、品川区で行っておりますものは、当然、ＰＲをしていることのほかに、町会に殺鼠剤を配付し、地域でネズミ駆除の取り組みをしていただくということを、年１回やっております。","voiceIndex":82,"id":"exchange-039"},{"speaker":"中島委員","kind":"質問","question":"しかしながら、被害は大きいと思いますので、あわせて、もう少し強化をお願いしたいと思います。続きまして、大井町駅周辺の整備および駐輪対策について、お伺いいたします。りんかい線の開通に伴い、大井町駅付近でも大きな変化が起きております。今年、予算の中に、エレベーター２基と、障害者用のエスカレーターが設置されるとありましたが、障害者用のエスカレーターはどこに設置されるのでしょうか。","respondent":"中谷まちづくり事業部長","answer":"バリアフリー対応のエスカレーターですが、りんかい線のホームから地上までのエレベーターに対応できるような形になっております。","voiceIndex":84,"id":"exchange-040"},{"speaker":"中島委員","kind":"質問","question":"既に設計はできているんでしょうが、あくまでも利用者の視点に立って、再度、細かいチェックをお願いしたいと思います。次に、西口の大井町阪急デパートの前に植え込みがあります。この手前にプランターが置かれているんですが、あれは何のために置かれているんでしょうか。","respondent":"中谷まちづくり事業部長","answer":"ここの歩道の整備を行った際に、植え込みとともにプランターを設置しまして、放置駐輪を排除するということで行ってきた経緯があります。","voiceIndex":86,"id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"実は、そのプランターの分だけ狭くなっております。私は、平成１２年の第４回定例会でもこのことを申しました。そのときに、「路上の駐輪は」と言われたんですが、じゃあ、自転車はだめでも、プランターはいいのでしょうかと逆に質問をしたと思います。そういった意味で、大井の陸橋化だけでは足りませんので、今後の課題だと思いますが、どのような計画をなさっているかお知らせください。","respondent":"中谷まちづくり事業部長","answer":"委員、ご提案の阪急前の駐輪のラック設置等につきましても、来年度予算では計上してございませんが、りんかい線のオープン後の人の動向、自転車の動向を見ながら検討していかなくちゃならない課題だと考えております。","voiceIndex":88,"id":"exchange-042"},{"speaker":"中島委員","kind":"質問・要望","question":"ぜひ、よろしくお願いします。続きまして、今、花粉症に悩んでいる方がたくさんいらっしゃると思います。我が党でも、３人に１人が、今、国民病とも言われているアレルギーにかかっていると言われておりますが、この点について、品川区としての対策をいろいろなさっていると思います。きょうは、ケーブルテレビも入っておりますので、ＰＲも兼ねて、アレルギー対策についてお答えいただきたいと思います。","respondent":"青山品川区保健センター所長","answer":"さまざまな形でのご相談がありましたときには、その都度、専門の職員が対応いたしますとともに、広報やパンフレット、それからホームページ、さらに、ご要望に応じまして講演会や座談会等の中でも、お話し申し上げているところです。","voiceIndex":90,"id":"exchange-043"},{"speaker":"中島委員","kind":"質問","question":"時間がないので、飛ばしていきます。今、高齢化社会と言われて、高齢化の問題はますますこれから進化していくと思います。そういった意味で、品川区の第２次いきいき計画というのがありますが、これは高齢化社会に向けた施策が打ち出されておりますが、ここにシニアの目線をどのように入れているのでしょうか、お伺いいたします。","respondent":"新美保健高齢事業部長","answer":"第２に、健康づくりプラン２１ということで、健康づくりに力を入れる。それから、第７のプロジェクトで、人にやさしいまちづくりということで、高齢者、障害者の視点でまちづくりを進めるなど、そういう意味で、かなりシニアの視点を入れたつもりです。","voiceIndex":92,"id":"exchange-044"},{"speaker":"中島委員","kind":"提案","question":"これから、まちの形を変えるハード対策、まちづくりの仕組みを変えるソフト対策、そして、まちの人の意識を変えるハート対策、こうした三位一体によるまちづくりを、ぜひよろしくお願いしたいと思います。このとき、都の福祉局長は、「区市町村でこれを受けてくれるところは、しっかり応援したい」という答弁をなさっておりますが、この点について、区としてはどのようにお考えでしょうか。","respondent":"新美保健高齢事業部長","answer":"品川区といたしましては、先ほども出ました第２次いきいき計画２１の中で、重点プロジェクトに、自立支援ネットワークの充実というプロジェクトを掲げております。","voiceIndex":94,"id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"大変すばらしい計画を立てておられるんですが、現在、福祉サービスというのは、利用者が役所などの窓口に来て、初めてそこから事が起こると思うんです。この前の西東京市のご夫婦にしても、地域と断絶していたわけではなくて、むしろ、地域の方と親しくしていた。しかしながら、これがわからなかったということなんです。この辺について、どのようにお考えでしょうか。","respondent":"新美保健高齢事業部長","answer":"確かに、地域のお一人ひとりすべてということは難しいかと思いますが、品川区におきましても、高齢者のさまざまなサービス、あるいはお申し出については、介護の場合は支援センターという形で、お電話一本、あるいは民生委員の通報等で対応できる仕組みになっております。","voiceIndex":96,"id":"exchange-046"},{"speaker":"中島委員","kind":"質問・要望","question":"先ほども申しましたが、高齢化社会２０２５年には３人に１人が高齢者、３世帯に１世帯が６５歳以上の高齢者世帯となると言われております。そういった意味からも、やはりもう少し細かい視点に立った計画が必要だと思います。ですから、ぜひ、この際、シニアの目線に立った総合的なまちづくりというものを、しっかりこれから計画を立てていただきたいと要望いたしまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-047"},{"speaker":"鶴委員","kind":"質問・要望","question":"全体の奉仕者としての職員の職責、信用の保持などについて。今回の一連のアルゼンチン国債購入をめぐって、うそをついている、でたらめなことをやっている、全体が狂っているとの批判が当たるのか、当たらないのかを含め、文化振興事業団のアルゼンチン国債をはじめ、外債購入の事実経過、財産運営上の問題点、今後の是正課題など、調査結果に基づいて、区民の皆さんにわかりやすい説明をまず求めます。","respondent":"中尾根企画部長","answer":"アルゼンチン国債購入に関しての何点かのご質問ですけれども、改めて、区民にわかりやすくです。１点目の、外国債購入の事実の経過ですけれども、文化振興事業団では、昭和６１年設立以来、国の公益法人会計基準に基づきましてさまざまな運用をしてまいりました。","voiceIndex":100,"id":"exchange-048"},{"speaker":"鶴委員","kind":"質問・要望","question":"言葉を極めた不適切な批判であることがよくわかり、不穏当な発言や確証のない発言は軽々にすべきではないと、自覚を新たにいたしました。監督責任を求められている理事長も、その職を辞職し、適任と思われる民間人を選任するなど、新しい体制のもとで、事業団への信頼回復に努めるべきであると進言をいたします。区長の潔いご決断を期待し、改めて、ご所見を伺っておきたいと思います。","respondent":"高橋区長","answer":"当然ですが、文化振興事業団、国際友好協会、それから、共済会の理事長、この三つの理事会を開きまして、今回のアルゼンチン国債の問題だけではなく、区長と理事長を併任していることがいいか、悪いという反省の立場に立ちまして、これから区長に専念するために。","voiceIndex":102,"id":"exchange-049"},{"speaker":"鶴委員","kind":"質問・要望","question":"区長のご答弁を聞いて、やはり役職をスリム化することも大事かなと思いました。次に、全体の奉仕者としての職員の職責、信用の保持などに関連してお尋ねいたします。品川区職員服務規程第２条および第３条はどういうふうになっているか。さらに、品川区職員氏名札着用規則第１条および第３条の規程、ならびに現在の氏名札の定められた様式がどうなっているかも、ご説明いただきたいと思います。","respondent":"本間総務部長","answer":"１点目の品川区職員服務規程ですが、第２条は、服務の原則として、「職員は全体の奉仕者としての職責を自覚し、法令、条例、規則および訓令ならびに上司の職務上の命令に従い、誠実、公正、かつ能率的に職務を遂行しなければならない」とし、第３条は信用の保持として、第１項は。","voiceIndex":104,"id":"exchange-050"},{"speaker":"鶴委員","kind":"提案","question":"納税者は、職員の働きぶり、窓口の対応ぶり、貴賤の度合いを含めじっと見ています。職員の方々も、何かとご苦労の多いことと思います。昨年３月の予算特別委員会で、私は、ノーネクタイの導入を強く求めましたが、その立場から、その省エネ効果に注目しております。今後、検討していく中で考えていきたい」と、人事課長は答弁されています。検討状況をお聞かせ願いたいと思います。","respondent":"本間総務部長","answer":"このようなことから、今後、サマールックキャンペーンの実施の状況等も加味しながら、引き続いて検討していきたいと考えているところです。","voiceIndex":106,"id":"exchange-051"},{"speaker":"鶴委員","kind":"質問・要望","question":"住民サービス向上の観点から、新たなスタイルの氏名札の着用を強く求めておきたいと思います。今生活保護をかけてもらえなければ、ホームレスになるしかありません」と言ったところ、「どうぞ、ホームレスになればいいじゃないですか」と言われたんですと。先日の事例ということですから、担当職員に事実関係を確認されていることと思いますので、事実を明らかにしていただきたいと思います。","respondent":"小沼福祉事業部長","answer":"私のほうも、事実とすれば大変由々しき問題ですから、即刻調べました。結論から申し上げますと、私ども職員のほうから、「ホームレスになればいいじゃないか」と言ったことはございません。","voiceIndex":108,"id":"exchange-052"},{"speaker":"鶴委員","kind":"質問・要望","question":"次に確認したいことは、路上生活者を対象にした支援センターの入所者に対する食事券の処遇についてであります。そこで売っているズボンは、まちで買えば２,０００円ぐらいのものが６,０００円もする」と紹介し、改善を求められました。後刻、私は理事者に調査、確認をお願いしました。台東寮および大田寮の３月１３日の朝食、昼食、夕食別にメニューやカロリーなど詳細に報告をいただきたい。","respondent":"小沼福祉事業部長","answer":"こういうことを、文書でいただいてあります。","voiceIndex":110,"id":"exchange-053"},{"speaker":"鶴委員","kind":"質問・要望","question":"〔「場所が違う」と呼ぶ者あり〕 違うんだったら、その委員会のときに言えばよかったじゃないですか。しかし、風聞をうのみにし、事実確認を怠り、公の場で披瀝することが誤解の種をまくばかりではなく、関係者の名誉を棄損したり、人権を侵害することもあります。次に、公共施設におけるオストメイト対応トイレの設置についてですが、まず、説明していただきたいと思います。","respondent":"本間総務部長","answer":"オストメイトについてのご説明ですが、大腸ですとか、小腸、それから直腸、膀胱等の悪性腫瘍疾患のために、延命手段として、外科的に疾患部の全部または一部の切除手術を受けて、腹部に排泄のためのストーマー、つまり排泄口を設けた方を言います。","voiceIndex":112,"id":"exchange-054"},{"speaker":"鶴委員","kind":"質問・要望","question":"近年の直腸がん、膀胱がんの増加傾向を反映して、人口１,０００人当たりに占めるオストメイトの比率はここ数年倍増していて、現在、全国で約２０万人以上いると言われています。品川区でも、約２３０人の方が社会復帰をし頑張っていらっしゃいます。品川区にも１カ所もありませんが、品川区内の公共施設をはじめとして、対応策を求めておきたいと思いますが、いかがでしょうか。","respondent":"本間総務部長","answer":"こういう状況の中で、本格的なオストメイト対応のトイレの設置には一定のスペースが必要であるとか、維持管理等々の課題もあることから、既存の施設に設置することは非常に難しい面もありますが、当面、庁舎のだれでもトイレの中に、簡易な手法です。","voiceIndex":114,"id":"exchange-055"},{"speaker":"鶴委員","kind":"提案","question":"ぜひ、前向きな取り組みをお願いしたいと思います。ところで、新年度予算案に、大井町の公衆便所の改修工事２,５８０万円が計上されていますが、この公衆トイレが、オストメイト対応トイレの品川区における第一歩だと言われるような工事をやっていただきたいということを提案します。ご答弁を求めます。","respondent":"中谷まちづくり事業部長","answer":"ここでも、だれでもトイレを設置する予定ですので、先ほど総務部長から話がございましたが、オストメイトの簡易型のものについて、設置する方向で検討してまいりたいと考えております。","voiceIndex":116,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"上山委員の質問は、人権教育を同和問題に等質させるあり方はやめるべきだと述べたものです。我が党は、人権教育は大事であり、男女差別、障害者差別、思想差別をなくすことは、憲法が求めている課題だと考えます。私からは、介護が必要な高齢者の所得税、住民税の障害者控除についてと、特別養護老人ホームの増設、この２点について質問いたします。品川区のこの３年間の認定実績について、お聞かせください。","respondent":"新美保健高齢事業部長","answer":"控除額ですが、一般控除が、所得税で２７万円、特別障害が４０万円です。品川区における、これまでの認定の実績ですが、従来、ねたきり手当等の対象で行っておりましたが、介護保険後も認定をしておりまして、平成１２年が４件、１３年が６件、１４年に入りまして３件です。","voiceIndex":120,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の部長のお答えですと、ねたきり老人だけということですけれども、昭和４５年、１９７０年の拡大の所得税法施行令第１０条第１項の７号についての拡大された中身についてお聞きしましたので、そのことについてのお答えをお願いします。","respondent":"新美保健高齢事業部長","answer":"先ほど申し上げました社会局長通知そのものは、障害者控除の拡大という通知ですけれども、ねたきり老人につきましての取り扱いは、昭和４５年通知以降、基本的に変わっていないものです。","voiceIndex":122,"id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、申請があれば認定証が発行できる。それと、申請があれば、認定証が発行できるという方は、どういう判定基準で行うのか。判定表があると思うんです。例えば障害者控除を受けられる３から６級に準ずるもの、これがどの程度のものなのか、具体的にお示しいただきたいと思います。呼吸器障害、そして下肢不自由の方、この場合について、お答えいただきたいと思います。","respondent":"新美保健高齢事業部長","answer":"ねたきり老人というのは、高齢における障害で、それにあわせた形での判定ということになりまして、昭和４５年以降、かなり長期間において、高齢者福祉手当制度等がございましたので、そういう制度の中での心身状況の判定をもとに、認定証を出してきたものです。","voiceIndex":124,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区のほうから判定表をいただきました。下肢の部分で言えば、「片下肢障害のため、１ｍ以上歩けない」等さまざまあるわけですけれども、こういう方も３から６級に準ずるという判定書になっていると思うんです。こういうことで言えば、認定を受けている方のかなりの部分が認定証の発行が可能かと思うんですが、その点については、いかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"ねたきり老人の障害者控除の判定は、６カ月以上の臥床状況、さらに、常時、排泄、あるいは食事といったところでの介助が必要というのが基本的な認定基準で、従来から認定をしているものです。","voiceIndex":126,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この点については、もう１回、１９７０年当時のそれを調べていただきたいと思います。今、申し上げたようなものがすべて、「身体障害者に準ずる者」という形で障害者控除の対象になるという方向がきちんと出されているわけですから、この点については、ぜひ、もう１回、調査をしていただきたいと思います。そして、あわせて、この問題について、ぜひ、区民のほうに周知、徹底をしていただきたいと思います。","respondent":"新美保健高齢事業部長","answer":"ただいま、ご答弁申し上げましたのは、従来、または現在の対応についてお答えをしたものです。それから、特にこの件について新たな通知は来ておりません。しかしながら、いろいろとご質問等もありますので、引き続き調査はしていきたいと考えております。","voiceIndex":128,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"時間がなくなりましたので、次の質問に移らせていただきたいと思います。特別養護老人ホームの増設についての質問をします。はじめに、特別養護老人ホームの入所希望者の推移について、平成１３年２月末、９月末、そして、今年の２月末で締め切った申請数を教えてください。それを払えるだけの高齢者は、品川区の中にどれぐらいいると考えているかについて、お聞かせください。","respondent":"新美保健高齢事業部長","answer":"この３月に行います、２月末締め切りの部分が５２２人です。西五反田ケアホームにつきまして、これまでもご説明しましたとおりケアハウス制度に特定施設を組合せ、上乗せ負担をいただいて、個室でユニットケアをする施設です。","voiceIndex":130,"id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"半年間に入れる人数は９０人ということですけれども、今回で言えば５２２人、残りの４３２人に対して、区はどのように考えているんでしょうか。入れなかった人の７割は、また次回にも申し込むと聞いていますけれども、そうすると、どんどん積み上がっていくと思うんです。","respondent":"新美保健高齢事業部長","answer":"入所を希望される方が、少しずつ増加していることは確かです。高齢者人口の伸びということもありますので、そういう傾向が続くことは、当然考えておかなければならないと考えています。","voiceIndex":134,"id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回で言えば、半年間で入れない残りの４３２人に対して、どう考えているのかということについてお聞かせください。","respondent":"新美保健高齢事業部長","answer":"当然、それぞれの方は、ご自宅か、老人保健施設か、病院でお待ちになっていらっしゃるわけでございまして、在宅の方には、入れるまでの間の在宅サービスをより使っていただくようなケアマネージメントに努めますし、老人保健施設につきましては。","voiceIndex":136,"id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"老人保健施設に入所されている方は、３カ月ごとに、次の老人保健施設の移転先を探さなければいけない。要介護度４とか５の方は、毎回、３カ月ごとに寝台車で移転をしなくちゃいけないわけですよね。こういう方に、区として、どういうふうに心を寄せていくのかというのが問われているんじゃないかなと思うんです。そういうところで、ぜひ、特別養護老人ホームを建設していただきたいというのが要望です。","respondent":"新美保健高齢事業部長","answer":"区としましては、もちろん個室で、ユニットケア等のケアの手法もいろいろ工夫をして、暮らしの形に近いケアをしていくべきだという考え方で、これまでも取り組んでまいりまして、西五反田では、それを具体化する一つとして、ケアハウス制度を使って特定施設。","voiceIndex":138,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今度の新型特別養護老人ホームも視野に入れて、ぜひ、検討をしていただきたいと思うんですが、いかがでしょうか。そういうところでは、ぜひ、この新型特別養護老人ホームも含めて、そして介護を受けている本人や家族、住民のニーズを調査しながら、どういう特別養護老人ホームにしていくのか検討しながら、特別養護老人ホームの建設をしていただきたいと思うんですが、いかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"そういった点が特に大都市東京、品川区におけるスタッフの確保という面から、きちんと考え、検討していく必要があるというのが大きな点かと考えております。","voiceIndex":140,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都南病院の跡地は、品川区でも老人保健施設が１施設しかありませんので、待ち望まれていたところなのに、ほんとうに残念だなと思うんです。今、品川区で、老人保健施設の利用者が３７０人ですよね。この都南総合病院の跡地を、ぜひ区が取得して、特別養護老人ホームと老人保健施設の建設をしていただきたいと思うんですけれども、いかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"今のご質問のようなことについては、考えてございません。","voiceIndex":142,"id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この点については、ぜひ、前向きにご検討いただきたいと思います。やっぱり多くの区民が求めているのは、どの階層でも、だれでも入れる特別養護老人ホームだと思います。これだけ増え続けているのに、みんなが入れる特別養護老人ホームをなぜつくらないんでしょうか。改めて、区民の切実な願いである、すべての階層が入れる特別養護老人ホームと、老人保健施設の建設を強く要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-068"},{"speaker":"菊地委員","kind":"質問","question":"日本共産党区議団を代表いたしまして、残りの時間、質疑をします。先ほど、４月中に理事長を辞任をするという意向をお話してくださいましたけれども、理由として、区長との兼任で、理事長の任を果たせなかったということをおっしゃっておりますけれども、これは、区民に対する謝罪であると、このように受けとめてよろしいんでしょうか。それともう１点、お聞きしたいんです。","respondent":"高橋区長、中尾根企画部長","answer":"本会議のときにも申し上げましたけれども、品川文化振興事業団の運営に対しまして、大変申しわけなく思っておりまして、おわびを申し上げましたところです。この間の購入の経過についての、そういう発言の問題ですけれども、区長のほうは、この予算特別委員会でも発言しましたのは、ご自分の経験等から、資金運用の方法や考え方についての感想を述べられた、こういうことです。","voiceIndex":146,"id":"exchange-069"},{"speaker":"菊地委員","kind":"質問","question":"感想を述べられたということですので、ちょっともとのところからお聞きしてまいります。先ほど、この間の経過について述べておられましたけれども、３億１,０００万円の外国債を事業団が購入した経過について、改めてお聞きしたい。それから、調査会の問題ですけれども、これは理事長、それから、副理事長にどのような調査を行って、どのような返答を得たのか、この点についてお聞かせを願いたいと思います。","respondent":"中尾根企画部長","answer":"今回の調査は、全体としまして、外国債券の購入の経過、手続の事実をはっきりさせるということと、事業団に対する区からの補助金等がどうなっているのかを解明すること、そして、三つ目には、調査した結果として、どういうことが問題点としてあるのか。","voiceIndex":149,"id":"exchange-070"},{"speaker":"菊地委員","kind":"質問","question":"私がお聞きしたのは、現在の理事長、それから副理事長にどのような調査を行ったのか、どのような返答を得たのか、このことをお聞きしました。","respondent":"中尾根企画部長","answer":"理事長につきましては、助役のほうから、調査のある一つの経過のまとまりができまして、それを逐次報告する中で、理事長としての立場としては、どうだったのかという確認行為をしています。","voiceIndex":151,"id":"exchange-071"},{"speaker":"菊地委員","kind":"質問","question":"そのときの立場の部分って、全然具体的じゃないのでわからないんです。それじゃあ、調査会の報告、まとめで、アルゼンチン国債を買ったこと自体は問題がない、手続に違反があったことが問題なんだと言っていますけれども、区長は、報告書、まとめについて、実際は満足をされておられるんでしょうか。この辺の見解を、ちょっとお聞かせを願えますか。","respondent":"高橋区長","answer":"たびたび私の問題が出てまいりますけれども、私は、理事長として、事実を知ったことについて、率直に現副理事長にお話をいたしました。それが一つの事情聴取かなと考えています。","voiceIndex":153,"id":"exchange-072"},{"speaker":"菊地委員","kind":"質問・要望","question":"満足をされておられるということですけれども、区長は、集中審査の際に、アルゼンチン国債の危険性は知っていると、「私は絶対に外国債には手を出さない」と言っていますよね。しかし、事業団そのものは、外国債を買うことはいいんだと、不当でも違反でもないと、このように述べておられます。個人的には、危険なものだと承知をしているということですよね。この辺を明確にしていただきたいと思います。","respondent":"高橋区長","answer":"ただ、現在のこういう情勢の中で、私だったら買いませんでしたと、そういうふうに申し上げているわけでして、過去と、現在と、将来とをよくひとつご理解をしていただきませんと、ごっちゃにしますと、この問題はまた何か霧の中に入ってしまいますので、よろしくお願いいたします。","voiceIndex":155,"id":"exchange-073"},{"speaker":"菊地委員","kind":"質問","question":"区長、もう一度お聞きしますけれども、私は、ＢＢ債、同じことなんですか、区長。外国債を買うことはいいんだと、それじゃＢＢ債はどうなんですか。ここのところに区長は問題意識を持たれたんじゃないでしょうか。","respondent":"高橋区長","answer":"先ほどから申し上げておりますように、それぞれの財団の基本財産の運営は、安全、かつ有利に活用することが必要です。安全が前提です。安全性のないものには手を出さない、これが、本来の運営の仕方じゃないかと考えています。","voiceIndex":157,"id":"exchange-074"},{"speaker":"菊地委員","kind":"質問","question":"区長は集中審査の際に、「元助役は株をやったことがあるのか。やっていたら、外国債にはほんとど手を出さないものだと、これが今回の大きな間違いの一つだと思っている」と、このように答弁をされたわけですよね。区長の見解と調査会の見解というのは明らかに違うと思うんですよ。これは、決して言葉尻の問題ではなく、調査会そのものの問題ではないでしょうか。ちょっとお聞きします。","respondent":"高橋区長","answer":"経済について、あなたは強いと言われているんだけれども、どうしてなんだ」と言ったら、「いや、私はそういう株の問題については、あまりよく存じておりませんでした」という返事が返ってまいりました。ですから、財政通が即株について精通しているとは言いきれません。","voiceIndex":159,"id":"exchange-075"},{"speaker":"菊地委員","kind":"確認","question":"ただ、今回の事件というのは、確認書にあるとおり、最初から元本割れを起こすリスクが説明をされていたわけですよね。この間、理事長も財務については、なかなか確認ができなかったということですけれども、これはほんとうに、この間、集中審査や総務委員会でも行われましたけれども、信じがたいような組織形態を持っていると思います。","respondent":"中尾根企画部長","answer":"利払いの件ですけれども、１２月９日に購入しました６,０００万円のほうのアルゼンチン国債についての利払いが３月２６日に、一応、予定をされてありますが、事業団が、３月１５日、改めて証券会社および幹事会社の東京三菱銀行に確認しましたところ。","voiceIndex":161,"id":"exchange-076"},{"speaker":"菊地委員","kind":"質問・要望","question":"毎年、四、五億円の補助金や委託金が注ぎ込まれているわけですよね。実際に、いろいろな小さな事業なんかについては、果実で運営をしていくんだというようなことですけれども、実質的に３億１,０００万円の原資というのが区民の財産であることは明らかですから、いろいろな形で、区のほうも調査をしてきたんだと思います。この辺に責任を持つのかどうか、ちょっとお聞きしたいと思います。","respondent":"高橋区長","answer":"それが違法の方法であるならば、幾らでも負債の責任は取りますけれども、合法的な方法で買った、ただ、買う手続が適当でなかった、ただ、それだけの問題ですので、私は、この問題に対しまして、私の財産を投入して負債を埋めるという考え方は、今、持っておりません。","voiceIndex":163,"id":"exchange-077"},{"speaker":"菊地委員","kind":"質問","question":"おやめになるということですけれども、財団の理事長は区長、副理事長は助役と教育長、それから、監査が収入役、こういう役員布陣を持っているわけですね。これは区民の目から見れば、同じ品川区の事業なんですよ。確かに、第３セクターとしてつくり上げていますよ。だからこそ、いろいろな問題が、区民の間からいろいろな声が起きてているんじゃないですか。ちょっとその点、お聞かせください。","respondent":"高橋区長","answer":"それをひとつ、忘れないでいていただきたい。それから、今、副理事長の問題、または、監事の問題の責任云々ということがございましたが、私は、その全責任を取って、監督責任を取ってやめるということを、何回も言明をしているわけですから、これ以上聞かないでください。","voiceIndex":165,"id":"exchange-078"},{"speaker":"菊地委員","kind":"質問・要望","question":"具体的に、この辺は、具体的にありましたら示していただきたいと思います。就任当初は、確かに、知り得ないかもしれませんけれども、アルゼンチン国債を購入したのは、その１カ月ほど後でしょうか。この時点で、理事会にかけられていないことは知り得たはずなんです。実際に、理事長に対して確認をとるという作業をなぜしなかったのかというところを、お教えいただきたいと思います。","respondent":"中尾根企画部長","answer":"比較されていたＡＡというものについては、これはアメリカですけれども、１.幾つというようなことでした。したがいまして、そういう格付けなり、利率なり等をいろいろ検討したという経過の中で、やはり利率の高いものを選んでいったと受けとめてあります。","voiceIndex":167,"id":"exchange-079"},{"speaker":"菊地委員","kind":"確認","question":"事務局長についても、お聞きしているんです。なぜ、理事長に確認をとる作業をしなかったのか。","respondent":"中尾根企画部長","answer":"もう一つ確認されているのは、決裁区分についても、決裁はこのままでいいのかとやっぱり疑問を持っておりまして、本来は理事長ではないかということでしたが、「いや、これは、一番最初に自分も事務局長の兼務で決裁しているから、それと同じことでいいのだ」と。","voiceIndex":169,"id":"exchange-080"},{"speaker":"菊地委員","kind":"質問","question":"とすると、その時点で、前副理事長が、処務規程ですとかを無視したんだということになんでしょうか。もう一度。","respondent":"中尾根企画部長","answer":"調査の結果は、そう判断せざるを得ないです。","voiceIndex":171,"id":"exchange-081"},{"speaker":"菊地委員","kind":"質問","question":"副理事長、お聞きしますけれども、事務局長から就任時に報告を受けたということですけれども、これは２０００年の１１月か１２月ということです。区長に報告したのが２００１年５月。そもそも、副理事長の立場で、格付けがＢＢ債だということに疑問を持たなかったのかどうか。それから、理事長に相談をしなかった理由について、もう少し明確に述べていただければと思います。","respondent":"濱野助役","answer":"これも、款別審査、あるいは集中審査の際にご答弁申し上げているところでありますけれども、２０００年の冬だったと思います、今、お話のように、話を聞きました。そしてまた、相前後しまして、証券会社から話を聞いてあります。","voiceIndex":173,"id":"exchange-082"},{"speaker":"菊地委員","kind":"質問","question":"ＢＢ債について、副理事長は疑問を持たなかったのか。これは、区長にもお聞きをした話ですけれども、ちょっとその点をお願いいたします。","respondent":"濱野助役","answer":"もちろんＡＡＡからいろいろなランクがあります。確認書も見ました。確認書には、ＢＢというのは、ＢＢＢに比べれば、元本の確実性が低い、それから、流動性が低いということは書いてありましたし、当然、そういう意味では、大変に優良な債権ではないという認識はございました。","voiceIndex":175,"id":"exchange-083"},{"speaker":"菊地委員","kind":"質問","question":"ＢＢ債でサムライ債ということで、経済用語の解説の中に、サムライ債を発行している外国政府の中には、債務返還の確実性が低くて、格付けが低いところがある。投資の際には、元本が返って来ないというリスクがあるんだというのがあるんですね。ＢＢ債そのものは、どちらにも当てはまらないわけですよね。そのことが目につかなかったということなんでしょうか。もう一度、そこを教えていただければ。","respondent":"濱野助役","answer":"その時点での価格を見ましても、９９.９幾つということでありますから、その時点でどうこうすべきものということは考えられません。その後、若干値を下げた段階で、やはりこれは基本財産として置いておくことついては問題があるという判断をして、理事長に報告をしたものです。","voiceIndex":177,"id":"exchange-084"},{"speaker":"菊地委員","kind":"意見","question":"最後になりましたので、まとめてまいりますけれども、今回の問題で、日曜日に業者の方から私のところに電話があって、不況の中で、おれたち零細業者は商売を青息吐息でやっているんだと。それなのに、こんな形で、この方は税金と言いましたけれども、税金をもてあそぶなんていうのはとんでもないことだという怒りの声を上げていました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":179,"id":"exchange-085"},{"speaker":"船波委員","kind":"質問・要望","question":"これから求める財産運用の細目規程の詳細を教えていただきたいと思います。今後の事業団の資産管理や運用については、そうしたきちんとした専門家のアドバイスを受けるべきだと思いますけれども、そうした点に関しては、どういう予定になっているのか、お伺いしたいと思います。そこで、補助２９号線に関しては、区長はどのようにお考えなのか、そのご見解をお伺いしたいと思います。","respondent":"中谷まちづくり事業部長、新美保健高齢事業部長、小沼福祉事業部長、指田教育次長、中尾根企画部長","answer":"具体的なものとしましては、第三次長期基本計画の施策の中に、都市景観ガイドプランというのを作成することになっておりまして。２点目の暮らしの福祉インフラ整備検討経費についてのご質問にお答えいたします。順序は変わりますけれども、ファミリーサポートのほうからまいりますと、先般の２回の研修で、それぞれ別々に研修をしています。したがいまして、どういう形で放課後を過ごすかは、そのお子さんの一人ひとりの考え、あるいは親御さんの考えという中で、特に現時点において。","voiceIndex":182,"id":"exchange-086"},{"speaker":"船波委員","kind":"質問","question":"品川区は、今までも、長期基本計画をつくるときなど、多少は公募市民の委員が選ばれたりしているわけですけれども、やっぱり人数が少なかったり、平日の昼間開催されるがために、多くの人が参加したいと思っても、そもそもその応募が限られてしまっているような側面もあると思うので、もっと多くの人が参加できるような大胆な手法もとってほしいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-087"},{"speaker":"高星委員","kind":"質問・要望","question":"最初に西五反田三丁目地区のまちづくりについて、お伺いしたいと思います。私は五反田の出身でありますけれども、西五反田三丁目地区は、ご案内のように、区民住宅、それから複合住宅、福祉住宅といったものが建設中でありますけれども、その部分について、ちょっとまず最初にお伺いしたいと思います。こちらが、ＪＲの社宅があるところです。そんなこともあるものですから、ちょっとお聞きしたいと思います。","respondent":"岩野まちづくり事業部次長","answer":"大日本印刷につきましても、次々に住宅が上がってくると、ここでの工場の操業は難しいだろうというような判断をいたしまして、業務経営の用途変更というような形で、現在、社内での検討を開始しているといったように聞いてあります。","voiceIndex":190,"id":"exchange-088"},{"speaker":"高星委員","kind":"質問・要望","question":"私は、かつて、一番最初の段階で、東京都の福祉局がこれに絡む話があったときに、「この部分はどうするんですか、障害を持った方がいっぱい来るんじゃないですか、ここは遊歩道にしなさい」という話したことがあるんですが、どうなっていくのか、考え方をお聞かせいただきたいと思います。先日、見ましたら、東急の目黒駅のそばは約８ｍ。その辺の考え方を、ちょっとお聞かせいただきたいと思っています。","respondent":"岩野まちづくり事業部次長","answer":"それから最後になりますが、五反田駅へのアプローチですが、これも、委員、ご指摘のように、やはり４ｍ５０cmとかの非常に狭い道路が、今、五反田駅へのアクセスですが、中央にある１２ｍの通りに直接道路をぶつけるような形というのは。","voiceIndex":192,"id":"exchange-089"},{"speaker":"高星委員","kind":"提案","question":"自民党の塚本委員からも何度も怒られているんじゃないですか。今の件について、ちょっとご提案もさせてもらいたいんです。それから、この事業そのものがプロポーザル方式という形の中で、周辺のまちづくりときちんと整合したものとしてつくられてきたはずなんですけれども、私が提案したいのは、目黒川左岸ですね。特にこれから先、施設が施設ですから、高齢者が集まることも多いと思います。","respondent":"若月教育長","answer":"プラン２１の進め方ということでありますけれども、これはもう、何度も申し上げております、今まで、学校はこうしなきゃいけない、先生たちはもっとこうしなきゃいけないと、いろいろなことが言われてきました。","voiceIndex":194,"id":"exchange-090"},{"speaker":"高星委員","kind":"質問・要望","question":"拡大解釈というか、いや、私自身も、品川区の教育改革について反対する者ではありません。当初から、不退転の決意でやりなさいということは申し上げているわけです。だから、まだ成熟していないんですよ。もう４分しかありませんので、次にいきます。小中一貫校についてお伺いしたいと思います。なぜ第二日野小学校ということにこだわるのか、お聞かせいただきたい。","respondent":"指田教育次長","answer":"小中一貫校の開設場所の予定としまして、今、第二日野小学校の跡地ということで考えているわけです。ご承知のとおり、あそこの周辺につきましては、今、まちづくりが行われてきております。","voiceIndex":196,"id":"exchange-091"},{"speaker":"高星委員","kind":"質問・要望","question":"お聞きしますと、私も多少調べさせていただいたんですが、開発組合から、土地の一部寄附を受けるんだと。そのほか開発の地区の一部を取得するようだという話です。差し支えない程度に、どのぐらい考えているのか、ちょっとお聞かせいただきたい。特に、これは総合体育館の関係がありますので、よろしくお願いします。","respondent":"岩野まちづくり事業部次長","answer":"総合体育館、それから小中一貫校ですので、その隣は三井不動産が取得している土地がありますので、その土地につきましても、区のほうにご協力いただけるかどうかといったようなことで、今、三井不動産のほうで検討中です。","voiceIndex":198,"id":"exchange-092"},{"speaker":"高星委員","kind":"質問・要望","question":"土地の問題ですから、今のところまだ整理しているという段階だと思います。次に、日野中学校の問題なんです。これは、おわかりのとおりであります。文字どおり、地域ぐるみで子どもを守っているわけですね。このような状況で、日野中学校ＰＴＡから、区当局、教育委員会に要望書が出されたと聞きますが、それは承知していますか、どういうふうに思ったか、ちょっとお聞かせいただきたいと思います。","respondent":"指田教育次長","answer":"これにつきましては、今後、小中一貫校のさまざまな課題につきまして、考え方、あるいは、準備委員会を設けて検討してまいりますけれども、そういった結果などを、適切に学校のほうからＰＴＡ等に伝えて、かつ。","voiceIndex":200,"id":"exchange-093"},{"speaker":"高星委員","kind":"提案","question":"時間がないので、ものすごく飛ばしちゃいますけれども、お願いというか、提案を一つしたいんです。私の案は、日野中学校は第１グラウンド、第２グラウンド、教育センター、五反田文化センター、五反田文化センター別館、それから、第一日野中学校、第一日野幼稚園というふうに教育施設が連続した構造になっているんですね。地域の関係というのは、そういうことを言うんじゃないですか。お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":202,"id":"exchange-094"},{"speaker":"藤原委員","kind":"質問","question":"はじめに、事業部制について、その次に、監査事務局について、区役所職員像について、商店街について、そして最後に、議員と区長についてお伺いします。はじめに、事業部制についてお伺いします。このことについても、お伺いしますし、また、品川区らしい独自性、国や都に依存しない自前の政策立案の力をつけることが大切だと思いますが、いかがでしょうか。","respondent":"中尾根企画部長","answer":"したがいまして、今後につきましては、こういったよい結果を評価していく積極的なプラス思考の組織に育て上げ、それを進めていきたいと考えています。","voiceIndex":204,"id":"exchange-095"},{"speaker":"藤原委員","kind":"質問","question":"部長のご答弁をいただきまして、何かほんとうにいいところづくめですね。ほんとうに期待します。どの政策分野も、いずれをとってもほんとうに重要だと思います。しかし、特に都区制度改革によって新たに区が行うことになった清掃の分野では、とりわけ、区独自の政策能力が問われていると思います。この分野での、第三次長期基本計画のもとで、今後の施策のあり方、基本姿勢や考え方をお伺いしたいです。","respondent":"野本環境清掃事業部長","answer":"今の企画部長の答弁にありましたように、例えばノーレジ袋を一つとってみますと、清掃分野で言えば、省資源、あるいは資源循環型というような啓発と同時に、地域、まちの活性化、商店街の活性化というように、各部門を横断的にリンクをして立ち上げていかないと。","voiceIndex":206,"id":"exchange-096"},{"speaker":"藤原委員","kind":"質問","question":"環境清掃事業部長、ほんとうにどうもありがとうございました。続きまして、監査事務局についてお伺いします。たしか、今、事務局の方が５人だと思いますが、区の規模からして、５人で対応しているのは大丈夫なんでしょうか。それと、たしか３月６日に監査報告が出されたと思いますが、今年の監査の特徴があったら教えていただけますか。","respondent":"南監査委員事務局長","answer":"その能力を高めるために、いろいろ研修や情報収集に努めているわけですが、幸い、私以下４人職員はすべて係長級で、いわゆる主査制をとっておりまして、少数精鋭で対応していると考えています。","voiceIndex":208,"id":"exchange-097"},{"speaker":"藤原委員","kind":"質問・要望","question":"少数精鋭、すばらしいですね。今年、初めてだと思うんですけれども、東京都が、行政評価の手法を使って監査をしたと伺っているんです。これについて、もしわかることがあれば、ご説明していただきたいのと、将来、品川区として導入していく予定はあるんでしょうか。","respondent":"南監査委員事務局長","answer":"こういったものについては、大いに参考にしていきたいと考えていますが、当品川区は、事務事業評価を実施し、今後、政策評価という流れになってありますので、監査としては、屋上屋を重ねるといいますか、同じことをトレースするのではなくて、区の行政監査として。","voiceIndex":210,"id":"exchange-098"},{"speaker":"藤原委員","kind":"質問・要望","question":"続きまして、区役所の職員のあり方について、お伺いさせていただきたいと思います。過去５年間で、退職者数から採用者数を引いた人数、実際に減った職員の数は何人で、これは財源的には、どのような効果があったのでしょうか。今後、１０年間の職員数の変化と、職員減に見合った事業執行をどのように考えているのか教えてください。","respondent":"本間総務部長","answer":"職員費の縮減効果といたしましては、単純には、約４５億円の減ということが言えますが、しかし、一部に業務委託ですとか、非常勤職員に切り替えた経費もありますので、すべてが財政効果とは言えませんが、固定費です人件費を。","voiceIndex":212,"id":"exchange-099"},{"speaker":"藤原委員","kind":"質問","question":"これからの１０年間で、職員構成が大きく変わることがよくわかりました。これは、研修で、このような職員に対して対応ができるものなのでしょうか。普通の民間のサラリーマンというのは、利益追求のために働くわけですから、会社自体がそうですから、危機感というのはものすごくあると思います。だれしも心の中までは見えないので、その辺について教えてください。","respondent":"本間総務部長","answer":"２点目の、こういう研修を受けても効果があまり上がらない職員に対する対応ですが、手立てといたしましても、今、ご説明をした研修プランニング制度を機能させるともに、客観的で科学的な人事考課制度とリンクをさせまして、成績主義を基本とした適正な指導を、当然、今。","voiceIndex":214,"id":"exchange-100"},{"speaker":"藤原委員","kind":"確認","question":"商店街活性化の今後についてお伺いします。その基本的スタンスを再確認する意味で、商店街の現状や、実情に関する基本知識を含めて、質問します。これから４項目質問しますが、まず、ふだん何気なく商店街と呼んでいますが、実際には、商店街と商店会が二つの名称で使われているように思うんです。現在、区内における商店街と、商店会の内訳を教えてください。","respondent":"小栗区民生活事業部長","answer":"区内の現状で申し上げますと、法人化された商店街が３４、法人化されていない商店会が７１ございまして、区内には総計で１０５の商店街組織があります。","voiceIndex":216,"id":"exchange-101"},{"speaker":"藤原委員","kind":"質問","question":"商店街を法人化することによって、どのようなメリットがあるのか。そして、法人化された商店街は増える傾向にあるのか、減る傾向にあるのか、お知らせください。商店街が法人化されていないことによって、補助金を受ける資格とか、補助金の額に影響があるかについても、あわせて教えてください。","respondent":"小栗区民生活事業部長","answer":"補助金等のメリットですが、過去には、法人化をしないと補助金を受けられないというようなところがございましたけれども、現在の国庫補助等におきましては、そのようなことがなく、法人のみじゃなくて、事業の執行内容を見て行っておりますので。","voiceIndex":218,"id":"exchange-102"},{"speaker":"藤原委員","kind":"質問","question":"法人化された商店街組織が減りつつあるということですが、商店街の振興組合を解散する事情というのは、どのようなものなんでしょうか。最近、商店街で合併とか、組織自体の解散という話はあるんでしょうか。あるとすれば、行政として、どのような対応をしていくのか、あわせてお伺いいたします。","respondent":"小栗区民生活事業部長","answer":"ご質問のございました商店街の統廃合ですが、具体的には、現在、ある商店街から、解散したいというようなことで、１件、相談を持ちかけられているところです。個々の事情に応じまして、適切な対応に努めてまいりいたと考えているところです。","voiceIndex":220,"id":"exchange-103"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、品川区内の商店街で、店舗数によって大規模、中規模、小規模という区分けをすると、それぞれどのぐらいの割合になるんでしょうか。そして、そのような規模の異なる商店街が隣り合って存在する状況に対して、今後、どのような活性化の対応をしていくのか、教えていただきたいと思います。","respondent":"小栗区民生活事業部長","answer":"今後とも、活力ある品川区の商店街の火を消さないように、商店街とパートナーシップを持って、品川区の商店街が、個性と活力を持った特色ある活動に取り組めるように、我々のほうといたしましても、支援してまいりたいと考えているところです。","voiceIndex":222,"id":"exchange-104"},{"speaker":"藤原委員","kind":"質問・要望","question":"ほんとうに、２人で小さな会派ですけれども、区長がこれからいろいろ区政をするに当たって、私たち少数会派の要望とか、そういうものをどのように反映させていってくださるか、ぜひお答えください」という質問を、当時させていただきました。このときは、会派というふうに伺ったんですけれども、今回は、議員と区という観点から、最後に、区長からご答弁をいただきたいと思います。","respondent":"高橋区長","answer":"会派の大小の問題、それはまた議会の運営の中では、議長が権限を持っておりますが、議員一人ひとりのご意見は甲乙つけがたく、平等にすべて聞いていくのが、私、区長の責務だと考えています。積極的なご意見をいただけるよう、ご要望申し上げまして、お答えにします。","voiceIndex":224,"id":"exchange-105"}]},{"id":"topic-02","title":"ます。 これをもって、総括質疑を終了いたします。 以上で、平成１４年度品川区各会計予算についての質疑は、すべて終了いたしました。 次に、第９号議案","agenda":"ます。 これをもって、総括質疑を終了いたします。 以上で、平成１４年度品川区各会計予算についての質疑は、すべて終了いたしました。 次に、第９号議案","exchanges":[{"speaker":"築舘委員","kind":"提案","question":"我が会派は、予算特別委員会での集中審査、総括質疑の審議を通して経緯を明らかにし、今後の再発防止と、監査の強化等、万全の措置を求めるよう苦言を呈してまいりました。我が会派は、介護保険制度本来の立場から、介護保険本来の趣旨である相互扶助の精神のもと、収入に応じての適切な受益者負担を求めており、昨年、与党会派の提案で、低所得者に対しての介護保険料減免が行われました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-106"},{"speaker":"堺委員","kind":"提案","question":"校舎改築に備えて、１００億円余を義務教育施設整備基金として確保するほか、我が党の提案によって創設された地球環境リサイクル基金を環境施策の充実のため１０億円余とするほか、母子生活支援施設品川区ひまわり荘を全面改築し、子育て支援の中核施設として設置するなど、我が党の施策を数多く取り入れて、約１３０の計画事業を予算化され、さらに、取り崩し可能な基金が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-107"},{"speaker":"沢田委員","kind":"提案","question":"利用実績が少ないことを理由にしていますが、それならば、信用保障制度の見直しなど、より借りやすい制度を検討すべきではないでしょうか。一般財源は投入していないと言いますが、補助金の半分は２３区の共通財源、財調交付金だったのではないでしょうか。２点だけ述べます。我が党が本議会に提案した第９号議案、予算修正案は、区民の期待にこたえて提案したものだと自負いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":235,"id":"exchange-108"},{"speaker":"本田委員","kind":"質問・要望","question":"品川区が、景気の好不況にかかわらず、長年にわたって行財政改革の努力を積み重ね、区民のニーズにこたえてきた蓄積が新年度予算編成の土台になっているものであり、絶えず公益性と採算性を勘案しながら、時代の波に流されないように、地方自治体のあり方を考える職員気質をつくっていくことは、予算編成時だけのことではなく、日ごろから行うことが重要であり、職員研修をはじめあらゆる機会の中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-109"},{"speaker":"本間委員","kind":"質問・要望","question":"平成１４年度品川区一般会計予算、同国民健康保険事業会計予算、同老人保健医療特別会計予算、同介護保険特別会計予算および同用地特別会計予算について、幾つかの意見および要望を述べ、原案のとおり賛成いたします。これまで、私たちの会派から、本会議および予算特別委員会などを通じ、さまざまな角度からの要望や意見を述べてまいりました。いずれも、区民の声を率直に代弁してきたものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-110"},{"speaker":"田中委員","kind":"意見","question":"建て替え時期を迎えた校舎は、学ぶ場所という意味合いだけでなく、新しい教育を実現できる創造的な空間としての整備をすべきだと考えており、プラン２１によるソフト面の改革が進められていく中、校舎の建て替えとあわせて、新しい時代の学校づくりに向けて、ハード、ソフト両面の改革の成果が表現されていくことを期待しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":241,"id":"exchange-111"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=798#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":108762,"voices":249}},{"id":"h14-20020412-7","meetingId":"h14-cm04","date":"2002年4月12日","dateIso":"2002-04-12","committee":"厚生委員会","time":"午後１時０８分～午後５時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"嶋委員","kind":"質問・要望","question":"５月９日開所式ということで、定員が今２０名ということなんですが、人数的にどれぐらいの方が今予定されていらっしゃるんでしょうか。それからあと、送迎サービスがあるということなんですが、一番遠いところからいらっしゃる方は、どこら辺からいらっしゃるのか、もしわかっていれば教えいただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"定員の関係ですけれども、まず２０名で既に４月１日から出発をいたしました。定員いっぱいです。それから、先ほど申し上げましたけども、来年になりますと養護学校の卒業生で通所の見込みの方が１０名以上今のところ手が挙がっておりますので、３０名に定員を拡大するです。","voiceIndex":22,"id":"exchange-001"},{"speaker":"嶋委員","kind":"質問","question":"来年から通所に手を挙げている方が１０名いらっしゃると思うんですが、これは募集というか、登録制になっていらっしゃるのか、定員になるための募集とか。それと、今２０名定員ぴったりということなんですが、年齢的なものがわかったら教えていただけますか。","respondent":"日下部障害者福祉課長","answer":"年齢につきましては、これは養護学校を卒業される方は１８歳ですね。それから、例えば、年齢的には、平均年齢は出ておりませんけれども、例えば高齢の方ですと５０歳代の方が２人ぐらいいらっしゃるということで、かなり年齢的にはばらつきがあります。","voiceIndex":24,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、いろいろ障害の程度などを見ながら調整をしているということなんですが、今回この対象の方というのは、障害の程度というのはどのくらいまでというふうなのがあるのかどうかということが一つと、それからあと、職員体制がどういう状況になっているのかということと、それからあと、補助金というか、そういうふうなのがどれぐらいになっているのかについて教えてください。","respondent":"日下部障害者福祉課長","answer":"ただ、個々にいろいろ状況の違いがあるということで、中心になりますのは、大体２度から３度、全体で知的障害というのは４区分に分かれておりますけれども、大体２度から３度の方が中心になってまいります。それから、職員の体制ですけれども、現在は国の基準もあります。","voiceIndex":27,"id":"exchange-003"},{"speaker":"鶴副委員長","kind":"質問","question":"これは何で更生施設というんですか。どうして更生施設というんですか、法律に基づいているとは言いますけども。なぜ、いつまでも更生施設なの。","respondent":"日下部障害者福祉課長","answer":"こういうことについて、日常的な訓練、あるいは指導を通してできるだけ自立して日常の生活を行えるようにと、そういう意味合いで更生施設ということでの位置づけがされているところです。","voiceIndex":29,"id":"exchange-004"},{"speaker":"鶴副委員長","kind":"質問","question":"もうそろそろこの法律の文句を変えたらどうですかとか、そういうことはやっぱり積極的に自治体から、あれは法律だから国のことだということじゃなくて、そういう積極的な働きかけというのがとっても大事じゃないかというふうに思うんですね。どうしてもっといい表現が、みんなの英知を絞ったら出てこないわけがないというふうに思うんですが、所管の課長はどう思いますか。","respondent":"日下部障害者福祉課長","answer":"これは法律に基づく用語ですので、なかなか正直言って難しいところはありますけれども、確かにご指摘のようにもう少しわかりやすく、旧態依然たる表現ではなくて、そのような形で表現も少し変わっていけばいいんではないかというふうに私も個人的には思いますけれども。","voiceIndex":31,"id":"exchange-005"},{"speaker":"鶴副委員長","kind":"質問","question":"わかりました。全体的な問題ですので、例えば今まで保護課というのは生活福祉課というふうに名称を変えましたよね。だから、それは変えてはならないという法律はなかったと思うんです。生活保護となると、何となく国のお世話になるんだからということで、一歩しり込みしながらでも行かざるを得ないというような面もあるじゃないですか。「物言えば唇寂し」。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-006"},{"speaker":"鶴副委員長","kind":"意見","question":"この１番の中延ですね、定員が３４名で現員が５４名でしょう。どういう措置をされているのかな。現況ですね、別に一つのところに閉じ込めるわけじゃありませんからあれですが、ちょっと説明していただけませんか。","respondent":"辻田児童課長","answer":"中延は施設面でいろいろな対応をしています。中延の学童保育クラブにつきまして、４１平米の育成室でございましたけど、ここをいろいろ工夫しまして、６４平米に拡幅して対応している、当然児童数が増えましたので、それに合わせてロッカー等の整備もしたというような形です。","voiceIndex":39,"id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問","question":"でも、数字だけ見ている人は、３４名のところに２０名もオーバーしていて大変なことじゃないかなんて見る人もいるじゃないですか。だから、今それなりの工夫をしているということなんですけれども、だったら、定員というのは、定員の枠の見直し、どのぐらいの施設規模かわかりませんが、この定員の考え方ですね。","respondent":"辻田児童課長","answer":"そういうことなんで、それぞれ地域の状況により、いわゆる学童保育に通う児童が多くなります。そのたびに変更していかなければならないということもありますので、その辺はいわゆる現在のところは弾力を持って運用するということで定員については考えている、そういう状況です。","voiceIndex":41,"id":"exchange-008"},{"speaker":"鶴副委員長","kind":"質問","question":"弾力的、要するに小さくても、オーバーになっていたとしても、学童保育クラブとしての機能というのが十分に発揮されていると。そういう説明がちゃんと外に向かってないと、何だかんだと非難されることになりかねない。そういうことを心配するわけですよ。そういうことだというふうに私は思っているわけですよ、創意工夫して、それなりの対応をしているということですから。そこあたりは心配ないわけですね。","respondent":"辻田児童課長","answer":"今のご質問ですけど、前児童課長もそのたびごとにお答えしておりますけど、児童センターのあるところはその一体化、それから単独館につきましては、単独館全体を使って、また園庭なども使いまして、いろんな工夫をしながら対応しているという状況なので。","voiceIndex":43,"id":"exchange-009"},{"speaker":"須藤委員","kind":"質問","question":"それからもう一点、学童に入っていて、６時なら６時ぐらいまでですか、お預かりをするという形になっていると思うけど、途中でおけいこごとに行きたいと。おけいこごとが終わって、まだ家族の者が帰っていないので、また学童に戻りたいというような相談があったんだけど、そういう場合も学童としては引き受けてくれるでしょうというような話を街の人にしたんだけども、そういうところはどうなんですか。","respondent":"辻田児童課長","answer":"１点目ですが、少なくなったところにつきましては、当然職員についても弾力的な対応をしているということで、ついていた非常勤を多くなったところに異動させるというような形での対応が当然なされております。","voiceIndex":45,"id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"弾力的な運用をしてもらいたいと思っているんですけども。だけども、家族がなかなか夜遅くならなきゃ帰れないと。ですから、そのおけいこのときのお話をきちんと家族の人としてあれば、この時間帯はおけいこに行っています。そしてまた遅れて、例えば４時なら４時、５時なら５時にまた学童に入りますということができていれば、そういうお子さんもいいんじゃないかなと思うんですけども、いかがでしょうか。","respondent":"小沼福祉事業部長","answer":"そういうものの中での対応でまず考えていくというのが基本的な線ですけれども、今のようなケースになりますと、個々具体的、ケース・バイ・ケースで何とも言えないところがあるんですが、もし、そのお子さんがどこも行くところがないと。","voiceIndex":47,"id":"exchange-011"},{"speaker":"須藤委員","kind":"質問・要望","question":"週に１回とか２回、そういう場合があったら、おうちの方がある程度学年が上になってくれば、お子さんに勉強させたいなというような気持ちがあろうと思うので、それだったら、やはり弾力的にきちんと親御さんのほうからそういう申し出があったら、そういう状況もかんがみて受け入れてあげるような態勢をとっていただきたい。要望だけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"いろいろ今意見が出ましたので重ならないように質問いたしますが、それぞれ減っているところと増えているところがあります。これはこれでそれでいいと思うんですけど、これからの学童保育クラブの方向性について確認といいましょうか、答弁いただきたいんですが、例えば漸減していく学童クラブとか、それからこの表で見てもマイナス２１人のところもあって、プラスのところもある。","respondent":"小沼福祉事業部長","answer":"先般の予算特別委員会での論議あるいは審議の状況の中の一コマとして、今後の大きな一つ、児童課が当然対応しなきゃ、課題として今の、実は学童保育クラブ全体の問題、今後どういう形で取り組んでいくのかというようなところを話した段階ですけれども。","voiceIndex":50,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、その１、２、３年生を別なところに今までは措置していたんだけれども、これから具体的にすまいるスクールが展開していけば、それぞれの小学校ごとにそれが設置されてくるということになってくると、この整合性というのは十分に考えて生かされると考えていますので、ぜひ検討していただきたいということが一つと、それから多分これから問題になってくるのが。","respondent":"辻田児童課長","answer":"その辺でのすまいるスクールと学童保育クラブとのすみ分けというんですか、そこら辺を十分精査した形で今後の大きな課題として早急に検討していきたいというぐあいに考えております。","voiceIndex":52,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この一番下のところに４年生以上の延長児が１１名というふうに書いてあるんですが、この１１名の子どもさんがどこに入られているのかを一つ教えていただきたいのと、それに対しての職員体制がどうなっているかを一つ教えていただきたいと思います。それとあと、現在の指導員の定数と実際の人数を教えてください。とりあえずお願いします。","respondent":"辻田児童課長","answer":"ですから、増えているところ、増えていないところ、それぞれあるです。それから指導員の定数ですけど、平成１３年度は定数１１３人に対して、１２３名です。平成１４年、１１３名のところ、１２６名という状況になっております。","voiceIndex":54,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"延長児が２５名から１１名に少なくなっていて、職員体制はちょっとはっきりわからなかったんですが、１１名に対して非常勤が基本的には１名という形でついているということなのか、１１名に対しての職員の体制ということについてちょっと教えていただきたかったので、その点についてひとつお願いしたいと思います。","respondent":"辻田児童課長","answer":"例えば、中延ですと、障害児関係で４名、それから荏原ですと２名、それから荏原南で１名、源氏前はついておりません。それから原で１名、それから平塚で１名ということで、大体１名ずつはついてあります。","voiceIndex":56,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの地域というのはいつも東中延に学童がなくなってから、かなりオーバーしているというふうな状況が続いている地域なんですけど、それで新たな学童をつくってほしいというふうな要望も地域の中では出されているんですけども、そういうことに対して、区として今後どういうふうに、今年だけ多くて、来年はまた少なくなるという、そういう状況じゃないという事態があると思うんですね。","respondent":"辻田児童課長","answer":"それが今年は５９名ということで、約１０名ばかり増えているわけですけど、あそこのいわゆる施設全体を使って要するに受け入れていくというような形で考えておりまして、ほかにそういうものをまたつくるということは、全体のバランス等も崩してまいりますので。","voiceIndex":58,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどもすまいるスクールとの関係ということで出ていましたけれども、すまいるスクールはすまいるスクールで、やはり期待も多いですし、体制をきちんと整えながら評価できる部分というのはあると思うんですけれども、学童というのはまた共働きをしている子どもへの対応ということで、すまいるスクールとは基本的に違う性質の部分がありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-018"},{"speaker":"船波委員","kind":"質問","question":"４年生以上の延長児を受け入れていることについて、この子どもたちは障害があることなどから、適切な保護が受けられないでいるから延長して受け入れているというようなご説明だったと思いますけれども、障害があることなどで適切な保護が受けられないでいると判断するその基準は何なんでしょうか。","respondent":"辻田児童課長","answer":"今ちょっと私まだ十分詳しくはないんですけど、いわゆる一律的に何かをぱっと横引きで区切るというような形はしていない。実際を見て、そしてお預かりできるかどうか、そういうことを判断しながら実施しているという状況です。","voiceIndex":61,"id":"exchange-019"},{"speaker":"船波委員","kind":"質問","question":"もちろん状況は、子どもたち、保護者の状況は一つであるわけですけど、それを区の側が見たときの判断と、保護者の側から見た判断が異なってきてしまうと、明らかな基準がない場合、ただ単に個別の状況を見て判断するという場合には、同じ状況を見た場合でも違う判断があるということが生じてくるケースもあると思いますけれども、そういったことについては、どうやって対応していくんでしょうか。","respondent":"辻田児童課長","answer":"先ほどはちょっと失礼しました。保護者や児童と面談を実施して、そして区の中にある障害児等の育成審査会、こちらのほうで最終的に判断することになっております。当然そこら辺で親御さんと私どものほうの判断の違いという、思いの違いですか、というものは出てくると思います。","voiceIndex":63,"id":"exchange-020"},{"speaker":"船波委員","kind":"質問","question":"私の印象で言うと、同じような部署の中で行われているような気がしてしまうんですけど、その辺の体制はそれぞれどうなっているんでしょうか。","respondent":"辻田児童課長、小沼福祉事業部長","answer":"ですから、いろいろ話の中でどんどん突き詰めていく中で、話し合いをしながら、いわゆる一般的な状況の中でどうだという形での判断、それから具体的ないろんなケースの中で、その後の対応をお話ししながらやっているという状況であって。ですから、そこの中で出てきますのは、一般に子どもの生活動作、日常生活動作、ＡＤＬということで、我々よく言うんですが、そこのところの動きと、それから医療的なかかわりを要するお子さんであるのかどうなのか。","voiceIndex":65,"id":"exchange-021"},{"speaker":"船波委員","kind":"質問","question":"その子どもにとって、その子どもを受け入れる体制があるかどうかとか、例えば、もっと医療的なものが必要なのではないかということはもちろん例えば医師であるとか、学童のほうの体制であるとか、具体的なものが、判断する基準があるかと思いますけれども、例えばその子どもを学童で過ごさせるか、あるいはほかの場で過ごさせるかどうかというのは、やはりその家庭の方針。","respondent":"小沼福祉事業部長","answer":"後半のほうの問題から入っていきますと、方針決定云々というのは、私どものほうで方針決定について決めると、こういうことはございません。","voiceIndex":68,"id":"exchange-022"},{"speaker":"船波委員","kind":"確認","question":"では最後に、一つだけ確認ですけど、じゃあただいまのご説明であった、例えば看護婦さんの配置などができない、そういった要素に基づいて決めるということで、親の方針について区が決めたことを押しつけているのではないというように私は理解しましたけれども、それでは、その子どもの状況から、特別に看護婦さんをつけたりというような状況がない場合は、家庭の方針を尊重するということですか。","respondent":"小沼福祉事業部長","answer":"ですから、自分の家庭の方針あるいは自分の方針がこうだから、それに沿うべきではないか、従うべきではないのかというのは、それは決定にはならないと思います。参考にはしますけども、そのことをもって決定というふうには考えてございません。","voiceIndex":70,"id":"exchange-023"},{"speaker":"船波委員","kind":"意見","question":"こうやって質疑応答を続けていても永遠に続いてしまうんじゃないかと、何かグルグル回ってしまうような気がするんですが、それでは、児童福祉施設だから、子どもの福祉のために判断をするということですけれども、それではこの子にとってこういう場で過ごしたほうがいいという親の判断より、区のほうで判断したものでいくということなわけですね。","respondent":"小沼福祉事業部長","answer":"例えば、学校の生徒ですと、５年、６年となりますと、入ってくるお子さんというのは正直申し上げまして、１年生、２年生、３年生ですから、５年生、６年生になったとき、自分より下の集団のお子さんとだけ接触しているほうがよろしいのか、それとも児童センターというような場面。","voiceIndex":72,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のことが区がベターというふうに考えるのと、親が考えるベターというのが食い違っているというふうなことで、区の出した学童保育の延長を認めないというふうなことに対して、親がそれでは納得いかないというふうな、そういう状況になったということだと思うんですが、そこら辺のところというのは、親もやっぱり我が子ですから、かけがえのない我が子ですから。","respondent":"辻田児童課長","answer":"２５名から１１名ということで、１４名の方が延長しなかったわけですけど、その中で、今お話にあった親の思いも十分伝えて、そして話をしていくということでは、私どものほう十分対応しております。","voiceIndex":74,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その個別のケースに関しては、私たちもかかわったことですので中身はよく承知しているんですが、今回４名の方がそういうふうに区のほうに対していろいろと要望されていったというふうなことがあって対応されたということがありますけれども、じゃあ子どもにとってよりいい対応というふうなのはどうなのかというところで、やはり学童には受け入れられませんというだけじゃなくて、じゃあその先に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問","question":"ＩＳＯのことをお伺いいたします。公立園では全国初ということで、ほんとうにお疲れさまでございました。それで、質問のほうは、まず一つは、これをこれからどういうふうに区内の保育園で展開していくかということを一つ聞きたいのと、それからたしかこれは更新が必要ですよね。何年かたったときに、更新。","respondent":"金子保育課長","answer":"節目節目で更新ということが出てきますので、そこにおいては、私ども今回取りましたのは９４年版ですけれども、現在２０００年版というものが出ております。更新のタイミングにおきまして、この２０００年版への切りかえということを考えていく予定です。","voiceIndex":81,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問・要望","question":"一つ、今の答弁の中で、いろいろありがとうあります。一つは、これからの展開をどうするかということをお伺いした中で、これは一つの情報提供であると今お話があったんですけど、それはそれで考え方についてはわかる部分があるんですけど、これだけのＩＳＯ９００１を全国初で取ったということは、いろんな意味でＰＲになるんじゃないですか。","respondent":"金子保育課長","answer":"その辺を審査員の方が実際に現場でいろいろなものを確認しながら、マニュアルと実際の行動というのが記録を通して確認できるように審査してきたというふうなことで今回の登録審査に通ったというふうに認識していますので。","voiceIndex":83,"id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それはそれでわかりますよ。それで、現場の苦労は間違いなくありますよ。それはただでさえ忙しい保育園の中で、こんなことをやれというのは酷かもしれないけれども、こういう成功例が同じ区内にあって、しかも、全国初でありますから、これをどうしてもっと進めていこうとしないのかなと素直に思いますので、ちょっとしつこいようですけど、その確認答弁をいただきたいと考えています。","respondent":"金子保育課長","answer":"ですが、これの手法というものを同じような形でほかの３６園全園が取り組んでいこうというふうに考えているところですので、イコールにはならないと申しましたのは、先ほど申し上げたとおり、それぞれの園の微妙な違いとかがありますので。","voiceIndex":85,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＩＳＯのほうが先に論議になっているのでＩＳＯのほうをお聞きしたいんですけど、今冊子をつくっていくということで言われましたけれども、冊子というのは具体的にはどういう中身になるんでしょうか。","respondent":"金子保育課長","answer":"冊子についてのお尋ねですけれども、先ほども申し上げましたけれども、保育基本マニュアルというのは片面印刷で５ミリちょっとの厚さですけれども、これの付属の手順書というのが片面印刷でこれぐらい、大体全体で５００ページ程度のものがありますので。","voiceIndex":87,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ、冊子はマニュアルそのものということでよろしいんでしょうか。","respondent":"金子保育課長","answer":"失礼しました。先ほど申し上げましたとおり、基本マニュアルと、それに付属しますさまざまな手順書というものです。","voiceIndex":89,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そうすると、この写真、例えば学校のＰＴＡなんかでも写真を広報で使うときには、子どもの許可を取ったりというふうなのがありますけれども、そういうところでは、すべての父母が自分の子どもがいろんなところに写真で載って、それがいろんなところに配付されるということになると思うんですが、そこいらのところは父母の皆さんは了承されているということの上でされるのかどうかについてお聞かせください。","respondent":"金子保育課長","answer":"私どもは従前から外部に対して提供する写真等につきましては、すべて保護者の了解を確実にとるようにしております。今日お配りしたところにも写真がありますが、これについても公開することでご了解がとれているものです。","voiceIndex":91,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"じゃあ、この冊子というのは、販売もしていくということですけれども、どれぐらいの部数をつくられる予定なのかをちょっと一つお聞かせいただきたいのと、それからあと、このマニュアルを維持していくというのもかなり大変な作業になっていくと思うんですが、先ほど継続審査を半年に一遍と、更新というのは３年ごとですか、そういう形でなっていくと思うんですが。","respondent":"金子保育課長","answer":"そこのところももちろん認めていただいたわけで審査登録されたわけですが、私どもとしましては、当面この継続審査ということにはきちっと合格するように取り組んでいくつもりですので、当面ですけれども。","voiceIndex":93,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"昨年どおり１名配置ということなんですが、そうすると、これをこれと同じような形でほかの園にもＩＳＯは取得しないまでも、同じようにマニュアルづくりを今後ずっとやっていくというふうなことだと思うんですけれども、それに対しての体制というのはどう考えられているんでしょうか。","respondent":"金子保育課長","answer":"私どもは、ＩＳＯの取得というのは初めての経験でしたし、これを更新していく、継続していくことも初めてのことですので、これにつきまして、東五反田保育園には当面１名置くという考えで置いているわけです。","voiceIndex":95,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この作業というのはかなり大変だというのはいろんな本を読んだりすると、そういうふうな形でいろいろ書いてあるんですけれども、ほんとうに書類の山になって大変だというふうなことで書いてあるものもありましたけれども、多分ほかのところもそういうところで実際こういうふうな形でされていくことが今でも保育のほうが忙しくて、すごく体制がぎりぎりで大変だというふうな中で。","respondent":"金子保育課長","answer":"それからもう一点は、実際にかかった経費ですけれども、平成１３年度分でこの審査をお願いした費用で、２０６万2,２００円ほどかかっております。登録審査の継続分の予算につきましては、今年度で３５万円の予算を計上しています。","voiceIndex":97,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この予算についてなんですが、審査で２０６万幾らということなんですけれども、そのほかにはかかってはいないんでしょうか。コンサルタントとか、そういうふうなのはなかったでしたでしょうか。","respondent":"金子保育課長","answer":"失礼しました。そこをちょっと答弁漏れしまして失礼いたしました。コンサルティングの委託料としましては、２１０万円を計上しておりました。ですので、合計すると４１６万円余というふうになります。","voiceIndex":99,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今年度の予算というのは３４万円でしたでしょうか。〔「３５万円」と呼ぶ者あり〕３５万円。ごめんなさい。それだけで、これから先というのはこの費用だけで済むということでいいんでしょうか。それとあと、このＩＳＯを取って継続していくということなんですが、これはずっとこの先も延々とやり続けるという方向なのか、そのことについてお聞かせください。","respondent":"金子保育課長","answer":"今後ずっとこれを継続していくかということですけれども、私どもとしては、現在のところせっかく取得して継続するというところに意義があるというのが既に皆様ＩＳＯ１４０００のほうでもご認識があると思いますので、そういう意味で。","voiceIndex":101,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"とにかく現場で保育される子どもたちがよりよい保育になるようにお願いしたいと思います。ご苦労さまです。そして、ちょっとお聞かせいただきたいんですが、締め切りのときの入園申請者数というのは、トータルでどれぐらいだったのか。昨年と比べてどうだったのか、そしてその中で入園できた方が、０、１、２、３、４、５歳、何人入園できた方がいるのか、その人数についてお聞かせください。","respondent":"金子保育課長","answer":"比較のためにもう一つ数字を申し上げますと、全体では1,２１７名、区民外の方も含めて1,２１７名の申し込みがありました。これは昨年と比較しますと、昨年が1,０８２人でしたので１３５人、約１2.５％の増というふうになってあります。","voiceIndex":103,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません。入園できた方の０歳児とか１歳児がすごく多かったと聞いたんですけど、０、１、２、３、４、５歳の人数を教えていただきたいんですが。","respondent":"金子保育課長","answer":"失礼しました。入園された方のうち、区民の方に限りますと、０歳が３１８人、それから１歳が２８９人、２歳が１３１人、３歳が１１３人、４歳が３３人、５歳が１４人というふうになってあります。","voiceIndex":105,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民で申請された方が1,１３０人、うち入れた方が８９８人ということで、待機児が１８８名と先ほどお聞きしたんですけど、この差というのがどういうものなのか、それとあと、待機児というのは、待機児の基準、待機児の考え方についてお聞かせいただきたいのと、それとあと、例えばこの中にも、３歳未満児というところが多いところというのは、すごく大変かなというふうな思いがするんですけど。","respondent":"金子保育課長","answer":"３歳未満児の数が多いというふうにご指摘いただきました園ですけれども、大崎と東五反田、このあたりにつきましては、ご案内のとおり１０時までの夜間保育を実施している園です。","voiceIndex":107,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"待機児の数なんですが、先ほど区民の方の申請者が1,１３０人で、うち入れた方が８９８人という人数だったようにお聞きしたように思うんですが、そうすると、これを単純に引くと２３２人になるんですけど、この１８５人というふうにはちょっと私の計算だとならないんですが、その待機児の１８８人と２３２人、この差がちょっとよくわからないんですが。","respondent":"金子保育課長","answer":"大変失礼しました。ちょっと説明が悪うございました。申込者の中には、転園の希望者も含めて数えておりますので、その数がかなりいらっしゃいます。転園の中で実際には転園できなかったという方が４７名おりますので、その分を引くと数字が合ってくるというふうに思います。","voiceIndex":109,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"わかりました。かなり今少子化と言われながらも、働く女性が増えて毎年毎年保育園の入園希望が増えているという状況だと思うんですけれども、これから待機児解消に向けて品川区が去年は分園とかなんかも検討するというふうなお話もあったんですけど、そういうことも含めて待機児解消についてお聞かせください。","respondent":"金子保育課長","answer":"事業は違いますけれど、幼保一元化の事業として二葉幼稚園内に９月に保育園の部分もオープンする予定にしておりまして、こちらのほうは４３名ということで、年度内に６９名の枠が増えるということで一定考えておったわけですけれども、今後の展望につきましては、やはり大崎。","voiceIndex":111,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、ニュースでもかなり保育園の虐待死の問題が取り上げられていますけれども、ほんとうに親が安心できる保育園の整備にぜひ今後とも取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-043"},{"speaker":"須藤委員","kind":"質問・要望","question":"ＩＳＯのところで、ちょっとつまらないことで申しわけない。保育園の１日のところで、おやつが終わってお昼寝のところなんですけども、「ふとんに入り、入眠します」という表現がしてあるんだけど、こういう言葉があるのかどうか、ちょっと聞かせていただきたいと思うんですけども。","respondent":"金子保育課長","answer":"八潮についての考え方ですけれども、ご指摘のとおり八潮中央につきましては、１０時までやっているということもありまして、非常に希望が多い。","voiceIndex":116,"id":"exchange-044"},{"speaker":"須藤委員","kind":"質問","question":"ですから、これからまた新たに２歳、３歳というものを含めて弾力的に運用するベースがために現在８０人なら８０人ぴったりでとまっているよとか、逆に１人減らしているよという考え方、将来的に弾力化ができる状況をつくっておくよというふうに考えていらっしゃるから今の状況で今後の枠を考えているんで、こういう数値ですよというふうに理解をしていいのかなというのが１点と、これが。","respondent":"金子保育課長","answer":"先ほどの「入眠」の言葉ですけれども、確かに一般的にわかりやすい言葉をこういったマニュアルとか手順書では使うべきだというふうに私も基本的には考えておりますので、言葉の使い方については、また再検討しながら考えていきたいと考えています。","voiceIndex":118,"id":"exchange-045"},{"speaker":"鶴副委員長","kind":"質問","question":"保育基本のマニュアルに関して数点お伺いしたいんですが、これは要するにあくまでも基本をマニュアル化した。誤解を受けるのは、これを忠実に職員の人たちが実践することによって、職場の労働が加重になるとかというようなことではないというふうに私は理解するんですね。預ける側にとってはすごく安心して０歳児から幼児までのお子さんを保育園に預けることができる。この点、どうですか。","respondent":"金子保育課長","answer":"つまり、今までこういった形で保育をやっていた、あるいはマニュアル化することによりまして、自分たちのやり方というのがみんなに明らかになっていくわけですから、そのマニュアル化する際には、書き記す際には。","voiceIndex":120,"id":"exchange-046"},{"speaker":"鶴副委員長","kind":"質問","question":"先ほどのご答弁による説明によりますと、この冊子は５００ページ、いわゆる裏表して２５０ページぐらいになるのかなと。相当の冊子になるわけですが、ところで、これは品川区のパソコンを開いたら、このマニュアルはパーッと見れるのでしょうか。","respondent":"金子保育課長","answer":"現在のところ、このマニュアルそのものをインターネット等々で公開するということは考えておりませんけれども、こういったものを私どもが取得して、大まかな部分、概要については明らかにしていきたいというふうに考えております。","voiceIndex":122,"id":"exchange-047"},{"speaker":"鶴副委員長","kind":"質問","question":"打ち込みの作業は大変だろうというふうに思うんですが、どういうふうに基本的な考え方、基本的な戦略というのは難しい言葉ですけど、どうなっているんでしょうかね。ＩＴ担当の部分と、事業部ごとの話し合いの中で、この事業については詳細にどこまでお知らせしていこうとかという打合せというか、連携というのはどういうふうになされているんでしょうか。","respondent":"金子保育課長","answer":"その意味では、この冊子については版権といいますか、著作権についてはきちっとした形にして対応していきたいと考えていますので、今のところ、インターネットでどういうふうに公開するかというのは結論は出しておりませんけれども。","voiceIndex":124,"id":"exchange-048"},{"speaker":"嶋委員","kind":"質問","question":"ほんとうにすばらしいのができて、私ども相談を受けることがこういう形でどんどんなって、安心してほんとうに品川に住み続けていただけるという大前進だと思って大変うれしく思っております。そういう中で、そういう私たちにも相談に来る方もいらっしゃいますが、どのように利用される方にお知らせとか、ご相談に乗る体制を今整えられていらっしゃるのか、お聞きをしたいと思います。","respondent":"中川原福祉事業部副参事","answer":"どういう手順で進めていくかというようなことをお知らせしてまいります。在宅介護支援センターとか、民生委員の方とか、日々そういった情報を集めてこちらにつないでくださる方には丁寧に説明してまいりたいと考えています。","voiceIndex":130,"id":"exchange-049"},{"speaker":"嶋委員","kind":"質問","question":"きっと相手の方もどんどん年をとってくるし、だんだんわからなくなってくる。お互いに頼んだほうも、頼んだことも忘れていくと、いろんな事故絡みになっていく部分もあるかと思いますが、そこら辺はちょっとどのようにお考えか、お聞きをしたいと思います。","respondent":"中川原福祉事業部副参事","answer":"ただし、在宅のケースにつきましては、すぐにはちょっとできない状況ですので、そのケースの状況を分析しつつ、そういったチームで今後のことを考えていきたいというふうに考えております。","voiceIndex":132,"id":"exchange-050"},{"speaker":"嶋委員","kind":"質問","question":"ちょっと私も前にお聞きしたことがあるんですが、施設に入っている方でも、こういう形をとっている方が何人かいらっしゃるとお聞きしたんですが、ちょっと施設のほうのことでお聞きをしたいと思います。","respondent":"中川原福祉事業部副参事","answer":"施設につきましては、特養なんですけれども、この間、特養の方が、調査をいたしまして、今特養で困っていらっしゃる、ここに該当しそうなケースについては情報を集めております。順次計画的にその方たちに制度をご活用いただくような形で今年度は進めていく予定です。","voiceIndex":134,"id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問・要望","question":"一つだけなんですが、利用料の基準といいましょうか、算定方法、いわゆる利用料はどこにかかってくるのかということを素直にお聞かせいただきたいのと、それから、そのほかの支払いとか立て替えについては当然この申し込みの方の遺産、資産を活用すると思うんですが、利用料というのは、一体どこで発生をして、どういう基準で、それからどれぐらいの負担をいただくかという説明がなかったと思いますので。","respondent":"中川原福祉事業部副参事","answer":"そのほか、法律家とか司法書士の方が必要な非常に専門的な内容につきましては、やはり実費ということになってまいりますので、日本弁護士連合会とか司法書士会が報酬基準というのを出しておりますので、そこら辺を基準としまして考えていくです。","voiceIndex":137,"id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"単純に生活支援の方の１時間1,０００円のことで済む場合もあれば、場合によってはそういう弁護士、司法書士、専門的なところも来るでしょうから。意思が例えば著しく欠けている、それがその状態がたとえ１０年かかって亡くなるかもしれないし、それから１週間で亡くなるかもしれない。その間の例えばかかる費用の算定というのはどういうふうにしていくんでしょうかね。それがすごく気になるんですが。","respondent":"中川原福祉事業部副参事","answer":"それは一応一月お幾らという形でお見積もりを立てまして、それが１年ですと１２カ月分になりますので、そういったお見積もりといいますか、支援プランにはそういった料金も含みまして計算をします。","voiceIndex":139,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、例えばどう質問したらいいんでしょうか。利用料を先に払って、それで、手前に亡くなった場合の精算をして、そのお金はどうなっていくんでしょうかということ。そういうふうな個々のケースに対してどういうふうに検討していくかということをお聞かせいただければと思います。","respondent":"中川原福祉事業部副参事","answer":"ですから、そういった面では、逆にこういった方たちの参加が必要な方というのは、そういった層になりますので、後ほど回収ができるのではないかというふうに考えております。","voiceIndex":141,"id":"exchange-054"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほども質問しましたように、多分いろんなケースがあって、いろんな個々の事情が相当入ってくる話だと思うんですね。だから、これがいいという回答がすごく見つけにくいところではあるんですけど、でも、始めていくわけですから、個人の財産というものを前提にしながらも、権利がそれぞれ守られる仕組みづくりをぜひつくっていただきたいというふうに要望しておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-055"},{"speaker":"鶴副委員長","kind":"質問","question":"ちょっと教えてほしいんですが、この財産保全を基本内容とするという、要するに幅広い支援の内容として、定期訪問とともに財産保全を基本内容とする。この財産保全という意味は、どういう範疇を言うのですか。","respondent":"中川原福祉事業部副参事","answer":"それで、通帳をいつもお使いになるもの以外はお預かりしておくという、それから証書類もなくさないようにお預かりしておくという、そういったお入り用なときは、こちらから持って伺うという、そういったものがこの財産保全サービスというような内容です。","voiceIndex":144,"id":"exchange-056"},{"speaker":"鶴副委員長","kind":"質問","question":"極めて難しい仕事だなというふうに思うんですね。それで、その点は後でちょっとお伺いしますが、この支払い猶予だとか立替払い制度をつくると。そのための運営財源とするために基金を設けると。この基金というのは、社会福祉協議会がその基本額を捻出するのか、それとも別なところから出捐金という形で、それを基金の基本額と定めていくのか、そこをちょっと説明していただけますか。スタートに当たって。","respondent":"中川原福祉事業部副参事","answer":"基金ですが、区の補助で当初1,０００万円で運営を始めます。これは取り崩し型で充当してまいりますので、運営状況を見まして、また積み増しといいますか、またいただく額を増やしていくこともあろうかと思います。とりあえずは1,０００万円からスタートです。","voiceIndex":146,"id":"exchange-057"},{"speaker":"鶴副委員長","kind":"質問","question":"いただく先は品川区と、こういうことですね。それを要するにベラベラしゃべる人はいないと思うんだけど、そういう公務員だったら公務員なりに知り得た情報をむやみに公言とか、あるいは公表してはならないみたいなペナルティー、それを犯した場合はペナルティーとかあるじゃないですか。このここで言うところの後見人制度に係わる人たちの身分というか、これはどういうことになるわけでしょうか。","respondent":"中川原福祉事業部副参事","answer":"ここに品川区とも非常に強い連携でやっていくというのは、戸籍の調査とか、いくら社会福祉協議会でもできないことがありますので、それは品川区のほうと連携してできることを分担するということで、そこら辺も配慮しながら進めていきたいというふうに考えております。","voiceIndex":148,"id":"exchange-058"},{"speaker":"鶴副委員長","kind":"質問","question":"だから、例えば町会長が、「おい、お年寄りはどんな生活をしているのか」、あるいは「知らせてくれよ」「教えてくれたっていいじゃないか」と、何かの災害があったときに、そういう話があったとしても、でも、そういう守秘義務があるからお話をされない。対処できるとなると、こういう場合は、こういう法律が適用されてペナルティーを受けることになりますとか、そういうところはどうなっているんでしょうか。","respondent":"中川原福祉事業部副参事","answer":"もう一点、社会福祉協議会の中に今従来財産保全管理サービスの審査会があったんですが、それも今度権利擁護の運営委員会ということで法律家とか、弁護士の方に入っていただきまして、適正な運用がなされているかということもチェックをしていただくという。","voiceIndex":150,"id":"exchange-059","title":"町会・自治会支援"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そしてあと、スタッフ体制なんですけど、先ほどから守秘義務についてお話がされていますけども、社会福祉協議会のコーディネーターが支援プランを作成し、そして支援専門員が基本的に日ごろからこういふうに標準サービスを行っていくという形になると思うんですが、このコーディネーターと生活支援員というのは、どういう資格、資格とか、どういう方がされて、どれぐらい、何人ぐらいいらっしゃるのか。","respondent":"中川原福祉事業部副参事","answer":"このスタッフの体制ですが、まず、社会福祉協議会のコーディネーターは現在５人を予定しております。社会福祉士という資格を持った職員が当たります。生活支援員ですが、これは民生委員のＯＢとか、高齢者クラブの方とか、また、そういった方たちを予定しております。","voiceIndex":152,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区長申し立て権というところなんですけど、これはだれがどういう形で判断するのかということと、あとプレス発表のところで、予算が出ていましたけど、ここのところで区長申し立て経費に７５万円というふうになっているんですが、この区長申し立てのところでどういうふうに費用がかかってくるのかについて教えていただきたいと思います。","respondent":"中川原福祉事業部副参事","answer":"区長申し立ての判断をどのような形で行うかというご質問ですが、それにつきましては、こういったケースが出てまいりますと、ここにあります社会福祉協議会と品川区と、それからそこに関連しているケアマネージャー、民生委員の方とケース会議を開きまして、この方の状況について。","voiceIndex":156,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ本人のほうから戻ってくるということなんですけど、その費用は大体どのぐらいかかるのか、教えてください。","respondent":"中川原福祉事業部副参事","answer":"手続料としまして、いろいろな書類等をつくったりする費用がございまして、収入印紙等がかかるんですけれども、それにつきましては、収入印紙とか郵便切手等々がございまして、１万円程度のそういった経費がかかります。","voiceIndex":158,"id":"exchange-062"},{"speaker":"嶋委員","kind":"質問","question":"すばらしい事業ということで、大変５５歳以上の方に関しては、ほんとうに朗報かと思いますが、やはり、企業側と就職側双方のいわゆる開拓というのが一番やっぱり大変かなと考えています。こういう意味では、ハローワークとの情報提供があるということなんですが、そうしますと、ハローワークに行かなくても、ここでそれだけの情報が得られていくのか、ちょっとまずお聞きをしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"ただいまのご質問の件ですけれども、おっしゃいますとおり、ハローワークに行かなくても、ここの新しい新・シルバー人材センターにおいて相談窓口において情報が得られるという形になります。","voiceIndex":164,"id":"exchange-063"},{"speaker":"嶋委員","kind":"質問","question":"ちょっとハローワークに行くと、機械方式なので、今なかなか機械が苦手という方が多くて、大変ハローワークに行っても引き返して帰ってくるという方が多くて、私どもに相談に来る方が大変多いので、シルバー人材センターでやっていただくということは大変うれしいかと思いますが、このいわゆる開拓をしていく営業的なものは、仕事をもっとくださいということを品川区としてもどんどん品川区中の企業。","respondent":"蓼沼高齢事業課長","answer":"識字力のない方への紹介等のお話ですけれども、この職業紹介、あるいは求人の要求に当たりまして、人材センターのほうの窓口でガイダンスあるいは個別にカウンセラーという者もおりまして、カウンセリングを綿密に行いまして、求職者の方の適材ですとか。","voiceIndex":166,"id":"exchange-064"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味では、最寄りの駅とかというのがあると、高齢者の方でも、そこら辺だったら自分のところから通っていけるのかなというのが、そこまで要求をしていいのか、ちょっと私自身が見たときに地図を広げないとわからないという状況がありましたので、そういう仕事の一覧表みたいなものの中に、最寄りの駅みたいなのが、駅から何分とか、もしできるようでしたら、そこら辺まで要望したいと思うんですが。","respondent":"蓼沼高齢事業課長","answer":"求人側の情報につきましては、やはり求人票をもとにシステムとしてデータベースの中に落とし込んでいきますけれども、そのときに、そうしたような交通アクセスの関係等についてきめ細かな情報がなるべく入れられるように努力してまいりたいと思います。","voiceIndex":168,"id":"exchange-065"},{"speaker":"嶋委員","kind":"質問","question":"それとあと、これは私が聞いた、これはうわさかどうか、事実かどうかちょっとわからなかったんですが、たまたまシルバー人材センターに登録をしても、やっぱり人間関係であることなので、好き嫌いももちろんあるし、合うタイプ合わないタイプとあるんですが、言葉的に悪いんですけど、そこで差別をされる、いい仕事があるのに自分には回されなくて、違う人にというお話をちょっと聞いたことがあるんですが。","respondent":"蓼沼高齢事業課長","answer":"ただいまのお話ですけども、すみません、私はまだ直接伺っておりませんけれども、今回そういう意味では、新しく業務を付加して、いわば新・シルバー人材センターといっておりますけれども、新しくシルバー人材センターも生まれ変わるということで。","voiceIndex":170,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ほんとうに仕事を探して探して探しても、なかなか就職できないという方がほんとうに多いので、これがスムーズにいくとほんとうにいいなというふうに期待するところなんですが、この仕事確保、ここら辺のところの見通しというか、そこら辺のところの見通しと、どのように確保していく、先ほど求人開拓担当者がいるということなんですが、事業所3,５００というふうにここに書いていますけども。","respondent":"蓼沼高齢事業課長","answer":"それとあとは、独自にＰＲといいますか、チラシ等の作成、配布ですとか、広報ですとか、シルバー人材センターの中にホームページも立ち上げますので、そういった形で求人求職が適切に要望に合うようなものがそろうような形で進めてまいりたいと思います。","voiceIndex":173,"id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ仕事確保のところでご努力いただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-068"},{"speaker":"伊藤委員","kind":"質問・要望","question":"一つ、求人開拓員という説明があったんですけれども、この方の身分は、例えばシルバー人材センターの職員であるのか、もしくはそういうある程度経験を積んだプロの方を雇うのか、もしくは、外部の方と契約をしていくのかということのいろんな選択があるんですけれども、要は求人開拓の方がどれだけの仕事を見つけてくるかにかかっているわけですから。","respondent":"蓼沼高齢事業課長、新美保健高齢事業部長","answer":"職業開発、能力開発等ですけれども、これにつきましては、今民間の活力の活用といいますか、民間の人材の派遣の業務をやっている、あるいは職業紹介をやっているという。若干補足的にご説明をしますが、求人開拓員は現在４月１日付で今申し上げました新規に始めます社会福祉協議会にこれから紹介権を取得してまいりますので、そこのスタッフとして２名、これは１人は６０代の男性、もう一人は５６歳で。","voiceIndex":176,"id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、多分求職側のほうはそんなに心配しなくても集まってくるでしょうけど、受け取る企業がどれだけの企業があって、どういうニーズがあるかということをまさにこのお二人の方、でも、お二人で足りるのかなという気もするし、そこの強化を十分に費用対効果の面も考えながら進めていっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-070"},{"speaker":"須藤委員","kind":"質問","question":"私、外から見ていると、事業費というのは非常に都内でもすごい働きをしているんだけども、それに伴って、登録者も非常に増えてきちゃっているんで、今言ったように５回来たのが３回になっちゃう、２回になっちゃうというような話をちらっと聞いたんだけど、その辺はいかがでしょうか。","respondent":"蓼沼高齢事業課長、林（和）委員長","answer":"すみません、今手元に事業費とその仕事の件数のデータが出てまいりませんけれども、こういう形で新しい新規の展開をしていくですので。ほかにございませんか。ないようですので、６番目の「高齢者就業総合相談窓口」のプレオープンについての報告を終わります。一昨年の暮れにこういう健康マージャンを普及させております健康マージャンの協会、あるいは長寿社会文化協会から実施の要請等もありまして。","voiceIndex":180,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このカリキュラムというのは、どこでどういうふうに決められるのかということと、それからあと、こういう中身も入れてほしいとかというのがケアマネージャーの方は、いろいろと持っているのかなというふうな思いもあるんですが、そういう要望というのは聞いていただけるような場面というのはあるのかどうか、ちょっとお聞かせください。","respondent":"諸岡保健高齢事業部副参事","answer":"さらにコース終了時にも修了証を発行する予定でありまして、基本的に１年間を通して受講していただきますと、一番効果が上がるようなカリキュラムを組んでおりますが、いずれもお勤めの方ですので、勤務の都合であるとか。","voiceIndex":193,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"居宅介護支援事業者はほかにもあると思うんですけど、そこの方も対象なのかということと、そこで働いているケアマネージャーの方が何人ぐらいいるのかというのがわかったら教えていただきたいのと、それと、さっきのカリキュラムはどこで決められるのかということについてもお願いします。","respondent":"早津高齢福祉課長、諸岡保健高齢事業部副参事","answer":"前段のご質問については私のほうから。民間の居宅事業者も対象としています。支援センター等に限ったわけではございません。人数についてはちょっと私どもでは把握できておりません。カリキュラムですが、私どもでこれまでも何回も会議を持ちまして、実際に各コースで指導に当たっていただく先生方と私どもとで話し合いまして、それから対象者へのアンケート等に基づく受講生の要望等も踏まえまして。","voiceIndex":195,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"カリキュラムについては、いろいろ事前のアンケートもとられているということなので、ぜひ現場のところに即した中身というところで、大田区のところでお聞きしたところでは、大田区なんかはいろいろな保健センターごとに講習を組んでいて、１年間に４２回ぐらいやっていて、そこにどこでも参加できるという、そういう中身でやっているというふうなことをお聞きしたんですが。","respondent":"諸岡保健高齢事業部副参事","answer":"今年度、立ち上げで、初年度ですので、経費的な面で概算でしか出ない部分もあります。１年間を通してやってみまして、その成果を踏まえまして受講料設定につきましては、また来期等に検討してまいりたいというふうに思ってあります。","voiceIndex":198,"id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ区の補助とかも含めてご検討いただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-075"},{"speaker":"須藤委員","kind":"意見","question":"これは区内のお勤めの方ということなんで、それぞれの区内事業所の方との連携がスムーズにいっているのかどうかということと、それからその辺で先ほどの費用の面で、これだけの講師陣を集めて、この費用で１回2,０００円といったら、ちょっと逆に区の持ち出しが出てきたりとか、いろんな考えがあるんじゃないかなと思うんだけど、むしろこれだけ研修するから。","respondent":"諸岡保健高齢事業部副参事","answer":"品川区からの品川介護福祉専門学校への委託金としまして６００万円ございまして、残りが受講料で賄うというようなほぼ1,０００万円規模でこの事業につきましては予定をしています。区の委託金の中には、国あるいは都からの助成金もあります。","voiceIndex":201,"id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません。今６００万円の補助金の中で、国と都の助成もあって、全部が区の持ち出しではないということなんですが、ここのちょっと内訳がわかったら教えていただきたいんですが。","respondent":"早津高齢福祉課長","answer":"確定しているわけではございませんが、国が２分の１、都が４分の１という補助です。","voiceIndex":203,"id":"exchange-077"},{"speaker":"鶴副委員長","kind":"質問","question":"一つは、こういった受講料等の問題につきましては、安直に一般財源を品川区から持ち出すというようなことは軽々に言うべきではない。要するに、自分たちはいろんな技術を、あるいは理論を習得するために、ある程度のペイをしていかなきゃいけない。それはそれとして、ところで、この品川福祉カレッジの位置づけというのは、要するに介護福祉専門学校の付属校ですか、それとも併設校なんですか。","respondent":"諸岡保健高齢事業部副参事","answer":"大変難しいところですが、基本的には品川福祉カレッジは単独で学長もやっていただいておりますので、付属とかそういう関係ではなく、単独です。ただ、品川介護福祉専門学校と連携を図り、機能やネットワークの設備を利用する協力関係にあるということで理解をしております。","voiceIndex":205,"id":"exchange-078"},{"speaker":"鶴副委員長","kind":"意見","question":"そうすると、設置主体者は品川区が設置をすると。それで、運営は実は介護福祉専門学校が行うと、こういう形になっていますよね。そうすると、品川福祉カレッジというのは、各種学校なのか、ただ単なるカレッジ、カレッジというしかないんですけども、どういう位置づけなのかな。でも、学長さんがいると。だから、どういうふうにして分類しておけばいいのかなというふうに思うんですが。","respondent":"諸岡保健高齢事業部副参事","answer":"したがいまして、シルバー大学とかというようなこともありますが、同様な考え方に基づくものというふうにご理解いただければと考えています。","voiceIndex":207,"id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"来年度から郵送方式ということでご報告いただいたんですけど、これは郵送というのはどういう形でというか、希望者だけというふうになるのか、とりあえず全員に郵送ということになるのか、来年度ということなので、これからいろいろ検討するのかもわからないんですが。","respondent":"日下部障害者福祉課長","answer":"その辺につきましては、具体的にこれから検討を進めてまいります。ほかの状況を見ましても、いろいろな形を取り入れてやっておりますので、品川区として一番いい方法はどれかということで検討を進めてまいります。","voiceIndex":214,"id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このことについてはかなり要望も出されていて、私も質問させていただいたんですが、ぜひ期待しているところですので、よろしくお願いいたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3014#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":70387,"voices":217}},{"id":"h14-20020415-6","meetingId":"h14-cm04","date":"2002年4月15日","dateIso":"2002-04-15","committee":"区民委員会","time":"午後１時１６分～午後４時１３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問","question":"今ここで提示されたもので、すぐにじゃあ花輪をどうする、生ごみをどうするという話になっても、なかなかああだこうだとなるだけの話でまとまらないと思うんで、１回各会派に持ち帰らせていただいて、そこで意見を集約をして、その中で議論をしたらどうだろうかと思うんですが、いかがでしょう。ですから、そういう意味も含めて、どうだろうかなと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-001"},{"speaker":"本田委員","kind":"質問","question":"ですから、項目だけ書いてありますけれども、できれば次回の委員会などに、一応こういう線を考えているということを率直に出してもらって、各会派の意見を加える、または委員会の中で意見を加える。そういう基本的な議論はやってきているので、一度自分が今言ったような形をちょっと出してもらって、議論をしやすくしたほうがいいんではないかなと思うんですが、進め方としてどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-002"},{"speaker":"菊地委員","kind":"意見","question":"私も本田委員の意見にはもちろん賛成ですし、やはり一番こうやって示されると使用料のところが一番気になるところですし、委託の問題にしても、ある程度の線、これがばらばらに委員会の中で考えるということもなかなか無理があるんで、ある程度の考え方として示していただくほうが論議としてはしやすいのかなというふうに思いますけれども。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"私も今、本田、原委員も初めにもおっしゃっていたように、そういう取り扱いでいいんじゃないですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-004"},{"speaker":"金高委員","kind":"質問","question":"やはりこれだけのボリュームですから、我々も会派に戻っていろいろちょっと整理しながら意見を集約していきたいと思います。これだけの資料ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-005"},{"speaker":"石田副委員長","kind":"質問・要望","question":"今４月２６日に入札で着工していくという形で、完成の日にちもある程度ありますけれども、こっちの管理運営のものについては、今のお話だと６月末までにある程度まとめて連絡協議会に出して夏までというんだけれども、これを完成のどれぐらい前までにこういうものを出して、これで普通に入札をしていくとかいろんな方法があると思うんですけれども、そこら辺の流れというのかな。","respondent":"宮地区民課長","answer":"これがもう少し努力をして早まるようなことになりますと、４月が３月へ、３月は２月ということになってきますと、今度は平成１５年度中のオープンになりますので、そうしますと、やはり各組合、各区の分担金が平成１４年度中に１５年度予算編成しないといけなくなってきますので。","voiceIndex":26,"id":"exchange-006"},{"speaker":"石田副委員長","kind":"確認","question":"そうすると、ちょっと確認だけだけれども、５月８日ごろまでに、今さっき本田委員がおっしゃったある程度これは例えばこういうふうにしたいという希望が、例えば仮泊でもこれはできるようにしていきますとか、決まっているようなことが幾つかもうある程度方向性がありますよね。それというのはある程度資料というのは出てくると考えていいということなんでしょうか。","respondent":"宮地区民課長","answer":"私どものほうでちょっとワーキングの中でやった、そのくらいの資料でよろしければ、また議論の参考にもなろうかと思いますので、この委員会終了後、お出しします。","voiceIndex":28,"id":"exchange-007"},{"speaker":"原委員","kind":"確認","question":"そうすると、今のお話ですけれども、この次の委員会ではなくて、今のお話だと時間的にこの委員会の後に、すぐ出せるということですか。それを基本にして、我々はまた会派で議論ができるということなのかどうか、そこだけ確認したい。","respondent":"宮地区民課長","answer":"今の段階で整理はそんなにされていないんですけれども、こういう考え方もあるというふうな段階のもので、もし参考になるようでしたら、お出しすることはできます。","voiceIndex":30,"id":"exchange-008"},{"speaker":"金高委員","kind":"意見","question":"今のお話ですと、８日までという話ですけれども、できたら一定の日づけまでに切ってもらったほうが、この資料と一緒に持ち帰って会派と話ができますので、今の委員長のお話ですと８日までということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-009"},{"speaker":"石田副委員長","kind":"質問","question":"前回の区民委員会。我々が区民委員会の委員として自分たちの会派の中で説明をしていく上においても、一つこういうことがプラスになるのではないかというような考えもあって、もし行けるものであればという話があったので、これは委員会に諮って皆さんにお聞きをしたほうがいいんじゃないのかというような話が出たということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-010"},{"speaker":"原委員","kind":"意見","question":"基本的には、今私たち東京博善社なんかしょっちゅう行っていますから、状況的には見てはいますけれども、ただ、見方がやっぱりここに出されたような視点で見るというのと、またそういった葬儀で行くのと違うから、そういう意味では１回行かれたほうがいいんじゃないかなとは思うんですけれども。５月８日にはまずできないと思うし。そこのところだけだと思うんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"私のほうも同一規模のものであればぜひ見ておきたいというのはあるんですけれども、ここに示してくださったものだけが全部じゃないと思うんですけれども、きっと。近いところで、今神奈川県の大和市より近いところでもしというようなものがあるとすれば、そうしたところもちょっと考慮に入れて考えれればなというふうに思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-012"},{"speaker":"原委員","kind":"質問","question":"とにかく皆さんから意見を伺わせていただいて、日程的にとれればということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"ここのところ桐ヶ谷斎場を見たり、それから川崎のを個人的に見ておりますし、あと、三島は行かなかったんですけれども、府中も見てきたんですけれども、斎場をずっとこうあちこち新しいところを、ホテルみたいなところも見たりしておりますので、大体状況はこれまでの議論を含めてわかっているつもりですが、委員会として行きましょうというふうになれば、それはそれで構わないんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-014"},{"speaker":"本田委員","kind":"意見","question":"所管外になってしまうんですけれども、この立坑の役割と、なぜここに場所を選んだのか。もしわかれば。","respondent":"宮地区民課長","answer":"立坑の役割ですが、この立会川流域の浸水被害がかなり出ていたということで、その浸水被害の低減と、それから立会川の勝島運河のここのところも水質改善ということで以前から話がありまして、その水質改善を進めるための工事ですが、その立坑を掘りまして。","voiceIndex":51,"id":"exchange-015"},{"speaker":"本田委員","kind":"質問・要望","question":"第二幹線をつくって、今の問題が解決するというふうに本当に付近住民の念願していることですから、早くこれはつくってほしいという要望が一方ではあるわけですね。今のご説明によると。立坑というのは１カ所だけになるんですか。運河の中に。そういう、この場所でなければならないという必然性が工法上どうしてもあるのかなという、そこを聞きたかったんです。所管外で申しわけないんですけれども。","respondent":"金井環境課長","answer":"埋め立てのときも私はそこの埋め立てをやっておりまして、かなり前ですが。基本的にここが立坑の発信基地ということで、ちょうど下水道幹線の中心を通ることになります。ポンプ場を下流のほうに確かつくる予定になっておりますので、海辺のほうにですね。","voiceIndex":53,"id":"exchange-016"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、付近住民の皆さんへの説明、それから交通渋滞だ、特に朝夕の緩和の策等をやらないと、立会川周辺が大変な交通問題が起きてくる可能性が十分あります。この図面で言いますと。ですから、その辺の対策を十分に立てていただきたい。そういうことで近隣住民への説明をきちっとやって、万全な対策を講じていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと２点ばかり確認をさせていただきたいんですけれども、先ほどのなぎさ会館の閉館の話で、それは半月に限定されているものなのかどうかちょっとお聞きしたいんですが。それからもう一つは、ここの立坑の、要するに駐車スペース２７台になったときに誘導員を２人つけるんですよね。１０年間２人つけるんだということになるんですか。どうなんですか。","respondent":"宮地区民課長","answer":"葬儀社の対応ですけれども、今協定葬儀をやっている品川区の場合は、品川支部のほうの方には近々委員会の報告が終わりましてからということでご連絡をする予定です。それから、館のほうにもポスター、それから広報にも載せる予定で考えております。","voiceIndex":56,"id":"exchange-018"},{"speaker":"原委員","kind":"意見","question":"そうすると、この閉館中の葬儀については、おのおのの町会でやってもらえるのか、あるいはどこか応援を立てないとという話になると思うんですが、その辺はどうしますか。","respondent":"宮地区民課長","answer":"これから町会、地域センターを通じていろいろとお話しする機会があろうかと思いますので、日にちが確定次第、何らかの形で区民の皆様にもお知らせできるように考えていきたいと思います。","voiceIndex":58,"id":"exchange-019"},{"speaker":"原委員","kind":"確認","question":"そのスタート時点はそのまま固定で、ずっと例えば７年なら７年、５年なら５年を加味していくわけですよね。そうすると、その間に下がったり上がったりするものについては一切影響なくやっていけるということなのか、ちょっと確認を。","respondent":"市川産業振興課長","answer":"急に一気に０.５％も上がるとかまずございませんので、そんなような状況ですので、財政的にも大体当初予算の見込みの中で処置、対応してきている。","voiceIndex":66,"id":"exchange-020"},{"speaker":"原委員","kind":"質問・要望","question":"金利が今の状況では低い状況の中でそのように行われているわけですが、各企業にすると、非常に今の経済状況が厳しい中で、できるだけ低いところで抑えてほしいなと。区の利子補給もそういう中で一応行われているわけですから、それをうまくかみ合わせて、その中で対応していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"今回全体的に０.３％、ご本人の負担が上昇されたんですけれども、区のほうでいろいろな論議を重ねてこういう形になってきたんでしょうけれども、別の考え方というか、課長のほうで別の考え方というと、結局は区がこの０.３％について区で利子補給をしていくかどうかということに集中しちゃうのかもしれませんけれども、別の考え方として、もしこの話の中であったのであれば。","respondent":"市川産業振興課長","answer":"それで、その分を利子補給という考え方をとらせていただければ、本来の利子補給の半分、それから利用者の半分という負担割合、これが実質とれたんじゃないかというような一応検討の経過があります。","voiceIndex":69,"id":"exchange-022"},{"speaker":"本田委員","kind":"質問・要望","question":"この事業そのものは今の状況に合った形で積極的に進めていっていただきたいと思うんですけれども、この財産変換についてはどこでやるんですか。","respondent":"市川産業振興課長","answer":"したがいまして、この産業振興課の所管事業の施設づくりというところで普通財産を活用していくという筋立てになりますので、今委員の言われた財産処分ということで、総務委員会に諮るということは現在のところ考えてございません。","voiceIndex":77,"id":"exchange-023"},{"speaker":"本田委員","kind":"質問","question":"そうすると、今ずっと内容が説明されて、この２階、３階のフロア、占有が５００平米ぐらいで、ワンフロアで２７０平米、これを１００平米にするか５０平米にするか、いろいろ使い方を今検討しているということなんですけれども、この辺の等価交換は適切なのかなどうなのかなということを率直にこう感じるんですがね。この辺はどこでその辺の評価判断はするんですか。所管だけでやっているわけですか。","respondent":"市川産業振興課長","answer":"区としていかに有効な床面積をいわばこの事業の中でとれるかということで、昨年来管財部門とそれから都市計画課が窓口になって開発事業者のほうと協議を進めてきてあります。","voiceIndex":79,"id":"exchange-024"},{"speaker":"本田委員","kind":"質問・要望","question":"これほど評価が落ちているわけですから。この事業がそういう意味で、財産管理上も問題が起きないように適切に進めなくちゃならないなというふうに思っておりますので、その辺のところは十分気をつけてと言ったら変ですけれども、配慮して進めていただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-025"},{"speaker":"原委員","kind":"質問","question":"この独立支援事業なんですけれども、これは第２の創業ということですよね。それはさっきもご説明あったとおり。例えばこの会社のこの部分はどうなのかとか、あるいはこの会社のこの分社化は適切なのかどうなのかという情報がいろいろ出てくると思うんだけれども、その辺はどう整理をされていくわけですか。","respondent":"市川産業振興課長","answer":"提携の仕方はいろいろあろうかと思いますが、その辺は今後検討させていただきたいと思いますが、会社のほうから何らかの形で共同してやっていこうと、協調して、共同、協調してやっていこうというようなことも寄せられていますので、いずれにしても。","voiceIndex":82,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"事業内容で「優れた経営資源を有する事業者」と書いてあるんですが、これは具体的にちょっとよくわからないんですけれども、これを教えていただきたいのが１点と、あと今、原委員からも出たんですけれども、実際にこのビルができました。","respondent":"市川産業振興課長","answer":"それと、やはり新しいマーケットに敏感に対応している企業であること、これもやはり大きな選択肢になります。","voiceIndex":84,"id":"exchange-027"},{"speaker":"金高委員","kind":"質問・要望","question":"課長の説明で、新しいタイプの製造業の進出ということが最後にありましたけれども、具体的にどういう。ＩＴなんかもそうですけれども、その辺をもうちょっと具体的に新しいタイプの製造業というのを教えていただきたいと思います。","respondent":"市川産業振興課長","answer":"それとか、あと消臭剤、においを消す消臭剤ですね、科学的な消臭剤でなくて、自然界の要素をもとにした消臭剤をつくっているメーカー、これは専門のメーカーと、それからカーテン製造の会社が新分野進出ということで。","voiceIndex":86,"id":"exchange-028"},{"speaker":"石田副委員長","kind":"確認","question":"ちょっと確認だけしたいんですけれども、今等価交換方式でやっていかれるということで、１０月ごろ着工されていくという話がありました。森ビルのところが６億５,０００万円で、建築費が約３０億かかって、これも森ビルから出ていくということは、建設に伴うすべてのこと、またあとはビルの管理から含めてすべて森ビルで業者選定から行っていくという理解でいいのかという確認をまず。","respondent":"市川産業振興課長","answer":"今までの森ビルというか、実際に開発するのは森ビルの子会社でサンウッドという会社ですけれども、子会社と区との協議の中では、今後のこの事業の効果的な進め方というか、効率などを考えた場合に、今副委員長が言われましたけれども。","voiceIndex":88,"id":"exchange-029"},{"speaker":"石田副委員長","kind":"確認","question":"もう１点だけ確認しますが、すべてそういう形になると、今まで時価評価が３億９,０００万でも何でもあるけれども、それと等価交換だからそれでもいいんだけれども、基本的に使えるところは５４０平米なわけですけれども、５４０平米をある程度３億９,０００万円の土地の６２４平米を５４０平米のこの占有面積にして、それを区民の今こういった創業支援という形でお貸しをしていく。","respondent":"市川産業振興課長","answer":"天王洲地区のいわゆる家賃相場との兼ね合いの中で、私ども区の事業としてやる中で、どこまで要するに政策的な使用料の減額と申しましょうか、一定のものを区が持つわけですけれども、どの部分を持つか、ランニングコストの部分なのか、本体の家賃部分なのか。","voiceIndex":90,"id":"exchange-030"},{"speaker":"石田副委員長","kind":"質問・要望","question":"使い勝手の問題も必ず出てくるでしょうし、そうすると、そこら辺で、この形で行くと、今等価交換という形だから、代替えにくれるということだから、品川区のお金は出さないで、そちらサイドでやってというと、どうしてもそっちのサイドの話になりやすいんだろうなと、自分たち、ここで例えば変な話、２４階建てのほとんどの部分は自分のところで貸していくわけだから。","respondent":"市川産業振興課長","answer":"いずれにしても、もう１点のテナントの、テナント側のニーズがどのくらいあるのかということが今年度の調査研究の中で具体的に当たっていきたいと思ってございまして、ただ、西大井のベンチャー創業支援に比較いたしますと。","voiceIndex":92,"id":"exchange-031"},{"speaker":"本田委員","kind":"質問","question":"職員も区役所に来た方々も。そういうのは。この数字を実現していくのは。考えてみたりしているのか。職員とその区民に対する、また他の区内事業者に対するＩＳＯの取得のいろいろな手だてについての各種の支援みたいなところは進めているわけですけれども、そういうシステムの開発が今進んでいるということですので、何かそういうようなこともやってみたらどうかなと思うんですけれども、どうでしょうか。","respondent":"宍戸ＩＳＯ担当課長","answer":"それをさらに区民とか事業者の方にどう啓発していくのかということに関しましては、もう少しお時間をいただきまして、今年度環境基本計画、行動計画を策定するということになってありますので、そういった中で検討してまいりたいというふうに考えております。","voiceIndex":104,"id":"exchange-032"},{"speaker":"本田委員","kind":"質問","question":"検討するということですから、排出量が一目瞭然、ぱっとわかるというので、そういう視覚に訴えるやり方、職員の皆さんは今言われたようなデータをそれは見ればわかるでしょうけれども、かといって全職員がいつもそこに目が行っているというふうな形。それをつけるのにまた金がかかるというようなことがあるのかもしれませんけれども、検討してみたらどうかなというふうに思うんですがね。","respondent":"金井環境課長","answer":"そういう意味では、私どもそういうものがあれば、できるだけうまく活用できればというふうに今後考えていきたいなというふうに思っておりますので、十分参考にさせていただきたいというふうに思います。","voiceIndex":106,"id":"exchange-033"},{"speaker":"本田委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。昨日の読売新聞の記事では、東京電力と三菱電機がタイアップして契約して、一般家庭の中でわかるようにというものを、そういうシステムをやったという記事ですが、ほかのメーカーもいろいろと研究しているというふうに聞いておりますので、そういうこともぜひ取り入れたらいかがかと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"その中では、こういう形のものをこういうふうにいろいろ羅列をされてあります。それで、第１段階で目標とするもの、第２段階で取り組みとするものという形で分けてあるんだけれども、現実にこれをこういう形でしたときに、これはその計算式に当てはめていくと、これだけになりますよという形になるんですか。","respondent":"宍戸ＩＳＯ担当課長","answer":"したがいまして、両方ともたまたま同じ数値なものですから、３％、３％、こちらも６％、６％ということなので、両方とも温室効果ガスの削減目標が３％、６％というふうになっていますけれども、計算式に入れていくと、ほかに地方や何かですと。","voiceIndex":109,"id":"exchange-035"},{"speaker":"原委員","kind":"質問","question":"今のこの計算式に絡んでの話はわかるんだけれども、この取り組み内容がですね、逆に言うと、このパーセントを削減するのにどういう役割というか、これをやっていけば、そのパーセントを削減する役割になるのかどうかというところなんですけれども。それがそういう形で出されたときには必ず削減につながってくるんだと、６％以上削減されるんだというもとでこれを出されてきているわけなんでしょうか。","respondent":"宍戸ＩＳＯ担当課長","answer":"そのときに省エネ型のタイプの機器にすることが想定できるといったようなことを含めまして、平成１８年度に向けて、どのぐらい削減できるだろうかというのをある程度計算して積み上げた数値です。","voiceIndex":111,"id":"exchange-036"},{"speaker":"原委員","kind":"質問","question":"この数字はそうなんですけれども、ここに実行すべき内容が書いてありますね、取り組みすべき内容。それは積み上げてから６％以上になるよというような話なんですか。それともこれは最低限やるべきことで、もっともっといろいろなことがあるのよということになるのでしょうか。","respondent":"宍戸ＩＳＯ担当課長","answer":"だから、かなり上のほうの目標に向かって、背伸びしないと６％にならないよという数値ではなくて、ある程度こういうふうな形でいけば、６％というのはある程度クリアできるんじゃないかという積み上げを本当にした数値です。","voiceIndex":113,"id":"exchange-037"},{"speaker":"原委員","kind":"意見","question":"ちょっと行き違いがあるみたいなんで、その取り組みと、要するにパーセンテージの問題で、こうやって取り組んでいったときに、その積み上げが６％だというような説明はわかったんですけれども、その取り組みはもっといろいろな方法がありますよね。","respondent":"金井環境課長","answer":"それで、こちらの５ページ、６ページに今、原委員がおっしゃったように、いろいろ取り組み方があります。そのほかにどのようなものがあるのかというのは、基本的には現在これで可能であるという判断です。これからまた施策が、低減方式がいろいろ出てくると思います。","voiceIndex":116,"id":"exchange-038"},{"speaker":"石田副委員長","kind":"質問","question":"例えばこの第１段階の目標で、平成１５年度で６％以上削減できたというときは、この計画を平成１２年度でこれを９％にするのか１０％にするのか、１２年度比で。そこら辺の計画の変更というか、この率先実行計画というのは随時１年ごとというか２年ごとというか、これは５年のスパンだけれども、その計画変更というのは随時行っていくという考えでいいわけですか。","respondent":"宍戸ＩＳＯ担当課長","answer":"それが継続的改善という部分です。","voiceIndex":118,"id":"exchange-039"},{"speaker":"石田副委員長","kind":"質問","question":"もう１点だけ。そういうところのものが区の中で見えないなというところに対しては、何か考えがあって、もっとこういうふうに、もっとぽんと自治体としてやるというお考えとか計画とかいうのがあるのかどうかというところをお聞きしたいんです。","respondent":"宍戸ＩＳＯ担当課長","answer":"したがいまして、今回の６％も、あまり上を見過ぎた数値ではなくて、ある程度かたい線ということで６％にしたわけですけれども、いろいろな考え方、それからこれから区民、事業者にアピールしていくというのがＩＳＯの一つの目標ですので、そうした点も加味しながら。","voiceIndex":120,"id":"exchange-040"},{"speaker":"原委員","kind":"質問","question":"箱根はヴィムからフジランドに変わったでしょう。日光の光林荘も変わりましたよね。その辺の経緯もちょっとお話し願えればと思います。内容的なものは別としても、ちょっと変わったということについては新聞か何かに公表されていますよね。その辺をちょっと。それからもう一つ、保養所は行政のほうに報告義務はどの辺まであるんですか。","respondent":"宮地区民課長","answer":"光林荘ですけれども、本日の文教委員会で、同じくこのようなその他の中でご報告をしていますが、やはりヴィムからミートランドという株式会社に、宇都宮の会社だそうですけれども変更になっております。","voiceIndex":129,"id":"exchange-041"},{"speaker":"原委員","kind":"質問","question":"外へ出てくださいと、外に出られたお客さんもいたようですけれども、一番大変だったのはお風呂に入っていた人が外へ出られなかったということだったんですけれども、ただ、そういったときに、これはたまたま今品川荘の問題になって、ほかのところもやっぱりそういった、細かいかもしれないけれども、ある意味では人命にかかわる問題が出てくる可能性も出てくるわけで、そこのところの対応なんですが。","respondent":"宮地区民課長","answer":"ご報告をするタイミングなんですけれども、報告自体もまだ原因が調査中ということでしたので、大事に至らぬ点もあったことで、ちょっと今回報告事項をさせていただきませんでしたけれども、今後そういうことを含めまして、あまりこんなことがあってはいけないんですけれども。","voiceIndex":131,"id":"exchange-042"},{"speaker":"菊地委員","kind":"質問","question":"１カ月ぐらい前に働いている方が、皆さんあと１カ月ですよと言われて、私が相談を受けた方は近々結婚するんだけれども困っているんだなんていう話をしていましたけれども、区がどこまで関与できるのかというのはちょっとわからないのですけれども、働いていらっしゃる方が業者がかわることで一気に職を失うということがあるんですけれども、その辺で。","respondent":"宮地区民課長","answer":"新しい業者にその条件をつけるようなことはできませんが、今回たまたまヴィムからフジランドに変わったときには、従来勤めている人は雇用をしていただけましたので、その点は問題はなかったんですけれども、支配人の方も含めて。","voiceIndex":134,"id":"exchange-043"},{"speaker":"菊地委員","kind":"意見","question":"そういう形でこの仕事として確保できていけば、よりいいんでしょうけれども、先ほど話したように、私が相談を受けた場合は、もうそこで全部一度仕事としてはなくなってしまうということがあって、区が実際に業務として委託をしてきた業者ですし、実際にそこで働いてきた皆さんですし、そういう方たちがある程度職業としてそこでやっていけるような、さっき言ったように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-044"},{"speaker":"原委員","kind":"確認","question":"一つだけ確認したいんですけれども、ここの三つのところで区の職員は何人いますか。いませんか。","respondent":"宮地区民課長","answer":"品川荘だけあと３人区の職員がおります。箱根荘はもう既に職員はおりません。光林荘も３人です。","voiceIndex":137,"id":"exchange-045"},{"speaker":"石田副委員長","kind":"質問","question":"一つだけいいですか。これは項目がずっと出てきているんですけれども、これ以外の項目自体というのはなかったのかな。","respondent":"宮地区民課長","answer":"最後に交通アクセスとつけ加えさせていただいてありますけれども、それは前回区民委員会で、ここでご議論いただいたのを申し伝えまして、そういう形でちょっと入れていただきましたけれども、かなりワーキングでは一応いろんなテーマが出てきましたので。","voiceIndex":153,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2322#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":47045,"voices":155}},{"id":"h14-20020415-8","meetingId":"h14-cm04","date":"2002年4月15日","dateIso":"2002-04-15","committee":"建設委員会","time":"午後１時１６分～午後２時３５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"ちょっとお尋ねしたいんですが、今の関係なんですが、登記している方が少ないということですが、これは後で伺いますけれども、その前に、地元の有志の方が協議会みたいなことをつくるとかという動きがあったように聞いているんですが、そういうところで、区のほうに何か要望みたいなことを出されていることがあれば、教えていただけませんか。","respondent":"中島街路事業担当課長","answer":"第１回の協議会につきましては、４月１１日、木曜日に開催してございまして、そのときには、区民の皆さんの参加をいただいたと聞いております。区民の方々も含めまして、７３名が参加されたと聞いてあります。","voiceIndex":13,"id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"もうちょっとお尋ねしたいんですが、今後、どういう形になるのか、これから測量説明会だとか、補償説明会とかなっていくかと思うんですけれども、勉強会というと、ちょっと表現は悪いのかもしれませんが、そういう協議会だと思うんです。あるいは、何かできるのか、できないのか、そこら辺はどうなんでしょうか。","respondent":"中島街路事業担当課長","answer":"私のほうでは、多分、要綱整備がされれば、要綱に基づきまして補助金等の手当、あるいは講師派遣ができるんじゃないかと考えています。","voiceIndex":15,"id":"exchange-002"},{"speaker":"上山委員","kind":"質問・要望","question":"これは要望にいたしますけれども、商店街とのかかわりがありますので、特に産業振興課などとも詰めて、横の連絡をとっていただいて、対策協議会の役員の方々も商店街の方が多いと思いますので、そこら辺、よく連絡を取り合って、いずれでもうまくやっていただきたいと考えていますので、これは要望にとどめておきます、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"地元で協議会を設置して、今後、進めていくわけですけれども、いわゆる個別買収ではなくて、私ちょっと聞いたんだけれども、商店街そのものを何らかの形で残していこうということで、面的な整備というんでしょうか、一体的な整備というんですか、そういう声だとか、動きというのはあるんですかということが一つ。","respondent":"中島街路事業担当課長","answer":"４月８日にも勉強会をしてございまして、現在、大体、毎回１０名前後お集まりいただいたわけですけれども、再開発の説明が一区切りついてありますので、実際にコンサルタントの方が入っているんですけれども、今後、その方が直接エリアのほうに出かけて行って、意向等。","voiceIndex":18,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"北地区というのはどこだか、私これを見てもよくわからないんですが、北というと区役所寄りかという気がするんですけれども、そこら辺も含めてお尋ねしたい。今の事業費の関係で、国が２分の１、それから都市計画交付金と財調ということだったんですけれども、これの割合が、４分の１、４分の１なのか、わかれば教えてください。","respondent":"中島街路事業担当課長","answer":"要するに計画線の左側の左側というんですか、そちらのエリアを考えてあります。実際に、再開発する地域は約２,８００m2のエリアを、現時点では考えてあります。","voiceIndex":20,"id":"exchange-005"},{"speaker":"上山委員","kind":"質問","question":"年間、何回かあるかと思うんですけれども、昨年の５月ごろにもやったと思うんですけれども、大体、いつもこのぐらいだったんでしょうか。いろいろあってこうなったと思うんですけれども、それがいいとか悪いとか言うんではなくて、大体このぐらいの数だったんでしょうか。去年あたりの様子がわかれば教えていただければと思うんです。","respondent":"田村住宅課長","answer":"平成１３年５月の実績で言いますと、大崎、八潮、東品川と南品川のスーパーリフォームを含めまして１４戸ということです。そういう意味では、今回は八潮団地６戸ということで、半分ぐらいです。","voiceIndex":31,"id":"exchange-006"},{"speaker":"上山委員","kind":"意見","question":"６戸ではあまりにも、この部分について、品川区が悪すぎるとは言いませんよ。全体的に非常に少ないなと思います。ある人から、何年もなかなか入れないと相談を受けましたが、ぜひ、このことについては、都にも働きかけていただいて、全体で品川区がとるわけにもいかないと思いますけれども、何らかの形でないのかなと思います、感想だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-007"},{"speaker":"辻委員","kind":"質問","question":"若年ファミリー向け４５戸というのは、これは新築なのか、あき家なのか、どうなんですか。","respondent":"田村住宅課長","answer":"昨年１２月に定期借家権を設けましたが、それとはちょっと意味が違いまして、若年ファミリー向けで、内容的にはあき家住宅です。","voiceIndex":34,"id":"exchange-008"},{"speaker":"辻委員","kind":"意見","question":"それからもう一つ、あき家ですが、これは登録制になっているんですが、この１年間で、全体的に入るのに待ったけどだめだったということがあると聞いている。要するに新しく建て替える場合には、いつ入居できるかがわかるが、あき家はそうはいかない。ここのところの傾向としては、品川区は、都営住宅に当たった後にどうなっているのかはわからないだろうけど、要するにどういう状況なのか。","respondent":"田村住宅課長","answer":"ただ、東京都のほうも、今ですと長期滞納者への強制執行、高額所得者への立ち退き、あるいは、使用承継の問題など、本来入るべき方々が入居できないという形で、都においても都営住宅の抜本的な改革に取り組んでおります。","voiceIndex":36,"id":"exchange-009"},{"speaker":"辻委員","kind":"質問","question":"登録というのは期限があるんですか。１年たつと、もう１回やらなくちゃいけなくなる。","respondent":"田村住宅課長","answer":"前は、登録というのは１年と明記されていたんですが、最近は、やはりそういう部分で、特に期間について明記されてない。実際には、前にも建設委員会でご質問がありましたが、東京都のほうにも品川区の説明をしましたら、登録された方については、必ずあっ旋をするということです。","voiceIndex":38,"id":"exchange-010"},{"speaker":"辻委員","kind":"質問・要望","question":"去年も当たった人がずっと待っていて、まだ全部入ったかどうかわからないけれども、今年また６戸出てくる。どういう状況にあるのかということが、相手待ちというか、出ていかなきゃしようがないというのがあるとしても、この辺、都にどうなんですかって聞いたって、ちょっとという感じになっちゃう部分があるんで、ひとつよろしくお願いします。相談にのっていただくよう要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"たしか、品川区で、都営住宅というのは総数で２,０００戸ぐらいですか、ちょっとわからないんですけれども、それぐらいの割合として、八潮の６戸のみというこの見通しなんですけれども、どういう基準でやっているのかというのがよくわからないんですよ。都がやることだから、よくわからないのかもしれないんですけれども、ちょっとわかったら教えてほしいんですけれども。","respondent":"田村住宅課長","answer":"ですから、やはり都全体では２６万戸の住宅があって、現実にあきが出ていればすぐにわかりますが、このぐらいのあきが生じるだろうということであき家発生率を見込んで、八潮の６戸だけでありますが、その辺の割り振りについては、今回の報告だけで、１年トータルしたときに。","voiceIndex":41,"id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"ポイント方式は、ずれてやっていく、これは基本的にはあき家ですよね。これがずれるというのはわかるんですけれども、例えば、先ほどの道路の移転用地みたいなものを、道路拡幅だとか、あるいは開発だとか、そういうものが多いと、あき家が出ても、そちら用に確保しちゃうんじゃないのかなという気がするんですけど、そういうことはあまり反映されないんですか、これは。","respondent":"田村住宅課長","answer":"ただ、私どものほうで、東京都全体の募集が、事業用として幾ら確保した残りなのかは、正直言いましてわかりませんので、現実にどういう基準になっているのか、そこまでちょっと承知していないということです。","voiceIndex":43,"id":"exchange-013"},{"speaker":"築舘委員","kind":"質問","question":"あき家になるというのは、やっぱりその原因があると思うんですけれども、収入が超過していて、それを隠していて、住宅に住んでいたり、それがわかりそれで出るような件数が含まれているのか。その辺のところを厳しくやってもらいたいという風潮になっておりましても、実際に、都のことだから詳しくはわからないと思いますが、それがわかれば教えてください。","respondent":"田村住宅課長","answer":"数字的にも、たしか過去１０年ぐらい載っていましたけれども、かなりの数です。先ほどもお話ししましたように、今後、都では都営住宅の抜本的見直しを進めていますので、さらに適正な管理を進めていくと考えております。","voiceIndex":45,"id":"exchange-014"},{"speaker":"築舘委員","kind":"質問","question":"その前に、例えば調査的なことで、品川区にある都営住宅に関しての区のかかわり方があるのかどうか。その後のそういうことを住宅課でやっているんですか。その辺、調整的なことを主にやっている課というんですか、課が直接やっているのか、直接はできないので、第三者がやっているのか、その辺の事情がわかれば教えてください。","respondent":"田村住宅課長、山室住宅指導担当部長","answer":"区内にある都営住宅の管理については、やはり都がやっております。区の場合には、もちろん都から移管を受けました区営住宅がありますので、東京都住宅局とは絶えず連携をとりながら、作業を進めているところです。若干、補足をします。都営住宅の滞納、ないし高額所得者対応は、基本的には住宅供給公社のほうに事務を代行させているという状況です。","voiceIndex":47,"id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと制度全体のことだとかですが、利用件数がどれぐらいで、その中で、戸建て住宅と共同住宅の区分けみたいのがわかっていれば、ちょっと教えていただけますか。","respondent":"田村住宅課長","answer":"工事内容につきましては千差万別でございまして、リフォームだとか、１戸建てですと、屋根の修繕工事、外構の基礎工事、あるいは、屋根の塗り替えとか、床の修理、壁紙張り替え、ベランダのペンキ塗りの工事ということで、いろいろな工事が件数の中に出ているという状況です。","voiceIndex":55,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問・要望","question":"勤労者生活基金が３件の事業実績で、効率が悪いというので、今度、廃止されたということで、何かその水域に入ってきたような実績で、ちょっと不安なんですね。廃止だなんていうことにならないように、所管として広げていくようによろしくお願いしたいと思います、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-017"},{"speaker":"辻委員","kind":"質問","question":"大体、普通の家で、例えば太陽光発電を設置して、どのぐらいの総額になるんですか。","respondent":"田村住宅課長","answer":"いろいろな業者で出していますので、やはり３００万円ぐらいの金額になるかと思います。太陽光システムの設置だと、kw単価が毎年変化しているということで、若干下がり目で動いていますので、今後kwを購入しても、単価を見ていくと、下がり傾向にあるのかなという感じです。","voiceIndex":63,"id":"exchange-018"},{"speaker":"辻委員","kind":"質問","question":"問題は、太陽光あたりに絞っていけば、確かにそうかもしれない、価格については。この事業期間は平成１５年３月３１日と固定しているんですか。新規事業なんだけれども、どういう意味合いなんでしょうか、平成１５年３月３１日までに工事が完了するということは。","respondent":"田村住宅課長","answer":"これは単年度単位の事業ではございませんで、ずっと続く事業です。要は、予算が年度ですので、助成金を出す場合には、あくまで年度で完了して、今年度の分として助成を出すということです。そのまま中抜けしないで、来年の４月から来年度予算で対応するということです。","voiceIndex":65,"id":"exchange-019"},{"speaker":"辻委員","kind":"質問","question":"先ほど、値段を聞いたのは、例えば１４０万円を超えて、実際にやりましょうというときに、環境課を含め、まちづくりのために、これから大いにやってもらいたい事業でもあるわけですよ。１４０万円でやりましょうというときに、１５万円を限度で助成されるんだけど、じゃあ、残りはどうするのか。どっちが得をするんですか。例えば、ちょうど１４０万円だったとしますよね。この辺はどうなんですか。","respondent":"田村住宅課長","answer":"究極の選択で、どっちにするのかということですが、今回はあくまでサンプル住宅で、特に太陽光と、熱温水器という２点に絞ったので、当然、修繕全体で修築しながらそれを設置したいというような形は、先ほど、申し上げたように、額的にも修築が７００万円なんで。","voiceIndex":67,"id":"exchange-020"},{"speaker":"辻委員","kind":"質問","question":"そこのところはもうちょっと違った見方もあると思うんだけども。もう一つは、先ほど沢田委員もちらっと言ったけど、私も同じマンション住まいですけれども、マンションでひとつこういうことをやってみようじゃないかと、屋上でですけど、少し間をあけて屋上のあいているところに置こうじゃないかといったときに、マンションの管理組合の申込みは大丈夫なんですか。","respondent":"田村住宅課長","answer":"基本的には、先ほどの修築資金も同様なんですが、マンションの専有部分、または共用部分も、管理組合で了承されていれば、その分、あくまで個人が申込みになりますので、その証明さえ取れれば、考え方としてできることになります。","voiceIndex":69,"id":"exchange-021"},{"speaker":"辻委員","kind":"質問","question":"助成金額を５％、１５万円限度とするんじゃなくて、融資制度もあるんだったら、これも品川区でやっていくものである。それで、太陽光、あるいは温水器に人は関心を持つ、また、よしやってみようとやっていただけるほうが、事業評価はどうかというと、私は、そっちのほうがあると思う。実績が上がらないのだったら、そういう方法も考ていってもいいのではどうなんでしょうかということを言っているわけです。","respondent":"山室住宅指導担当部長","answer":"ただ、くどいようですけれども、戸建て住宅等でまずモデル的にやっていただいて、環境施策が、住宅施策としても少しずつ広がっていくような取り組みを今後できないかというふうな期待を、我々も大きな願いを持ってこれから進めていこうかということですので、ぜひ。","voiceIndex":71,"id":"exchange-022"},{"speaker":"沢田委員","kind":"質問","question":"太陽光発電というのは、国のほうもかなりありますよね。三、四例あるんじゃないですか。ちょっと、そこいらを説明していただけますか。","respondent":"田村住宅課長","answer":"国のエネルギー財団のほうですと、１kw当たり１２万円の補助金が、上限は９.９９k wまで受けられるということですので、１kwですので、単純に９倍しても、国のほうは１０８万円ぐらい、１０倍しても１２０万円なんで、kwの補助事業として。","voiceIndex":73,"id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、計算がよくわからないんですが、さっき、３kwで１４０万円から３００万円ということだったんですが、これは１kw当たり１２万円ですから、３kwというと３６万円。それプラス、品川区の最高１５万円までということで、これはダブルでいいわけですね。","respondent":"田村住宅課長","answer":"そのとおりです。","voiceIndex":75,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問・要望","question":"それからもう１点、環境問題をやった場合に、例えば、トイレに雨水を導入するものだとか、屋上緑化は、今度、制度化されましたけれども、そういう問題だとか、家の問題はちょっと違いますけれども、場合によってはバイオを取り込むごみ処理、いろいろな環境に関連した住宅にまつわるものというのはあるんだけれども、それぞれ個別にやるんではなくて、一つの制度に集約して、例えば。","respondent":"田村住宅課長","answer":"一定の成果が出た部分は、一定の整理統合というような形で、住宅でくくるのか、あるいは環境に類するものでくくるのか、そこら辺も含めて、将来的には検討していかなきゃいけないと考えています。","voiceIndex":77,"id":"exchange-025"},{"speaker":"沢田委員","kind":"質問・要望","question":"売電も、そこで発電したもので余剰のものを売るということもできますよね、今は。ですから、そういうことも含めて、ある程度、この制度がある以上、こういうパンフレットがあるとか、この問い合わせは品川区でやらないにしても、ここへ行けば大丈夫だとかというような体制をしっかりして、それも含めて広報をしていただきたいなという要望を述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-026"},{"speaker":"辻委員","kind":"確認","question":"これは建築確認が必要だとあるんですが、太陽光や温水器の中で要件は大丈夫なんですか、普通の戸建てで。建築確認だ何だというのは、どのぐらいの規模ですか。ただ畳の１畳か２畳ぐらいのは建築確認なんか要らない。","respondent":"田平建築課長","answer":"ある程度、一定規模以上になりますと、４００万円とか５００万円かかるということですと、それ相応の配管設備があります。そうすると、建築設備としての工事完了届並びに検査済証が必要になってくる。","voiceIndex":80,"id":"exchange-027"},{"speaker":"辻委員","kind":"確認","question":"温水器は最近やってますねときどき、屋根の上に乗って確認みたいな。今、はじめて聞いたけど、そう言えばそうなんだと。提出書類を後になって言うんじゃないんですよね、事前に説明に来たときに、区の意見はこうですよというのは、建築課のほうと事前協議をもっとやっていただいて、後になってだめだと言うことがないよう関連課と調整してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-028"},{"speaker":"横山副委員長","kind":"質問","question":"荏原管内でも、小山、小山台、西小山、こういった部分は安全だということではなくて、やはりこれと同じようにヒヤリ地図というのがあるんだと思うんですけれども、警察署管内は、これ１通で間に合わせているんですか。状況的には、この４枚で済ませちゃうということですか。","respondent":"奈良交通安全担当課長","answer":"一応、平成１３年度予算でやっております。各年度で、各警察署管内１カ所ということで、それが１０年度分で４０カ所やって、トータルで品川区内のヒヤリ地図ができ上がるです。平成１３年度分で、これでお終りです。","voiceIndex":88,"id":"exchange-029"},{"speaker":"横山副委員長","kind":"質問","question":"確かに、後地小学校あたりに行っても、西小山に行ったって、ヒヤリというか、現に事故がたくさんあるところはあるわけですから、もう少し小さくても、全体を把握できなければと思うんですけれども、年に何町会ですか、１０年間を張り合わせて品川区全体ができ上がるというのは、何かちょっと腑に落ちないような気がするんですけど。","respondent":"奈良交通安全担当課長","answer":"学校につきましては、これに該当する管内の小学校、あるいは保育園に配布するということでございまして、それで順次配布していくですので、よろしくお願いします。","voiceIndex":90,"id":"exchange-030"},{"speaker":"築舘委員","kind":"質問","question":"それに関連して、八潮は東京水上警察署なんですよ。だから、品川区ということでやっていることですけれども、やっぱり全体をある程度やってもらわないと困るんですね。警察署管内でやっていても、これは品川区として責任を持ってやっているわけですから、それで対応されても困る。だから、そこの部分は、次の年度で予算をとってやりますというのならいいんですけれども、そこを聞きたい。","respondent":"岩田管理工事課長","answer":"なぜ、こんなふうにちょっとずつやるのかということですけれども、今まで、実際に事故が起きた現場に入っておりますけれども、事故が起きた現場については、所管の警察と、区のほうで原因を究明して、ハード的な対策で対応できるようなものが何があるかということを。","voiceIndex":92,"id":"exchange-031"},{"speaker":"上山委員","kind":"質問・要望","question":"ちょっと要望なんですけれども、今、管理工事課長のほうからお話があったんですが、１０年間というとかなり、細かくつぶしていくということになれば、なるのかもしれませんけれども、１０年経って、比較ということもないかと思うんですけれども、また大分状況が変わっていくことも多いと思うんです。交通の状況だとか、事故だけじゃなくて。ちょっとそこで、考え方はどうなんでしょうか。","respondent":"岩田管理工事課長","answer":"やり方は今後、いろいろＩＴも進んでおりますし、特に交通事故の現場というのは、毎年変化してまいりますので、そういった意味では、確かに、毎年こういう紙ベースのやり方で１０年もかけてちんたらという感じはしますので、今後、コンピュータも活用できるかどうか。","voiceIndex":94,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3716#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":22137,"voices":99}}]);
